INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25778, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或身体轻轻碰一下。", "primary_collocate": null, "pronunciation": "qīng chù", "ipa": "tɕʰiŋ˥ tʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "他轻触我的手臂，让我小声点。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈轻触孩子的额头，看他发烧没有。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用脚尖轻触水面，觉得有点凉。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师轻触了一下我的桌子，提醒我别睡。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫用鼻子轻触我的手，想要吃的。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我轻触他的肩，他回头看了看我。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩伸出手，轻触着那只小鸟。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在路上轻触我的背，指了指前面。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他轻触过那幅画，被保安提醒了。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞者的手指轻触地面，然后慢慢站起来。", "target_word": "轻触", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "轻触了", "label": "完成体"}, {"form": "轻触过", "label": "经历体"}, {"form": "轻触着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "用手或身体轻碰一下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9799c0aa-2ee0-4905-9cb8-472d94641281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25778, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轻触", "is_correct": true, "explanation": "正确答案：轻触（qīng chù）指用手或身体轻轻碰一下。"}, {"text": "清除", "is_correct": false, "explanation": "chú（第二声）与 chù（第四声）声调不同，意思是除去、去掉，与轻轻碰到无关。"}, {"text": "清楚", "is_correct": false, "explanation": "chǔ（第三声）与 chù（第四声）声调不同，意思是明白、清晰。"}, {"text": "请出", "is_correct": false, "explanation": "qǐng（第三声）与 qīng（第一声）、chū（第一声）与 chù（第四声）声调都不同，意思是请某人出来。"}, {"text": "清出", "is_correct": false, "explanation": "chū（第一声）与 chù（第四声）声调不同，意思是清理后移出。"}], "explanations": {"轻触": "正确答案：轻触（qīng chù）指用手或身体轻轻碰一下。", "清除": "chú（第二声）与 chù（第四声）声调不同，意思是除去、去掉，与轻轻碰到无关。", "清楚": "chǔ（第三声）与 chù（第四声）声调不同，意思是明白、清晰。", "请出": "qǐng（第三声）与 qīng（第一声）、chū（第一声）与 chù（第四声）声调都不同，意思是请某人出来。", "清出": "chū（第一声）与 chù（第四声）声调不同，意思是清理后移出。"}, "sentence_index": null, "correct_answer": "轻触"}, "level_3": {"options": [{"text": "轻触", "is_correct": true, "explanation": "正确：“轻触我的手臂”指轻轻碰一下手臂，符合“让我小声点”的轻柔提醒。"}, {"text": "割", "is_correct": false, "explanation": "语义：割伤手臂与“让我小声点”的提醒毫不相关，也不是轻碰。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬手臂不是提醒对方小声点的轻柔动作，与语境不符。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：“拥抱”多用于人与人之间，不说拥抱手臂。"}], "explanations": {"轻触": "正确：“轻触我的手臂”指轻轻碰一下手臂，符合“让我小声点”的轻柔提醒。", "割": "语义：割伤手臂与“让我小声点”的提醒毫不相关，也不是轻碰。", "咬": "语义：咬手臂不是提醒对方小声点的轻柔动作，与语境不符。", "拥抱": "搭配：“拥抱”多用于人与人之间，不说拥抱手臂。"}, "sentence_index": 0, "correct_answer": "轻触"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力轻触了窗户，把玻璃震碎了。", "explanation": "这里误用了〈轻触〉：它只指轻轻碰一下，不能表示用力震碎玻璃；用力碰撞应说〈碰撞〉。"}, {"text": "货车轻触了路边的电线杆，电线杆倒了。", "explanation": "这里应该用〈撞〉。撞指用力碰撞，轻触只指轻轻接触，不能写货车撞倒电线杆。"}, {"text": "妈妈轻触了这道题，题目很快就做完了。", "explanation": "这里误用了〈轻触〉：它只指身体或物体的轻轻接触，不能表示做题；此处应说〈解答〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻触", "is_correct": true, "explanation": "正确：“伸出手，轻触着那只小鸟”指用手轻轻碰着小鸟，与前文的动作一致。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：摧毁与“伸出手”的轻柔动作和温柔的情景不符。"}, {"text": "挥舞", "is_correct": false, "explanation": "搭配：“挥舞”需要物品作宾语，不说挥舞一只小鸟。"}, {"text": "杀死", "is_correct": false, "explanation": "语义：杀死小鸟与句中温柔的情景相悖，不符合语境。"}], "explanations": {"轻触": "正确：“伸出手，轻触着那只小鸟”指用手轻轻碰着小鸟，与前文的动作一致。", "摧毁": "语义：摧毁与“伸出手”的轻柔动作和温柔的情景不符。", "挥舞": "搭配：“挥舞”需要物品作宾语，不说挥舞一只小鸟。", "杀死": "语义：杀死小鸟与句中温柔的情景相悖，不符合语境。"}, "sentence_index": 6, "correct_answer": "轻触"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他轻触了整整一夜，天亮时还没有结束。", "explanation": "这里误用了〈轻触〉：它指瞬间的轻轻碰一下，不能表示持续一整夜的动作；此处应说〈守〉。"}, {"text": "大风轻触了我的房子，房子倒了。", "explanation": "这里误用了〈轻触〉：它表示轻轻碰一下，不能表示把房子吹倒；此处应说〈吹倒〉。"}, {"text": "台风轻触了我们的城市，很多房子都倒了。", "explanation": "这里应该用〈袭击〉。轻触只指用手或身体轻轻碰一下，不能表示台风造成的大范围破坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他轻触了着我的手臂，我没有躲开。", "corrected_sentence": "他轻触着我的手臂，我没有躲开。", "error_description": "体标重复：“轻触”后只能用一个体标；“了”与“着”不能同时出现，应说“轻触着”表示持续。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈轻触一下了孩子的额头，问他冷不冷。", "corrected_sentence": "妈妈轻触了一下孩子的额头，问他冷不冷。", "error_description": "“了”位置错误：应说“轻触了一下”，“了”紧跟“轻触”；“轻触一下了”语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
