INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情一步步的顺序。", "primary_collocate": null, "pronunciation": "liú chéng", "ipa": "ljoʊ˧˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个工作的流程很简单。", "target_word": "流程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，请先把流程看一遍。", "target_word": "流程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的每个流程都有人检查。", "target_word": "流程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买火车票的流程是什么？", "target_word": "流程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给新同事讲了做菜的流程。", "target_word": "流程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的流程太长，要改一改。", "target_word": "流程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住院的流程我不太清楚。", "target_word": "流程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照流程做，就不会出错。", "target_word": "流程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理让我们把流程写下来。", "target_word": "流程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个流程一共有五步。", "target_word": "流程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个流程", "label": "量词（个）"}, {"form": "一套流程", "label": "量词（套）"}, {"form": "工作流程", "label": "复合词"}, {"form": "流程图", "label": "复合词"}], "register": "中性", "sense_fingerprint": "流程：名词，工作或事情进行的先后步骤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be7eb40f-7d8a-4232-9c49-ff679e0a5a7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流程", "is_correct": true, "explanation": "“流程”指做事的先后步骤，“这个工作的流程很简单”搭配自然。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”一般说“好”或“坏”，不说“很简单”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷热阴晴，与工作的难易无关，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不用“简单”来形容，“颜色很简单”不通。"}], "explanations": {"流程": "“流程”指做事的先后步骤，“这个工作的流程很简单”搭配自然。", "脾气": "搭配：“脾气”一般说“好”或“坏”，不说“很简单”。", "天气": "语义：“天气”指冷热阴晴，与工作的难易无关，句意不通。", "颜色": "搭配：“颜色”不用“简单”来形容，“颜色很简单”不通。"}, "sentence_index": 0, "correct_answer": "流程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃掉了这个流程。", "explanation": "这里把“流程”误当成了“食物”一类可以吃的东西；“流程”指做事的先后步骤，是抽象的，不能吃。"}, {"text": "这个流程很会唱歌。", "explanation": "这里把“流程”当成了会唱歌的人；“流程”指做事的先后步骤，是抽象的，不会唱歌。"}, {"text": "他把这个流程的重量称了一下。", "explanation": "这里把“流程”误当成了可以称重的“货物”；“流程”指做事的先后步骤，是抽象的，没有重量，不能称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流程", "is_correct": true, "explanation": "“流程”指做事的先后步骤，“住院的流程我不太清楚”搭配自然。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体的高矮，与住院的步骤无关，句意不通。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”不说“住院的性格”，与住院的程序不相关。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”与住院的步骤无关，“住院的声音”句意不通。"}], "explanations": {"流程": "“流程”指做事的先后步骤，“住院的流程我不太清楚”搭配自然。", "身高": "语义：“身高”指身体的高矮，与住院的步骤无关，句意不通。", "性格": "搭配：“性格”不说“住院的性格”，与住院的程序不相关。", "声音": "语义：“声音”与住院的步骤无关，“住院的声音”句意不通。"}, "sentence_index": 6, "correct_answer": "流程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台流程一共有五步。", "explanation": "这里应该用〈个〉。“台”用于机器、设备等，流程不是机器，不能用“台”来计量。"}, {"text": "这位流程一共有五步。", "explanation": "“位”只用于人，流程不是人，不能用“位”来计量。"}, {"text": "这匹流程一共有五步。", "explanation": "“匹”用于马等牲畜，流程不能用“匹”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把流程改了好。", "corrected_sentence": "我们把流程改好了。", "error_description": "错误形式“改了好”，正确形式“改好了”。结果补语“好”应紧跟动词“改”，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们制定了一根新流程。", "corrected_sentence": "我们制定了一套新流程。", "error_description": "错误形式“一根新流程”，正确形式“一套新流程”。“流程”的量词是“套”或“个”，“根”用于细长的物体，不能用于流程。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
