INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25788, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西里有多少水。", "primary_collocate": null, "pronunciation": "hán shuǐ liàng", "ipa": "xan˧˥ ʂweɪ˨˩˦ liɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "米的含水量太高，容易坏。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看看这盆土的含水量。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，地里的含水量明显增加了。", "target_word": "含水量", "complexity_tier": "T3", "furigana": "hán shuǐ liàng", "sentence_source": "generated"}, {"text": "干果的含水量很低。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄瓜的含水量大概有九成。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服的含水量太多，还没干。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们比较两种叶子的含水量。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "含水量高的木头不适合做家具。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些面粉的含水量偏高，要晾干再存。", "target_word": "含水量", "complexity_tier": "T3", "furigana": "hán shuǐ liàng", "sentence_source": "generated"}, {"text": "沙漠里的土含水量非常低。", "target_word": "含水量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西里水分的多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9799c0aa-2ee0-4905-9cb8-472d94641281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "含水量", "is_correct": true, "explanation": "含水量：米所含水分太多，容易变质，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是水分的多少，“米的颜色太高”不成立。"}, {"text": "长度", "is_correct": false, "explanation": "语义：长度与米是否容易坏无关，且“太高”不用来描述长度。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：味道一般说“浓”“淡”，不说“太高”。"}], "explanations": {"含水量": "含水量：米所含水分太多，容易变质，与句意相符。", "颜色": "语义：颜色不是水分的多少，“米的颜色太高”不成立。", "长度": "语义：长度与米是否容易坏无关，且“太高”不用来描述长度。", "味道": "搭配：味道一般说“浓”“淡”，不说“太高”。"}, "sentence_index": 0, "correct_answer": "含水量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "运动以后，要及时补充含水量。", "explanation": "这里应该用〈水分〉。含水量指物体所含水分的比例，补充的是水分本身。"}, {"text": "这种饮料的糖分含水量很高，喝起来很甜。", "explanation": "这里应该用〈含量〉。含水量指东西里所含水分的多少，“糖分”的多少要用含量。"}, {"text": "这个月的含水量很大，雨下得很多。", "explanation": "这里应该用〈雨量〉。含水量说的是物体所含水分，一段时间的降雨多少要用雨量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "含水量", "is_correct": true, "explanation": "含水量：比较两种叶子，指的是所含水分的多少，与句意相符。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：叶子没有脾气，无法拿来比较。"}, {"text": "心情", "is_correct": false, "explanation": "语义：叶子没有心情，句中要比较的是水分。"}, {"text": "心跳", "is_correct": false, "explanation": "搭配：“心跳”只用于有心脏的生物，叶子不说心跳。"}], "explanations": {"含水量": "含水量：比较两种叶子，指的是所含水分的多少，与句意相符。", "脾气": "语义：叶子没有脾气，无法拿来比较。", "心情": "语义：叶子没有心情，句中要比较的是水分。", "心跳": "搭配：“心跳”只用于有心脏的生物，叶子不说心跳。"}, "sentence_index": 6, "correct_answer": "含水量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的含水量很高，观众都很激动。", "explanation": "这里不能用〈含水量〉。含水量指物体所含水分的多少，比赛不是物体，没有含水量。"}, {"text": "他的性格含水量很高，大家都很喜欢他。", "explanation": "这里不能用〈含水量〉。含水量指物体所含水分的多少，性格不含水分，不能这样说。"}, {"text": "老师给我们看了一根含水量。", "explanation": "量词“根”用于细长的东西，不能用来修饰“含水量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这袋大米的含水量高很，容易坏。", "corrected_sentence": "这袋大米的含水量很高，容易坏。", "error_description": "错误：“很”应放在“高”前作状语，说“很高”，不能说“高很”。正确应为“含水量很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块木板的一只含水量很高，不能马上刷漆。", "corrected_sentence": "这块木板的含水量很高，不能马上刷漆。", "error_description": "错误：量词“只”用于动物或成对的东西，不能修饰抽象的“含水量”。正确应为不加量词，说“这块木板的含水量很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
