INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25790, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放在一起，让它们能用。", "primary_collocate": null, "pronunciation": "pèi zhì", "ipa": "pʰei˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "公司给每个人配置了一台新电脑。", "target_word": "配置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给每间教室配置了一套音响设备。", "target_word": "配置", "complexity_tier": "T3", "furigana": "xué xiào gěi měi jiān jiào shì pèi zhì le yí tào yīn xiǎng shè bèi", "sentence_source": "generated"}, {"text": "他把实验室的仪器合理配置好了。", "target_word": "配置", "complexity_tier": "T3", "furigana": "tā bǎ shí yàn shì de yí qì hé lǐ pèi zhì hǎo le", "sentence_source": "generated"}, {"text": "医院为新病房配置了很多新设备。", "target_word": "配置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂为每条生产线配置了一台检测仪。", "target_word": "配置", "complexity_tier": "T3", "furigana": "gōng chǎng wèi měi tiáo shēng chǎn xiàn pèi zhì le yì tái jiǎn cè yí", "sentence_source": "generated"}, {"text": "他正在给新手机配置网络。", "target_word": "配置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把新机器的参数配置好了才能开机。", "target_word": "配置", "complexity_tier": "T3", "furigana": "gōng rén bǎ xīn jī qì de cān shù pèi zhì hǎo le cái néng kāi jī", "sentence_source": "generated"}, {"text": "工厂要合理配置机器，才能多做产品。", "target_word": "配置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间配置了空调和电视。", "target_word": "配置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程队正在为新项目配置设备。", "target_word": "配置", "complexity_tier": "T3", "furigana": "gōng chéng duì zhèng zài wèi xīn xiàng mù pèi zhì shè bèi", "sentence_source": "generated"}], "morphological_forms": [{"form": "配置了", "label": "体标"}, {"form": "配置好", "label": "结果补语"}], "register": "通用", "sense_fingerprint": "把设备、人员等合理安排在一起使其可用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f217853e-c44a-4a7e-bf9e-9fbe27715e66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25790, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "配置", "is_correct": true, "explanation": "正确答案，pèi zhì，意思是把东西安排在一起使其能用。"}, {"text": "培植", "is_correct": false, "explanation": "培植（péi zhí）与配置（pèi zhì）两个音节的声调都不同，意思是培育栽培植物。"}, {"text": "配饰", "is_correct": false, "explanation": "配饰（pèi shì）与配置（pèi zhì）只差声母（zh 与 sh），意思是装饰用的物件。"}, {"text": "皮质", "is_correct": false, "explanation": "皮质（pí zhì）与配置（pèi zhì）韵母和声调都不同，意思是皮层的物质。"}], "explanations": {"配置": "正确答案，pèi zhì，意思是把东西安排在一起使其能用。", "培植": "培植（péi zhí）与配置（pèi zhì）两个音节的声调都不同，意思是培育栽培植物。", "配饰": "配饰（pèi shì）与配置（pèi zhì）只差声母（zh 与 sh），意思是装饰用的物件。", "皮质": "皮质（pí zhì）与配置（pèi zhì）韵母和声调都不同，意思是皮层的物质。"}, "sentence_index": null, "correct_answer": "配置"}, "level_3": {"options": [{"text": "配置", "is_correct": true, "explanation": "正确答案。“配置”指把电脑配给每个人，与语境相合。"}, {"text": "抄写", "is_correct": false, "explanation": "语义：“抄写”是把文字誊写一遍，不能用于给人配给电脑。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”多用于枝叶、头发，不能与“电脑”搭配。"}, {"text": "品尝", "is_correct": false, "explanation": "配价：“品尝”的宾语应是食物，不能带“电脑”作宾语。"}], "explanations": {"配置": "正确答案。“配置”指把电脑配给每个人，与语境相合。", "抄写": "语义：“抄写”是把文字誊写一遍，不能用于给人配给电脑。", "修剪": "搭配：“修剪”多用于枝叶、头发，不能与“电脑”搭配。", "品尝": "配价：“品尝”的宾语应是食物，不能带“电脑”作宾语。"}, "sentence_index": 0, "correct_answer": "配置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校配置了一场比赛。", "explanation": "这里应该用〈举办〉。配置指安排设备、物品，不用于组织活动。"}, {"text": "农民配置了小麦。", "explanation": "这里应该用〈种植〉。配置用于设备、人员的安排，不用于栽种作物。"}, {"text": "老师配置了学生的问题。", "explanation": "这里应该用〈解决〉。配置不表示处理问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配置", "is_correct": true, "explanation": "正确答案。“配置好了”指参数设置完毕，与“开机”的前提相合。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：“清洗”是洗涤，不能用于参数。"}, {"text": "煮", "is_correct": false, "explanation": "配价：“煮”的宾语应是食物，不能带“参数”作宾语。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于擦拭表面，与“参数”不搭配。"}], "explanations": {"配置": "正确答案。“配置好了”指参数设置完毕，与“开机”的前提相合。", "清洗": "语义：“清洗”是洗涤，不能用于参数。", "煮": "配价：“煮”的宾语应是食物，不能带“参数”作宾语。", "擦": "搭配：“擦”用于擦拭表面，与“参数”不搭配。"}, "sentence_index": 6, "correct_answer": "配置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程队正在配置新大楼。", "explanation": "这里应该用〈建造〉。配置指安排设备、物品，不表示建造房屋。"}, {"text": "工人配置了墙壁。", "explanation": "这里应该用〈粉刷〉。配置不用于涂抹墙面。"}, {"text": "医院配置了很多病人。", "explanation": "这里应该用〈接诊〉。配置用于设备、人员的安排，不用于接待病人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们给这间会议室配置了一投影仪。", "corrected_sentence": "我们给这间会议室配置了一台投影仪。", "error_description": "“投影仪”前用“一”时要带量词“台”，应说“一台投影仪”，不能说“一投影仪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店员已经把新电脑配置了好。", "corrected_sentence": "店员已经把新电脑配置好了。", "error_description": "结果补语“好”应紧跟动词，说“配置好了”；“配置了好”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
