INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种细菌，它不需要空气就能活。", "primary_collocate": null, "pronunciation": "yàn yǎng jūn", "ipa": "jɛn˥˩ jɑŋ˨˩˦ tɕyn˥˥", "syllable_count": 3, "sentences": [{"text": "厌氧菌是一种不需要空气的细菌。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的细菌喜欢空气，厌氧菌却怕空气。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把盖子盖紧，里面没有空气，厌氧菌就能活。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厌氧菌住在泥土深处，那里没有空气。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的肚子里也有厌氧菌。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厌氧菌很小，要用显微镜才能看到。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水池的底部没有空气，厌氧菌喜欢住在那里。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，厌氧菌不用呼吸空气也能活着。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子盖得很紧，里面长出了厌氧菌。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厌氧菌和我们不一样，它不需要空气。", "target_word": "厌氧菌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "专性厌氧菌", "label": "复合"}, {"form": "厭氧菌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不需要空气也能活的细菌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b564bc7-abf7-40ec-96cb-cfa30e5b9152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厌氧菌", "is_correct": true, "explanation": "“厌氧菌”不需要空气，符合“不需要空气的”这一描述。"}, {"text": "好氧菌", "is_correct": false, "explanation": "语义：好氧菌需要空气，与“不需要空气”直接矛盾。"}, {"text": "氧气", "is_correct": false, "explanation": "搭配：“是一种……”后应接生物类名词，“氧气”是气体，不搭配。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "语义：蝴蝶是需要呼吸空气的昆虫，与“不需要空气的”相矛盾。"}], "explanations": {"厌氧菌": "“厌氧菌”不需要空气，符合“不需要空气的”这一描述。", "好氧菌": "语义：好氧菌需要空气，与“不需要空气”直接矛盾。", "氧气": "搭配：“是一种……”后应接生物类名词，“氧气”是气体，不搭配。", "蝴蝶": "语义：蝴蝶是需要呼吸空气的昆虫，与“不需要空气的”相矛盾。"}, "sentence_index": 0, "correct_answer": "厌氧菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "土壤表层的厌氧菌需要大量空气。", "explanation": "这里应该用〈好氧菌〉。厌氧菌不需要空气，需要大量空气的是好氧菌。"}, {"text": "我用厌氧菌织了一件毛衣。", "explanation": "这里应该用〈毛线〉。厌氧菌是细菌，不能当毛线织毛衣。"}, {"text": "厌氧菌是一种会开花的植物。", "explanation": "这里应该用〈细菌〉。厌氧菌是细菌，属于微生物，不是植物，不会开花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厌氧菌", "is_correct": true, "explanation": "“厌氧菌”不需要空气，能在没有空气的底部生活，符合语境。"}, {"text": "人类", "is_correct": false, "explanation": "语义：人需要呼吸空气，与“没有空气”的语境矛盾，人不能在池底生活。"}, {"text": "植物", "is_correct": false, "explanation": "搭配：“住”的主语一般是动物或微生物，植物不说“住在”。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象需要呼吸空气，与“没有空气”的语境矛盾。"}], "explanations": {"厌氧菌": "“厌氧菌”不需要空气，能在没有空气的底部生活，符合语境。", "人类": "语义：人需要呼吸空气，与“没有空气”的语境矛盾，人不能在池底生活。", "植物": "搭配：“住”的主语一般是动物或微生物，植物不说“住在”。", "大象": "语义：大象需要呼吸空气，与“没有空气”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "厌氧菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面包放久了，表面会长出厌氧菌。", "explanation": "这里应该用〈霉菌〉。厌氧菌不需要空气，面包表面有空气，厌氧菌难以在那里生长，霉菌却常在那里生长。"}, {"text": "酵母在有氧的环境中繁殖得很快，厌氧菌也一样。", "explanation": "这里应该用〈需氧菌〉。厌氧菌不需要空气，不能像需氧菌那样在有氧环境中快速繁殖。"}, {"text": "香菇属于厌氧菌。", "explanation": "这里应该用〈真菌〉。香菇是真菌，不能归入厌氧菌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "泥土深处有一块厌氧菌。", "corrected_sentence": "泥土深处有一种厌氧菌。", "error_description": "量词错误：“块”用于块状物，厌氧菌应用“种”。应改为“一种厌氧菌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在罐子底部发现了一位厌氧菌。", "corrected_sentence": "我在罐子底部发现了一种厌氧菌。", "error_description": "量词错误：“位”用于人，厌氧菌应用“种”。应改为“一种厌氧菌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
