INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25799, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把敌人全部打死。", "primary_collocate": null, "pronunciation": "miè shā", "ipa": "mjɛ˥˩ ʂa˥", "syllable_count": 2, "sentences": [{"text": "我军灭杀了来犯的敌人。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们灭杀了山上所有的敌人。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场伏击战灭杀了一千多名敌人。", "target_word": "灭杀", "complexity_tier": "T3", "furigana": "zhè chǎng fú jī zhàn miè shā le yì qiān duō míng dí rén", "sentence_source": "generated"}, {"text": "我们要在天黑前灭杀这些敌人。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着队伍灭杀了城里的敌人。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大军进山，要灭杀所有的敌人。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争中，他们灭杀过很多敌人。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老将军说，要把敌人全部灭杀。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勇敢的战士灭杀了敌人的先头部队。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支小队夜里灭杀了守城的敌兵。", "target_word": "灭杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灭杀了", "label": "体标"}, {"form": "灭杀过", "label": "体标"}, {"form": "滅殺", "label": "繁体"}], "register": "书面", "sense_fingerprint": "灭杀：战争中把敌人全部打死", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b564bc7-abf7-40ec-96cb-cfa30e5b9152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灭杀", "is_correct": true, "explanation": "本词：指战争中把来犯的敌人全部打死，符合句意。"}, {"text": "驯服", "is_correct": false, "explanation": "搭配：“驯服”多用于动物，不能用于来犯的敌人。"}, {"text": "解救", "is_correct": false, "explanation": "语义：“解救”指使人脱离危险，与打击来犯敌人的语境相反。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”表示欢迎到来的人，用于来犯的敌人与句意不合。"}], "explanations": {"灭杀": "本词：指战争中把来犯的敌人全部打死，符合句意。", "驯服": "搭配：“驯服”多用于动物，不能用于来犯的敌人。", "解救": "语义：“解救”指使人脱离危险，与打击来犯敌人的语境相反。", "迎接": "语义：“迎接”表示欢迎到来的人，用于来犯的敌人与句意不合。"}, "sentence_index": 0, "correct_answer": "灭杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要在天黑前灭杀这些朋友。", "explanation": "这里应该用〈接待〉。灭杀指把敌人全部打死，朋友不是敌人，不能用灭杀。"}, {"text": "我军灭杀了那座粮仓。", "explanation": "这里应该用〈占领〉。灭杀的对象是敌方人员，不能用于粮仓等地点。"}, {"text": "工人在天黑前灭杀了这台机器。", "explanation": "这里应该用〈关闭〉。灭杀指把敌人全部打死，机器不是敌人，也不是生物，不能用灭杀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灭杀", "is_correct": true, "explanation": "本词：加“过”表示经历，指战争中消灭很多敌人，符合句意。"}, {"text": "款待", "is_correct": false, "explanation": "语义：“款待”是热情招待，与战争中杀敌的语境相反。"}, {"text": "赠送", "is_correct": false, "explanation": "语义：“赠送”指把东西送给人，不能用于敌人。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”多用于动物，不能以敌人作宾语。"}], "explanations": {"灭杀": "本词：加“过”表示经历，指战争中消灭很多敌人，符合句意。", "款待": "语义：“款待”是热情招待，与战争中杀敌的语境相反。", "赠送": "语义：“赠送”指把东西送给人，不能用于敌人。", "饲养": "搭配：“饲养”多用于动物，不能以敌人作宾语。"}, "sentence_index": 6, "correct_answer": "灭杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支小队夜里灭杀了城里的粮草。", "explanation": "这里应该用〈焚毁〉。灭杀的对象是敌人或有害生物，粮草不是。"}, {"text": "士兵灭杀了被困的平民。", "explanation": "这里应该用〈救出〉。灭杀指打死敌人，不能用于被困的平民。"}, {"text": "消防员灭杀了厨房里的大火。", "explanation": "这里应该用〈扑灭〉。灭杀的对象是敌人或有害生物，火不是。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我军再灭杀了来犯的敌人。", "corrected_sentence": "我军又灭杀了来犯的敌人。", "error_description": "错误形式是副词“再”。“再”表示尚未发生的重复，不能用于已完成的动作；已完成的重复应用“又”。正确形式是「我军又灭杀了来犯的敌人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支小队夜里很灭杀了守城的几名敌兵。", "corrected_sentence": "这支小队夜里灭杀了守城的几名敌兵。", "error_description": "“很”是程度副词，不能修饰动作动词“灭杀”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
