INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "盖板是盖住东西的板子。", "primary_collocate": null, "pronunciation": "gài bǎn", "ipa": "kai˥˩ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "盖板盖在箱子上，里面的东西很干净。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把盖板放在井口上。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盖板是塑料做的，一点也不重。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要踩这块盖板，它会坏的。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器的盖板打不开，我们看不到里面的问题。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下水道的盖板是铁做的。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，把桶的盖板吹走了。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一块旧盖板做了小桌子。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖板上落满了灰，好久没人打开了。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖板太小，盖不住这个箱子。", "target_word": "盖板", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "一块盖板", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "盖在箱子、井口等上面的板子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d26fe1-76de-4d72-b2de-845fecb9db9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25802, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盖板", "is_correct": true, "explanation": "正确：盖板是盖住东西的板子。"}, {"text": "改版", "is_correct": false, "explanation": "gǎi（第三声）与 gài（第四声）声调不同，意思是修改版本。"}, {"text": "再版", "is_correct": false, "explanation": "zài 与 gài 声母不同（z / g），意思是再次出版。"}, {"text": "盖碗", "is_correct": false, "explanation": "wǎn 与 bǎn 声母不同（w / b），意思是带盖的茶碗。"}, {"text": "盖满", "is_correct": false, "explanation": "mǎn 与 bǎn 声母不同（m / b），是动补短语，不是名词。"}], "explanations": {"盖板": "正确：盖板是盖住东西的板子。", "改版": "gǎi（第三声）与 gài（第四声）声调不同，意思是修改版本。", "再版": "zài 与 gài 声母不同（z / g），意思是再次出版。", "盖碗": "wǎn 与 bǎn 声母不同（w / b），意思是带盖的茶碗。", "盖满": "mǎn 与 bǎn 声母不同（m / b），是动补短语，不是名词。"}, "sentence_index": null, "correct_answer": "盖板"}, "level_3": {"options": [{"text": "底板", "is_correct": false, "explanation": "语义：底板在箱子底下，不能盖在箱子上。"}, {"text": "红茶", "is_correct": false, "explanation": "语义：红茶是饮品，不能盖在箱子上。"}, {"text": "盖板", "is_correct": true, "explanation": "正确：盖在箱子上的板子，与“里面的东西很干净”语境相符。"}, {"text": "墙砖", "is_correct": false, "explanation": "搭配：墙砖用于贴墙面，不说“盖在箱子上”。"}], "explanations": {"底板": "语义：底板在箱子底下，不能盖在箱子上。", "红茶": "语义：红茶是饮品，不能盖在箱子上。", "盖板": "正确：盖在箱子上的板子，与“里面的东西很干净”语境相符。", "墙砖": "搭配：墙砖用于贴墙面，不说“盖在箱子上”。"}, "sentence_index": 0, "correct_answer": "盖板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个罐子的盖板拧得很紧，里面的东西不会洒出来。", "explanation": "这里应该用〈盖子〉。盖板指板状部件，拧在罐口的盖子不说盖板。"}, {"text": "这间屋子的盖板是木头做的，走上去很舒服。", "explanation": "这里应该用〈地板〉。盖板是盖在开口或沟上的板，铺在地面的木板说地板。"}, {"text": "冷的时候，她把一块盖板拉到身上取暖。", "explanation": "这里应该用〈被子〉。盖板是硬的板状部件，不指软的被子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔不是桶的部件，与“桶的”不相合。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不能作为桶上的部件被风吹走。"}, {"text": "木柴", "is_correct": false, "explanation": "搭配：“桶的木柴”不成立，木柴不是桶的组成部分。"}, {"text": "盖板", "is_correct": true, "explanation": "正确：桶的盖板被风吹走，符合语境。"}], "explanations": {"钢笔": "语义：钢笔不是桶的部件，与“桶的”不相合。", "咖啡": "语义：咖啡是饮品，不能作为桶上的部件被风吹走。", "木柴": "搭配：“桶的木柴”不成立，木柴不是桶的组成部分。", "盖板": "正确：桶的盖板被风吹走，符合语境。"}, "sentence_index": 6, "correct_answer": "盖板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子的盖板很平，可以写字。", "explanation": "这里应该用〈桌面〉。盖板指盖住开口或东西的板，桌子的台面不说盖板。"}, {"text": "切菜的时候要用盖板，不要直接放在桌上。", "explanation": "这里应该用〈砧板〉。盖板指盖住开口的板，切菜用的板子说砧板。"}, {"text": "他把盖板当成窗帘挂在窗户上。", "explanation": "这里应该用〈布帘〉。盖板是硬的板状部件，不指挂在窗户上的软布帘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桶口放着一只盖板，灰尘进不去。", "corrected_sentence": "桶口放着一块盖板，灰尘进不去。", "error_description": "量词错误：盖板应用“块”，不用“只”。“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根盖板太薄了，一踩就碎。", "corrected_sentence": "这块盖板太薄了，一踩就碎。", "error_description": "量词错误：盖板是板状物，应用“块”，“根”用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
