INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25804, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "历时就是一件事情从开始到结束用了多长时间。", "primary_collocate": null, "pronunciation": "lì shí", "ipa": "li˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这项工程历时三年完成。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场战争历时八年。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试历时两个小时。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个手术历时四小时。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们修这条路历时半年。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛从开始到结束，历时九十分钟。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的拍摄历时一年多。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种好这片树林历时十年。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动历时五天。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的研究历时两个月。", "target_word": "历时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷時", "label": "繁体"}], "register": "书面", "sense_fingerprint": "历时：一件事从开始到结束所用的时间长度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b564bc7-abf7-40ec-96cb-cfa30e5b9152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25804, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "历时", "is_correct": true, "explanation": "本词：指一件事从开始到结束所用的时间长度。"}, {"text": "历史", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，意思是历史。"}, {"text": "理事", "is_correct": false, "explanation": "lǐ 与 lì、shì 与 shí 声调都不同，意思是理事，即管理事务的人。"}, {"text": "离世", "is_correct": false, "explanation": "lí 与 lì、shì 与 shí 声调都不同，意思是去世。"}, {"text": "力士", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是力气大的人。"}], "explanations": {"历时": "本词：指一件事从开始到结束所用的时间长度。", "历史": "shǐ（第三声）与 shí（第二声）声调不同，意思是历史。", "理事": "lǐ 与 lì、shì 与 shí 声调都不同，意思是理事，即管理事务的人。", "离世": "lí 与 lì、shì 与 shí 声调都不同，意思是去世。", "力士": "shì（第四声）与 shí（第二声）声调不同，意思是力气大的人。"}, "sentence_index": null, "correct_answer": "历时"}, "level_3": {"options": [{"text": "历时", "is_correct": true, "explanation": "本词：指工程从开始到完成所经过的时间，与“三年”搭配，符合句意。"}, {"text": "发生", "is_correct": false, "explanation": "搭配：“发生”指事情出现，不能以时间段作宾语。"}, {"text": "取消", "is_correct": false, "explanation": "语义：“取消”指作废，与工程完成的句意相反。"}, {"text": "撤销", "is_correct": false, "explanation": "语义：“撤销”指收回决定，与工程完成的语境相反。"}], "explanations": {"历时": "本词：指工程从开始到完成所经过的时间，与“三年”搭配，符合句意。", "发生": "搭配：“发生”指事情出现，不能以时间段作宾语。", "取消": "语义：“取消”指作废，与工程完成的句意相反。", "撤销": "语义：“撤销”指收回决定，与工程完成的语境相反。"}, "sentence_index": 0, "correct_answer": "历时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥历时五百米。", "explanation": "这里应该用〈长达〉。历时说事情经过的时间，不能用来表示长度。"}, {"text": "手术历时上午八点。", "explanation": "这里应该用〈从……开始〉。历时只接表示时长的词，不接时间点。"}, {"text": "我们的车历时每小时一百公里。", "explanation": "这里应该用〈时速〉。历时只说事情经过的时长，不能表示速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历时", "is_correct": true, "explanation": "本词：指拍摄过程所经过的时间，与“一年多”搭配，符合句意。"}, {"text": "宣布", "is_correct": false, "explanation": "搭配：“宣布”的宾语是事项或决定，不能以时间段作宾语。"}, {"text": "开幕", "is_correct": false, "explanation": "搭配：“开幕”用于会议或活动，不能用于拍摄。"}, {"text": "检验", "is_correct": false, "explanation": "语义：“检验”指检查，与拍摄所需时长的句意不符。"}], "explanations": {"历时": "本词：指拍摄过程所经过的时间，与“一年多”搭配，符合句意。", "宣布": "搭配：“宣布”的宾语是事项或决定，不能以时间段作宾语。", "开幕": "搭配：“开幕”用于会议或活动，不能用于拍摄。", "检验": "语义：“检验”指检查，与拍摄所需时长的句意不符。"}, "sentence_index": 6, "correct_answer": "历时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的研究历时两公斤。", "explanation": "这里应该用〈重〉。历时说时间长短，不能用来表示重量。"}, {"text": "我们每天历时两次研究。", "explanation": "这里应该用〈进行〉。历时表示时长，不能用来计算次数。"}, {"text": "我们的研究历时下午三点。", "explanation": "这里应该用〈开始于〉。历时只接表示时长的词，如“两个月”，不接时间点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套设备的安装历时过一周。", "corrected_sentence": "这套设备的安装历时一周。", "error_description": "错误形式是“历时”后加了表示经历的“过”。“历时”后直接接时间长度，正确形式是「这套设备的安装历时一周」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的筹备很历时半年。", "corrected_sentence": "这家公司的筹备历时半年。", "error_description": "错误形式是在“历时”前加了程度副词“很”。“历时”是动词，不能受“很”修饰。正确形式是「这家公司的筹备历时半年」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d57629-bc37-4f82-8ee9-c50d69be4a64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
