INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "精度就是东西量得准不准。", "primary_collocate": null, "pronunciation": "jīng dù", "ipa": "tɕiŋ˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这把尺子的精度不高，量不准。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电子秤的精度比老秤高多了。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要看看这个温度计的精度。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "精度高的尺子，量出来的数更准。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块表的精度很好，一天只差一秒。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做木工时，尺子的精度很重要。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子的刻度精度太低，量不准水。", "target_word": "精度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：这台机器的精度是多少？", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "精度不够的话，数字就不可靠。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买秤的时候，我先问了它的精度。", "target_word": "精度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高精度", "label": "复合"}, {"form": "低精度", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西量得准不准的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c243019-86a3-4adf-869e-dc4043fc4b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25808, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精度", "is_correct": true, "explanation": "正确。精度指东西量得准不准的程度。"}, {"text": "精读", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声调不同，精读是仔细阅读的意思。"}, {"text": "进度", "is_correct": false, "explanation": "jìn 与 jīng 的韵母不同（in 与 ing），声调也不同，进度指事情进行的程度。"}, {"text": "净度", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，净度指宝石等的纯净程度。"}], "explanations": {"精度": "正确。精度指东西量得准不准的程度。", "精读": "dú（第二声）与 dù（第四声）声调不同，精读是仔细阅读的意思。", "进度": "jìn 与 jīng 的韵母不同（in 与 ing），声调也不同，进度指事情进行的程度。", "净度": "jìng（第四声）与 jīng（第一声）声调不同，净度指宝石等的纯净程度。"}, "sentence_index": null, "correct_answer": "精度"}, "level_3": {"options": [{"text": "精度", "is_correct": true, "explanation": "正确。精度指量得准不准的程度，与“量不准”相呼应。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：尺子的颜色与量得准不准无关，“颜色不高”说不通。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”不说“高”或“不高”，句中要的是测量的准确程度。"}, {"text": "口味", "is_correct": false, "explanation": "语义：口味指食物的味道，与尺子能否量准无关。"}], "explanations": {"精度": "正确。精度指量得准不准的程度，与“量不准”相呼应。", "颜色": "语义：尺子的颜色与量得准不准无关，“颜色不高”说不通。", "性格": "搭配：“性格”不说“高”或“不高”，句中要的是测量的准确程度。", "口味": "语义：口味指食物的味道，与尺子能否量准无关。"}, "sentence_index": 0, "correct_answer": "精度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台新机器的精度很快，一小时能做二十个。", "explanation": "这里应该用〈速度〉。精度说测量或制造的准确程度，说快慢要用〈速度〉。"}, {"text": "这家工厂的精度很有名，大家都知道它的产品。", "explanation": "这里应该用〈名气〉。精度指测量、计算或制造的准确程度，说工厂有名要用〈名气〉。"}, {"text": "这首歌的精度很长，唱了很久。", "explanation": "这里应该用〈时长〉。精度指测量、计算或制造的准确程度，说歌的长短要用〈时长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精度", "is_correct": true, "explanation": "正确。精度指刻度测量的准确程度，与“量不准水”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：刻度的颜色与量水是否准确无关，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“刻度”后不能接“价格”，“刻度价格”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与刻度的准确性无关，“刻度年龄太低”没有意义。"}], "explanations": {"精度": "正确。精度指刻度测量的准确程度，与“量不准水”相符。", "颜色": "语义：刻度的颜色与量水是否准确无关，句意不通。", "价格": "搭配：“刻度”后不能接“价格”，“刻度价格”说不通。", "年龄": "语义：年龄与刻度的准确性无关，“刻度年龄太低”没有意义。"}, "sentence_index": 6, "correct_answer": "精度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次数学考了满分，精度很高。", "explanation": "这里应该用〈成绩〉。精度指测量、计算或制造的准确程度，说考试的分数要用〈成绩〉。"}, {"text": "他跑了一整天，精度还很好，一点也不累。", "explanation": "这里应该用〈体力〉。精度指测量、计算或制造的准确程度，说人跑完后还有没有力气要用〈体力〉。"}, {"text": "这本书的精度很长，读起来很累。", "explanation": "这里应该用〈篇幅〉。精度指测量、计算或制造的准确程度，说书的长短要用〈篇幅〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把精度很高，称药很准。", "corrected_sentence": "这种精度很高，称药很准。", "error_description": "量词错误：“精度”是抽象名词，不能用量词“把”（“把”用于有柄的器具），应说“这种精度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块表的精度好很，走得很准。", "corrected_sentence": "这块表的精度很好，走得很准。", "error_description": "语序错误：副词“很”应放在形容词“好”前作状语，说成“好很”不通，应说“很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
