INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25810, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "恭敬地把文件、物品拿出来交给上级或长辈看。", "primary_collocate": null, "pronunciation": "chéng", "ipa": "ʈʂʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他把报告呈给了经理。", "target_word": "呈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生把作业呈给老师检查。", "target_word": "呈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把名单呈给了会长。", "target_word": "呈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王双手把礼物呈上。", "target_word": "呈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣把信呈给了皇帝。", "target_word": "呈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办事员要先把材料呈给主任看。", "target_word": "呈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把调查结果呈给了市长。", "target_word": "呈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仆人恭敬地把茶呈给主人。", "target_word": "呈", "complexity_tier": "T3", "furigana": "pú rén gōng jìng de bǎ chá chéng gěi zhǔ rén", "sentence_source": "generated"}, {"text": "警察要求他把证据呈上来。", "target_word": "呈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把证件呈上来，我看一下。", "target_word": "呈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "呈交", "label": "复合"}, {"form": "呈送", "label": "复合"}], "register": "书面语", "sense_fingerprint": "恭敬地把文件、物品拿出来交给上级或长辈看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108d68a3-9e9d-4db4-87ac-576670149e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "呈", "is_correct": true, "explanation": "呈 chéng 即目标词，意思是恭敬地把东西拿给别人看。"}, {"text": "称", "is_correct": false, "explanation": "称 chēng（第一声）与 chéng 声调不同，意思是称量。"}, {"text": "晨", "is_correct": false, "explanation": "晨 chén 韵母不同（-n 与 -ng），意思是早晨。"}, {"text": "逞", "is_correct": false, "explanation": "逞 chěng（第三声）与 chéng 声调不同，意思是逞强。"}, {"text": "常", "is_correct": false, "explanation": "常 cháng 韵母不同（-ang 与 -eng），意思是经常。"}], "explanations": {"呈": "呈 chéng 即目标词，意思是恭敬地把东西拿给别人看。", "称": "称 chēng（第一声）与 chéng 声调不同，意思是称量。", "晨": "晨 chén 韵母不同（-n 与 -ng），意思是早晨。", "逞": "逞 chěng（第三声）与 chéng 声调不同，意思是逞强。", "常": "常 cháng 韵母不同（-ang 与 -eng），意思是经常。"}, "sentence_index": null, "correct_answer": "呈"}, "level_3": {"options": [{"text": "呈", "is_correct": true, "explanation": "呈表示恭敬地把文件递给上级，与“报告”“经理”相合。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”用于给人或动物吃东西，报告不能被喂。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”指重击，不能表示递交。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指使劲扔下，与恭敬递交的语境不合。"}], "explanations": {"呈": "呈表示恭敬地把文件递给上级，与“报告”“经理”相合。", "喂": "搭配：“喂”用于给人或动物吃东西，报告不能被喂。", "砸": "语义：“砸”指重击，不能表示递交。", "摔": "语义：“摔”指使劲扔下，与恭敬递交的语境不合。"}, "sentence_index": 0, "correct_answer": "呈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把垃圾呈进了箱子里。", "explanation": "这里应该用〈扔〉。呈是恭敬地把东西拿给上级或长辈看，不能用于把垃圾扔进箱子。"}, {"text": "妈妈把饭呈给了宝宝。", "explanation": "这里应该用〈喂〉。呈是恭敬地递给上级或长辈看，不用于给幼儿喂饭。"}, {"text": "他把包裹呈走了。", "explanation": "这里应该用〈寄〉。呈是恭敬地把东西拿给上级或长辈看，不表示把包裹寄走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25810, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "呈", "is_correct": true, "explanation": "呈 chéng 即目标词，意思是恭敬地把东西拿给别人看。"}, {"text": "撑", "is_correct": false, "explanation": "撑 chēng（第一声）与 chéng 声调不同，意思是支撑。"}, {"text": "尘", "is_correct": false, "explanation": "尘 chén 韵母不同（-n 与 -ng），意思是灰尘。"}, {"text": "秤", "is_correct": false, "explanation": "秤 chèng（第四声）与 chéng 声调不同，意思是称重的器具。"}, {"text": "长", "is_correct": false, "explanation": "长 cháng 韵母不同（-ang 与 -eng），意思是长短。"}], "explanations": {"呈": "呈 chéng 即目标词，意思是恭敬地把东西拿给别人看。", "撑": "撑 chēng（第一声）与 chéng 声调不同，意思是支撑。", "尘": "尘 chén 韵母不同（-n 与 -ng），意思是灰尘。", "秤": "秤 chèng（第四声）与 chéng 声调不同，意思是称重的器具。", "长": "长 cháng 韵母不同（-ang 与 -eng），意思是长短。"}, "sentence_index": null, "correct_answer": "呈"}, "level_3": {"options": [{"text": "呈", "is_correct": true, "explanation": "呈表示恭敬地把调查结果递给上级，与“调查结果”“市长”相合。"}, {"text": "泼", "is_correct": false, "explanation": "语义：“泼”指倾倒液体，不能用于调查结果。"}, {"text": "吐", "is_correct": false, "explanation": "语义：“吐”指从口中排出，不能表示恭敬地递交。"}, {"text": "劈", "is_correct": false, "explanation": "搭配：“劈”指用刀斧砍，不与“调查结果”搭配。"}], "explanations": {"呈": "呈表示恭敬地把调查结果递给上级，与“调查结果”“市长”相合。", "泼": "语义：“泼”指倾倒液体，不能用于调查结果。", "吐": "语义：“吐”指从口中排出，不能表示恭敬地递交。", "劈": "搭配：“劈”指用刀斧砍，不与“调查结果”搭配。"}, "sentence_index": 6, "correct_answer": "呈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把球呈给了队友。", "explanation": "这里应该用〈传〉。呈只用于恭敬地把文件或物品递给上级看，不用于队友之间传球。"}, {"text": "他把画呈在墙上。", "explanation": "这里应该用〈挂〉。呈表示恭敬地递交，不能表示把画挂在墙上。"}, {"text": "他把杯子呈碎了。", "explanation": "这里应该用〈摔〉。呈是恭敬地把东西拿给上级或长辈看，不表示把杯子摔碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把合同给呈了董事长。", "corrected_sentence": "他把合同呈给了董事长。", "error_description": "“呈”与“给”语序颠倒：“呈”是动词，应说“呈给”，不能说“给呈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把证件呈下来了。", "corrected_sentence": "他把证件呈上来了。", "error_description": "“呈上来”表示把东西向上送；“下来”方向相反，不能接在“呈”后，应说“呈上来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
