INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西摸起来的感觉，比如软软的、硬硬的。", "primary_collocate": null, "pronunciation": "zhì dì", "ipa": "ʈʂɻ̩˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这块布的质地很软。", "target_word": "质地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我摸了摸桌子，它的质地很光滑。", "target_word": "质地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种纸的质地很粗，写字不太舒服。", "target_word": "质地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫喜欢躺在质地柔软的毯子上。", "target_word": "质地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你摸摸这两件衣服，质地一样吗？", "target_word": "质地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子的质地摸着很暖，不像铁椅那么凉。", "target_word": "质地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的皮鞋质地柔软，穿着不会磨脚。", "target_word": "质地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用手摸了摸石头，说它的质地很粗。", "target_word": "质地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种海绵质地松软，一按就陷下去。", "target_word": "质地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最喜欢这件毛衣的质地，又软又暖和。", "target_word": "质地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "質地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西摸起来的感觉（软、硬、粗、滑）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c243019-86a3-4adf-869e-dc4043fc4b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“软”形容材料的手感，不能说颜色很软。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“软”不能用来形容温度。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与布料的手感无关，不能说价格很软。"}, {"text": "质地", "is_correct": true, "explanation": "正确：指布料摸起来的感觉，“软”正是对它的描述。"}], "explanations": {"颜色": "搭配：“软”形容材料的手感，不能说颜色很软。", "温度": "搭配：“软”不能用来形容温度。", "价格": "语义：价格与布料的手感无关，不能说价格很软。", "质地": "正确：指布料摸起来的感觉，“软”正是对它的描述。"}, "sentence_index": 0, "correct_answer": "质地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条毯子的质地很鲜艳，小猫很喜欢。", "explanation": "这里应该用〈颜色〉。“鲜艳”说的是颜色，质地是摸起来的感觉，不能说鲜艳。"}, {"text": "这床被子的质地很甜，小猫很喜欢。", "explanation": "这里应该用〈口味〉。质地指摸起来的感觉，不能用“甜”来形容，“甜”说的是味道。"}, {"text": "这块布的质地很香，小猫很喜欢。", "explanation": "这里应该用〈气味〉。质地指摸起来的感觉，不能用“香”来形容，“香”说的是气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形状", "is_correct": false, "explanation": "语义：形状不能用“柔软”来形容，皮鞋的形状与软硬无关。"}, {"text": "厚度", "is_correct": false, "explanation": "搭配：“柔软”形容材料的手感，不说厚度柔软。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量指轻重，不能说重量柔软。"}, {"text": "质地", "is_correct": true, "explanation": "正确：指皮鞋材料摸起来的感觉，“柔软”描述的正是质地。"}], "explanations": {"形状": "语义：形状不能用“柔软”来形容，皮鞋的形状与软硬无关。", "厚度": "搭配：“柔软”形容材料的手感，不说厚度柔软。", "重量": "语义：重量指轻重，不能说重量柔软。", "质地": "正确：指皮鞋材料摸起来的感觉，“柔软”描述的正是质地。"}, "sentence_index": 6, "correct_answer": "质地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把尺子的质地很长，量起来很方便。", "explanation": "这里应该用〈长度〉。质地指摸起来的感觉，不能用“长”来形容，“长”说的是长度。"}, {"text": "这道菜的质地很辣，我吃得很过瘾。", "explanation": "这里应该用〈口味〉。质地是摸起来的感觉，不能用“辣”来形容。"}, {"text": "这首歌的质地很香，大家都爱听。", "explanation": "这里应该用〈气味〉。“香”说的是气味，歌曲的质地不能用“香”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件外套的质地们很厚实。", "corrected_sentence": "这件外套的质地很厚实。", "error_description": "“质地”不能加“们”表示复数；“们”只用于指人的名词。应改为：这件外套的质地很厚实。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双手套有一只暖和的质地。", "corrected_sentence": "这双手套有一种暖和的质地。", "error_description": "“质地”是抽象名词，前面量词应用“种”；“只”多用于动物，不能用于质地。应改为：这双手套有一种暖和的质地。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
