INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "森林里的土。", "primary_collocate": null, "pronunciation": "sēn lín tǔ rǎng", "ipa": "sən˥ lin˧˥ tʰu˨˩˦ ɻɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "森林土壤很软。", "target_word": "森林土壤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我蹲下来，摸了摸森林土壤。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林土壤里有树叶和树枝。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明用小铲子挖了一些森林土壤。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，森林土壤很适合种树。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这袋森林土壤是爸爸从山上带回来的。", "target_word": "森林土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，森林土壤的味道特别好闻。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林土壤和沙子不一样，它又黑又湿。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蚂蚁在森林土壤里安了家。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花店老板说，这种花要放在森林土壤里。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "森林里的土", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c243019-86a3-4adf-869e-dc4043fc4b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "森林土壤", "is_correct": true, "explanation": "“森林土壤”指森林里的土，松软，与“很软”相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头本身质地坚硬，说石头很软与常识相反。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“软”多用于物体的质地，不说空气很软。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁质地坚硬，不能说很软。"}], "explanations": {"森林土壤": "“森林土壤”指森林里的土，松软，与“很软”相合。", "石头": "语义：石头本身质地坚硬，说石头很软与常识相反。", "空气": "搭配：“软”多用于物体的质地，不说空气很软。", "钢铁": "语义：钢铁质地坚硬，不能说很软。"}, "sentence_index": 0, "correct_answer": "森林土壤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明用小铲子挖了一条森林土壤。", "explanation": "这里应该用〈一袋〉或〈一堆〉。“条”用于细长的物件，土壤不能用“条”计量。"}, {"text": "小明在森林土壤里迷了路。", "explanation": "这里应该用〈树林〉。迷路的地点应是树林，土壤不是能让人迷路的地方。"}, {"text": "我们在森林土壤里乘凉。", "explanation": "这里应该用〈树林〉。乘凉要在树下或林间，不能在土壤里乘凉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "森林土壤", "is_correct": true, "explanation": "“森林土壤”雨后散发清香，与“特别好闻”一致。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾的味道难闻，不会“特别好闻”。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所的气味让人难受，与“特别好闻”矛盾。"}, {"text": "钢筋", "is_correct": false, "explanation": "搭配：“钢筋”是金属，没有气味，不说它的“味道”。"}], "explanations": {"森林土壤": "“森林土壤”雨后散发清香，与“特别好闻”一致。", "垃圾": "语义：垃圾的味道难闻，不会“特别好闻”。", "厕所": "语义：厕所的气味让人难受，与“特别好闻”矛盾。", "钢筋": "搭配：“钢筋”是金属，没有气味，不说它的“味道”。"}, "sentence_index": 6, "correct_answer": "森林土壤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花店老板说，这种花要放在很响的森林土壤里。", "explanation": "这里应该用〈松软〉。“响”形容声音，土壤不能用它来形容。"}, {"text": "花店老板说，这种花每天要喝森林土壤。", "explanation": "这里应该用〈水〉。“喝”的对象是液体，土壤不能喝。"}, {"text": "那片森林土壤又粗又壮，要三个人才能抱住。", "explanation": "这里应该用〈树〉。“又粗又壮”形容树干等有形体的东西，土壤不说粗壮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块森林土壤软很，踩上去陷下去。", "corrected_sentence": "这块森林土壤很软，踩上去陷下去。", "error_description": "形容词“软”前面要加程度副词“很”，应说“很软”，不能说“软很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师要我们带一条森林土壤回教室。", "corrected_sentence": "老师要我们带一袋森林土壤回教室。", "error_description": "土壤的量词应用“袋”，“条”用于细长的物件，不能用来计量土壤，应说“一袋森林土壤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
