INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "最后得到的东西。", "primary_collocate": null, "pronunciation": "zhōng chǎn wù", "ipa": "ʈʂʊŋ˥ ʈʂʰan˨˩˦ u˥˩", "syllable_count": 3, "sentences": [{"text": "做完这些步骤，终产物就是一杯果汁。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一块布经过很多步骤，终产物是一件衣服。", "target_word": "终产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们做了三天，终产物是一张桌子。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个过程很长，但终产物很漂亮。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们看看这些材料的终产物是什么。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，写作文的终产物是一篇好文章。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看终产物，就知道工人做得好不好。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小麦经过磨粉，终产物是白色的面粉。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "终产物放进盒子里，就可以卖了。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂每天检查终产物的质量。", "target_word": "终产物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "終產物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经过一系列步骤后最后得到的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c243019-86a3-4adf-869e-dc4043fc4b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原料", "is_correct": false, "explanation": "语义：原料是加工前投入的东西，不是加工完成后得到的饮品。"}, {"text": "半成品", "is_correct": false, "explanation": "语义：半成品指尚未加工完成的东西，与“做完这些步骤”相矛盾。"}, {"text": "配料", "is_correct": false, "explanation": "搭配：“配料”是加进食物里的成分，不能说“配料就是一杯果汁”。"}, {"text": "终产物", "is_correct": true, "explanation": "正确：做完步骤后得到的最后东西，即一杯果汁。"}], "explanations": {"原料": "语义：原料是加工前投入的东西，不是加工完成后得到的饮品。", "半成品": "语义：半成品指尚未加工完成的东西，与“做完这些步骤”相矛盾。", "配料": "搭配：“配料”是加进食物里的成分，不能说“配料就是一杯果汁”。", "终产物": "正确：做完步骤后得到的最后东西，即一杯果汁。"}, "sentence_index": 0, "correct_answer": "终产物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做衣服前，先要准备好终产物。", "explanation": "这里应该用〈原料〉。终产物是加工完成后得到的东西，不能在加工前准备。"}, {"text": "做完后，工人得到了一根终产物。", "explanation": "量词用错：终产物指加工得到的成品，应用〈件〉或〈批〉等；〈根〉用于细长条形的东西。"}, {"text": "这些衣服还是终产物，扣子还没缝上。", "explanation": "这里应该用〈半成品〉。终产物指加工完成的东西，与“扣子还没缝上”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说明书", "is_correct": false, "explanation": "语义：说明书只讲使用方法，看它不能知道工人做得好不好。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与工人的工作质量无关，看天气不能判断东西做得好不好。"}, {"text": "配方", "is_correct": false, "explanation": "搭配：“配方”是配料和步骤，不能与“做得好不好”搭配来判断工作质量。"}, {"text": "终产物", "is_correct": true, "explanation": "正确：指加工完成后得到的东西，看它才能知道工人做得好不好。"}], "explanations": {"说明书": "语义：说明书只讲使用方法，看它不能知道工人做得好不好。", "天气": "语义：天气与工人的工作质量无关，看天气不能判断东西做得好不好。", "配方": "搭配：“配方”是配料和步骤，不能与“做得好不好”搭配来判断工作质量。", "终产物": "正确：指加工完成后得到的东西，看它才能知道工人做得好不好。"}, "sentence_index": 6, "correct_answer": "终产物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "清洗后，机器里还留着很多终产物。", "explanation": "这里应该用〈残渣〉。终产物是加工得到的成果，留在机器里的是残渣，不是终产物。"}, {"text": "我们跑到终产物就停下来了。", "explanation": "这里应该用〈终点〉。终产物是最后得到的东西；跑步到达、停下来的地方叫终点，不能说终产物。"}, {"text": "这一步得到的终产物还要继续加工。", "explanation": "这里应该用〈中间品〉。终产物是最后得到的东西，不会再被加工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把终产物们装进了箱子。", "corrected_sentence": "工人把终产物装进了箱子。", "error_description": "“终产物”是物品，不能加“们”；“们”只用于指人的名词。应改为：工人把终产物装进了箱子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂每天生产一只终产物。", "corrected_sentence": "工厂每天生产一批终产物。", "error_description": "“终产物”是成批生产的产品，量词应用“批”；“只”常用于单个的动物或物件，不用于成批生产的产品。应改为：工厂每天生产一批终产物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd3a284-e754-4412-bbdf-54df91389c00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
