INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水开始流出来的地方，也指事情开始的地方。", "primary_collocate": null, "pronunciation": "yuán tóu", "ipa": "ɥɛn˧˥ tʰoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "我们走了很久，终于看到小河的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个泉水就是那条小溪的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这件事的源头是一个误会。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道黄河的源头在哪个省吗？", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山脚下有一个小湖，是这条河的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架的源头其实是一句玩笑话。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爬上山顶，去看河水的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找到火灾的源头，所以去了仓库。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的源头是一本老书。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很清，因为源头没有污染。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "源頭", "label": "繁体"}, {"form": "源头活水", "label": "四字格"}, {"form": "一个源头", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "源头：水开始流出的地方，也指事情开始的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755d8dfd-b59d-4c6c-9903-4203478bf4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脚印", "is_correct": false, "explanation": "语义：脚印是人或动物踩出的痕迹，小河不会留下脚印，句中说“终于看到小河的……”讲不通。"}, {"text": "源头", "is_correct": true, "explanation": "源头：水开始流出的地方。这里指小河的起始处，与“看到”搭配，句意通顺。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或动物活了多少年，不用来说小河。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”要用“闻”或“尝”，不能和“看到”搭配。"}], "explanations": {"脚印": "语义：脚印是人或动物踩出的痕迹，小河不会留下脚印，句中说“终于看到小河的……”讲不通。", "源头": "源头：水开始流出的地方。这里指小河的起始处，与“看到”搭配，句意通顺。", "年龄": "语义：年龄指人或动物活了多少年，不用来说小河。", "味道": "搭配：“味道”要用“闻”或“尝”，不能和“看到”搭配。"}, "sentence_index": 0, "correct_answer": "源头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的源头很宽，大船可以从那里驶入大海。", "explanation": "这里应该用〈河口〉。河口是河流汇入大海、可以行船的地方；源头是水开始流出的地方，通常很窄，不能说很宽，也不能让大船从那里驶入大海。"}, {"text": "这条路的源头在山的那一边。", "explanation": "这里应该用〈起点〉。起点指道路开始的地方；源头指水或事情的根源，一般不用来指道路的起始处。"}, {"text": "我们的源头在这片草原上生活了三千年。", "explanation": "这里应该用〈祖先〉。祖先是世代相传的先人，能在某地生活；源头指水或事情开始的地方，不指人群，不能作“生活”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山顶", "is_correct": false, "explanation": "语义：山顶是山的最高处，河水没有山顶，与“河水的”搭配不成立。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“去看”后面不能接“声音”，声音要用“听”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物的重量，河水不说体重。"}, {"text": "源头", "is_correct": true, "explanation": "源头：水开始流出的地方。这里指河水的起始处，与“去看”搭配，句意通顺。"}], "explanations": {"山顶": "语义：山顶是山的最高处，河水没有山顶，与“河水的”搭配不成立。", "声音": "搭配：“去看”后面不能接“声音”，声音要用“听”。", "体重": "语义：体重指人或动物的重量，河水不说体重。", "源头": "源头：水开始流出的地方。这里指河水的起始处，与“去看”搭配，句意通顺。"}, "sentence_index": 6, "correct_answer": "源头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场马拉松的源头在市政府门口。", "explanation": "这里应该用〈起点〉。起点可用于比赛、路线的出发处；源头指水或事情开始的根源，不用于比赛的起跑地。"}, {"text": "这个博物馆的源头在东边，大家从那里进去。", "explanation": "这里应该用〈入口〉。入口是人可以进入的地方；源头是水或事情开始的地方，不指建筑的进出口。"}, {"text": "这个学期的源头是期末考试。", "explanation": "这里应该用〈终点〉。终点指一段过程结束的地方或时候；源头指水或事情开始的地方，不能指结束的时候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们沿着河走，终于找到了一只源头。", "corrected_sentence": "我们沿着河走，终于找到了一个源头。", "error_description": "“源头”的量词错误：应说“一个源头”，不能说“一只源头”。“只”多用于动物，或用于成对、小件的东西，“源头”应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "泉水源头流出来。", "corrected_sentence": "泉水从源头流出来。", "error_description": "介词“从”的遗漏：表示起点要说“从源头流出来”，不能直接说“源头流出来”，否则“源头”前缺少引出起点的“从”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
