INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25830, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "得到的东西。", "primary_collocate": null, "pronunciation": "suǒ dé", "ipa": "suo˨˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他把一天的所得放在桌子上。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打工一个月，她的所得不多。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我们大家辛苦工作的所得。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把所得分给了几个朋友。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王看着一年的所得，笑了。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的所得，我要全部存起来。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔民出海一天，所得是三筐鱼。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们数了数今天的所得。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想要别人的所得，只想靠自己。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的所得，是一个宝贵的经验。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所得税", "label": "复合"}, {"form": "劳动所得", "label": "复合"}], "register": "书面", "sense_fingerprint": "自己得到的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78fdf4f0-324a-48ce-8d2c-3732d912f7c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所得", "is_correct": true, "explanation": "正确：“所得”指得到的东西，可以放在桌子上。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是抽象概念，不能放在桌子上，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的温度，不是可以放置的东西。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“放”要带具体物品作宾语，“笑声”不能放在桌子上。"}], "explanations": {"所得": "正确：“所得”指得到的东西，可以放在桌子上。", "时间": "语义：“时间”是抽象概念，不能放在桌子上，句意不通。", "体温": "语义：“体温”是身体的温度，不是可以放置的东西。", "笑声": "搭配：“放”要带具体物品作宾语，“笑声”不能放在桌子上。"}, "sentence_index": 0, "correct_answer": "所得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对朋友的所得很深。", "explanation": "这里应该用〈感情〉。“所得”指得到的东西，不能用“很深”来形容。"}, {"text": "他今天拿到了一只所得。", "explanation": "这里应该用〈份〉或〈笔〉。“只”用于动物、成对的器官等，不用于计量所得。"}, {"text": "他的心里充满了所得。", "explanation": "这里应该用〈喜悦〉。“所得”是得到的东西，不是情绪，不能“充满”心里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所得", "is_correct": true, "explanation": "正确：“所得”指渔民出海得到的东西，即三筐鱼。"}, {"text": "疲惫", "is_correct": false, "explanation": "语义：“疲惫”是人的状态，不是出海的结果，与“三筐鱼”不搭。"}, {"text": "理想", "is_correct": false, "explanation": "语义：“理想”是抽象的愿望，与“三筐鱼”这样具体的收获不搭。"}, {"text": "渔网", "is_correct": false, "explanation": "搭配：“三筐”计量的是鱼、果实等收获，“渔网”是工具，不能用“三筐”来计量。"}], "explanations": {"所得": "正确：“所得”指渔民出海得到的东西，即三筐鱼。", "疲惫": "语义：“疲惫”是人的状态，不是出海的结果，与“三筐鱼”不搭。", "理想": "语义：“理想”是抽象的愿望，与“三筐鱼”这样具体的收获不搭。", "渔网": "搭配：“三筐”计量的是鱼、果实等收获，“渔网”是工具，不能用“三筐”来计量。"}, "sentence_index": 6, "correct_answer": "所得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次失误给球队带来了很大的所得。", "explanation": "这里应该用〈损失〉。失误带来的是损失，“所得”指得到的收益，不能与负面结果搭配。"}, {"text": "这笔债务成了他的所得。", "explanation": "这里应该用〈负担〉。债务是需要偿还的负担，不是得到的东西。"}, {"text": "他一生都在忍受所得。", "explanation": "这里应该用〈痛苦〉。忍受的是痛苦，“所得”不能被忍受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她攒下了一块不小的所得。", "corrected_sentence": "她攒下了一笔不小的所得。", "error_description": "错误：“所得”前的量词“块”不当，应为“笔”。“块”用于块状物，不用于计量所得。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔民今天拿回了一座可观的所得。", "corrected_sentence": "渔民今天拿回了一笔可观的所得。", "error_description": "错误：“所得”前的量词“座”不当，应为“笔”。“座”用于山、房屋等大型固定物，不用于计量所得。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
