INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25834, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "食物里能帮助身体长大的好东西。", "primary_collocate": null, "pronunciation": "yíng yǎng", "ipa": "iŋ˧˥ jɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "宝宝要吃有营养的饭。", "target_word": "营养", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "牛奶有营养，你要多喝。", "target_word": "营养", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友吃饭要有营养，才能长高。", "target_word": "营养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给我做了有营养的饭菜。", "target_word": "营养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些菜很有营养，快吃吧。", "target_word": "营养", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "只吃糖，身体没有营养。", "target_word": "营养", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鸡蛋里有营养，能让你长高。", "target_word": "营养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不好好吃饭，身体会缺少营养。", "target_word": "营养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果和蔬菜都很有营养。", "target_word": "营养", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥说，苹果的营养很丰富。", "target_word": "营养", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "营养品", "label": "复合"}, {"form": "营养不良", "label": "复合"}], "register": "中性", "sense_fingerprint": "食物里帮助身体长大的好东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f08d9b0-eeda-4784-a384-1aff1574232b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "营养", "is_correct": true, "explanation": "正确：“有营养的饭”指对身体长大有益，符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“有价格的饭”说不通，饭的好坏与价格无关。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”与“宝宝要吃饭”的语境无关。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：“有音乐的饭”说不通，饭不具有音乐。"}], "explanations": {"营养": "正确：“有营养的饭”指对身体长大有益，符合语境。", "价格": "语义：“有价格的饭”说不通，饭的好坏与价格无关。", "寿命": "语义：“寿命”与“宝宝要吃饭”的语境无关。", "音乐": "语义：“有音乐的饭”说不通，饭不具有音乐。"}, "sentence_index": 0, "correct_answer": "营养"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我买了一颗营养。", "explanation": "这里应该用〈种〉。营养不能用“颗”计量，颗用于颗粒状的东西。"}, {"text": "我每天吃大量营养。", "explanation": "这里应该用〈食物〉。营养是食物里对身体有益的成分，不能直接当作食物来吃。"}, {"text": "这道菜的营养很好吃。", "explanation": "这里应该用〈味道〉。“好吃”描述的是味道，营养不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "营养", "is_correct": true, "explanation": "正确：“鸡蛋里有营养，能让你长高”，营养促进成长，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：鸡蛋里的颜色与“能让你长高”的因果不成立。"}, {"text": "形状", "is_correct": false, "explanation": "体貌：形状与身高增长无关，“能让你长高”说不通。"}, {"text": "节奏", "is_correct": false, "explanation": "语义：节奏与鸡蛋的成分无关，也不能促进长高。"}], "explanations": {"营养": "正确：“鸡蛋里有营养，能让你长高”，营养促进成长，符合语境。", "颜色": "语义：鸡蛋里的颜色与“能让你长高”的因果不成立。", "形状": "体貌：形状与身高增长无关，“能让你长高”说不通。", "节奏": "语义：节奏与鸡蛋的成分无关，也不能促进长高。"}, "sentence_index": 6, "correct_answer": "营养"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家药店卖各种营养。", "explanation": "这里应该用〈营养品〉。营养是食物里的成分，不能拿来出售，可以卖的是营养品。"}, {"text": "哥哥吃了一块营养。", "explanation": "量词错误：营养不能用“块”计量，应该用〈种〉。"}, {"text": "哥哥说，苹果的营养很红。", "explanation": "这里应该用〈颜色〉。“红”描述颜色，营养没有颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈做的饭有多个营养。", "corrected_sentence": "妈妈做的饭有多种营养。", "error_description": "量词错误：“营养”应该用“种”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种蔬菜有一根营养。", "corrected_sentence": "这种蔬菜有一种营养。", "error_description": "量词错误：「营养」应该用「种」，「根」用于细长的东西，不能用来计量营养。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
