INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25836, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "吃饭时用的桌子。", "primary_collocate": null, "pronunciation": "cān zhuō", "ipa": "tsʰan˥ ʈʂuo˥", "syllable_count": 2, "sentences": [{"text": "饭做好了，请大家来餐桌这边。", "target_word": "餐桌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了一张新餐桌。", "target_word": "餐桌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "餐桌上有鱼，有肉，还有汤。", "target_word": "餐桌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩子不要在餐桌上玩。", "target_word": "餐桌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们每天晚上在餐桌上聊天。", "target_word": "餐桌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶把餐桌擦得很干净。", "target_word": "餐桌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张餐桌太小，坐不下八个人。", "target_word": "餐桌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸坐在餐桌的一头看报。", "target_word": "餐桌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "餐桌上的菜都凉了。", "target_word": "餐桌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把碗筷摆到餐桌上。", "target_word": "餐桌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "餐桌布", "label": "复合"}], "register": "中性", "sense_fingerprint": "吃饭时用的桌子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78fdf4f0-324a-48ce-8d2c-3732d912f7c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餐桌", "is_correct": true, "explanation": "正确。“饭做好了，请大家来……这边”中的地点应是供人吃饭的桌子，餐桌符合句意。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：饭做好了却叫大家去垃圾桶旁边，与吃饭的语境完全冲突。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机不是吃饭的地方，与“饭做好了”的语境冲突。"}, {"text": "书柜", "is_correct": false, "explanation": "配价：“来……这边”需要一个可供大家聚在一起吃饭的地点，“书柜”是存放书的家具，不能充当这样的地点。"}], "explanations": {"餐桌": "正确。“饭做好了，请大家来……这边”中的地点应是供人吃饭的桌子，餐桌符合句意。", "垃圾桶": "语义：饭做好了却叫大家去垃圾桶旁边，与吃饭的语境完全冲突。", "洗衣机": "语义：洗衣机不是吃饭的地方，与“饭做好了”的语境冲突。", "书柜": "配价：“来……这边”需要一个可供大家聚在一起吃饭的地点，“书柜”是存放书的家具，不能充当这样的地点。"}, "sentence_index": 0, "correct_answer": "餐桌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一个餐桌，放在厨房里。", "explanation": "这里应该用〈张〉。桌子用“张”计量，“个”不能用于餐桌。"}, {"text": "老师站在餐桌上讲课。", "explanation": "这里应该用〈讲台〉。讲课要站在讲台上；餐桌是供人吃饭用的桌子，不能站上去讲课。"}, {"text": "他躺在餐桌上看书。", "explanation": "这里应该用〈床〉。躺着看书要在床上；餐桌是吃饭用的，不能躺在上面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餐桌", "is_correct": true, "explanation": "正确。“这张……太小，坐不下八个人”说的是可以坐人的家具，餐桌符合句意。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不能用来坐人，“坐不下八个人”的主语不能是地图。"}, {"text": "床单", "is_correct": false, "explanation": "语义：床单是铺床用的织物，不是用来坐人的，与“坐不下八个人”的语境不符。"}, {"text": "纸", "is_correct": false, "explanation": "配价：“坐”的主体须是人或能坐人的家具，“纸”不能作为坐人的物体。"}], "explanations": {"餐桌": "正确。“这张……太小，坐不下八个人”说的是可以坐人的家具，餐桌符合句意。", "地图": "语义：地图不能用来坐人，“坐不下八个人”的主语不能是地图。", "床单": "语义：床单是铺床用的织物，不是用来坐人的，与“坐不下八个人”的语境不符。", "纸": "配价：“坐”的主体须是人或能坐人的家具，“纸”不能作为坐人的物体。"}, "sentence_index": 6, "correct_answer": "餐桌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一只新餐桌。", "explanation": "这里应该用〈张〉。桌子用“张”计量，“只”用于动物或成对的东西。"}, {"text": "妈妈把婴儿放在餐桌上睡觉。", "explanation": "这里应该用〈摇篮〉。哄婴儿睡觉要用摇篮；餐桌是吃饭用的，婴儿躺在上面很危险。"}, {"text": "她对着餐桌梳头。", "explanation": "这里应该用〈梳妆台〉。梳头、化妆要对着梳妆台；餐桌是吃饭用的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把餐桌擦很亮。", "corrected_sentence": "妈妈把餐桌擦得很亮。", "error_description": "补语错误：“擦”后面的状态补语“很亮”要用“得”连接，应说“擦得很亮”，不能直接说“擦很亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们昨天买了两只新餐桌。", "corrected_sentence": "他们昨天买了两张新餐桌。", "error_description": "量词错误：餐桌应用量词“张”计量，“只”用于动物或成对的东西，应说“两张新餐桌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
