INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25838, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "自己动手做，不是让别人帮忙。", "primary_collocate": null, "pronunciation": "qīn shǒu", "ipa": "tɕʰin˥ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "这是我亲手做的饭。", "target_word": "亲手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈亲手做了很多菜。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想亲手给他一朵花。", "target_word": "亲手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张画是弟弟亲手画的。", "target_word": "亲手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师亲手写了一封信。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他亲手做了一个小船。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸亲手给我做玩具。", "target_word": "亲手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件衣服是奶奶亲手做的。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我要亲手把信交给她。", "target_word": "亲手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她亲手种了一棵小树。", "target_word": "亲手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "自己动手做，不让别人帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f08d9b0-eeda-4784-a384-1aff1574232b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25838, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亲手", "is_correct": true, "explanation": "正确。亲手（qīn shǒu）指亲自用手做，与听到的读音一致。"}, {"text": "亲口", "is_correct": false, "explanation": "亲口（qīn kǒu）的第二音节是 kǒu，与 shǒu 的声母不同（k 与 sh），意思是用嘴说。"}, {"text": "亲友", "is_correct": false, "explanation": "亲友（qīn yǒu）的第二音节声母是 y，与 shǒu 的 sh 不同，意思是亲人和朋友。"}, {"text": "亲属", "is_correct": false, "explanation": "亲属（qīn shǔ）的第二音节韵母是 u，与 shǒu 的 ou 不同，意思是有血缘或婚姻关系的人。"}], "explanations": {"亲手": "正确。亲手（qīn shǒu）指亲自用手做，与听到的读音一致。", "亲口": "亲口（qīn kǒu）的第二音节是 kǒu，与 shǒu 的声母不同（k 与 sh），意思是用嘴说。", "亲友": "亲友（qīn yǒu）的第二音节声母是 y，与 shǒu 的 sh 不同，意思是亲人和朋友。", "亲属": "亲属（qīn shǔ）的第二音节韵母是 u，与 shǒu 的 ou 不同，意思是有血缘或婚姻关系的人。"}, "sentence_index": null, "correct_answer": "亲手"}, "level_3": {"options": [{"text": "亲手", "is_correct": true, "explanation": "正确。这里指我自己动手做饭，符合句意。"}, {"text": "亲口", "is_correct": false, "explanation": "搭配：“亲口”指用嘴说，做饭这一动作不能用它修饰。"}, {"text": "随口", "is_correct": false, "explanation": "搭配：“随口”指随便说出，不能修饰做饭。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”描述音量，与做饭这一动作无关，句意不通。"}], "explanations": {"亲手": "正确。这里指我自己动手做饭，符合句意。", "亲口": "搭配：“亲口”指用嘴说，做饭这一动作不能用它修饰。", "随口": "搭配：“随口”指随便说出，不能修饰做饭。", "大声": "语义：“大声”描述音量，与做饭这一动作无关，句意不通。"}, "sentence_index": 0, "correct_answer": "亲手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他亲手承认了错误。", "explanation": "这里应该用〈亲口〉。承认是用嘴说出来，“亲手”不能修饰这一动作，应说“亲口承认”。"}, {"text": "我亲手听到他的声音。", "explanation": "这里应该用〈亲耳〉。听靠耳朵，“亲手”不适用于听觉，应说“亲耳听到”。"}, {"text": "我亲手看见了日出。", "explanation": "这里应该用〈亲眼〉。看见靠眼睛，“亲手”不能用于视觉动作，应说“亲眼看见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲手", "is_correct": true, "explanation": "正确。这里表示爸爸自己动手做玩具，符合句意。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”表示突然发生，与做玩具这一需要持续时间的过程冲突。"}, {"text": "瞬间", "is_correct": false, "explanation": "搭配：“瞬间”表示极短的时间，做玩具需要一段时间，二者不搭配。"}, {"text": "顿时", "is_correct": false, "explanation": "语义：“顿时”表示立即出现的变化，与做玩具的过程不合。"}], "explanations": {"亲手": "正确。这里表示爸爸自己动手做玩具，符合句意。", "猛然": "语义：“猛然”表示突然发生，与做玩具这一需要持续时间的过程冲突。", "瞬间": "搭配：“瞬间”表示极短的时间，做玩具需要一段时间，二者不搭配。", "顿时": "语义：“顿时”表示立即出现的变化，与做玩具的过程不合。"}, "sentence_index": 6, "correct_answer": "亲手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我亲手经历过那次地震。", "explanation": "这里应该用〈亲身〉。亲手指手上的动作，经历地震不靠手，应说“亲身经历”。"}, {"text": "校长亲手参加了开幕式。", "explanation": "这里应该用〈亲自〉。参加活动不是手上的动作，应说“亲自参加”。"}, {"text": "我亲手见过那座古城。", "explanation": "这里应该用〈亲见〉。见到景物靠眼睛，“亲手”不能用于这种感知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个书架是爸爸亲手做了。", "corrected_sentence": "这个书架是爸爸亲手做的。", "error_description": "错误：“是……的”强调句的句末应用“的”，不能用“了”。正确是“这个书架是爸爸亲手做的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶亲手了缝这块布。", "corrected_sentence": "奶奶亲手缝了这块布。", "error_description": "错误：“了”误放在副词“亲手”和动词“缝”之间，应放在动词后。正确是“亲手缝了这块布”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新鲜", "is_correct": true, "explanation": "新鲜：食物未变质，与「腐败」（食物变质）相对。"}, {"text": "高大", "is_correct": false, "explanation": "高大形容个子或建筑高，与「腐败」没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色亮，与「腐败」没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "坚硬形容质地硬，与「腐败」没有反义关系。"}], "correct_answer": "新鲜", "explanations": {"新鲜": "新鲜：食物未变质，与「腐败」（食物变质）相对。", "高大": "高大形容个子或建筑高，与「腐败」没有反义关系。", "明亮": "明亮形容光线或颜色亮，与「腐败」没有反义关系。", "坚硬": "坚硬形容质地硬，与「腐败」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新鲜", "is_correct": true, "explanation": "新鲜：食物未变质，与「腐败」（食物变质）相对。"}, {"text": "勤奋", "is_correct": false, "explanation": "勤奋形容努力用功，与「腐败」没有反义关系。"}, {"text": "温和", "is_correct": false, "explanation": "温和形容性情平和，与「腐败」没有反义关系。"}, {"text": "朴素", "is_correct": false, "explanation": "朴素形容简单、不华丽，与「腐败」没有反义关系。"}], "correct_answer": "新鲜", "explanations": {"新鲜": "新鲜：食物未变质，与「腐败」（食物变质）相对。", "勤奋": "勤奋形容努力用功，与「腐败」没有反义关系。", "温和": "温和形容性情平和，与「腐败」没有反义关系。", "朴素": "朴素形容简单、不华丽，与「腐败」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西变坏了，比如食物发霉不能吃。", "primary_collocate": null, "pronunciation": "fǔ bài", "ipa": "fu˨˩˦ pai˥˩", "syllable_count": 2, "sentences": [{"text": "这些水果放太久，已经腐败了。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "腐败的食物不能吃。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太热，鱼很快就腐败了。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱能让牛奶不容易腐败。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房里有一股腐败的味道。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "剩菜放在桌上慢慢腐败了。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把腐败的肉扔进了垃圾桶。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "米饭没放进冰箱，第二天就腐败了。", "target_word": "腐败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盒鸡蛋腐败了，不要再吃。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "潮湿的粮食容易腐败。", "target_word": "腐败", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "腐败了", "label": "体标"}, {"form": "腐败的", "label": "复合"}, {"form": "腐敗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "食物、肉类等东西变质发臭、不能再吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14c65f7f-0b0a-4240-89c9-7a856accbf3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腐败", "is_correct": true, "explanation": "腐败：食物变质。此处指水果放太久已经变质。"}, {"text": "干净", "is_correct": false, "explanation": "语义：「干净」指清洁，放太久的水果不会变得干净，与「放太久」的变化相反。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：「坚硬」用于形容物体的质地，水果放久不会变得坚硬。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：「明亮」形容光线，与食物变质的状态无关。"}], "explanations": {"腐败": "腐败：食物变质。此处指水果放太久已经变质。", "干净": "语义：「干净」指清洁，放太久的水果不会变得干净，与「放太久」的变化相反。", "坚硬": "搭配：「坚硬」用于形容物体的质地，水果放久不会变得坚硬。", "明亮": "语义：「明亮」形容光线，与食物变质的状态无关。"}, "sentence_index": 0, "correct_answer": "腐败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把铁刀放在雨里，已经腐败了。", "explanation": "这里应该用〈生锈〉。腐败指食物等有机物变质，金属在雨中变色要用「生锈」。"}, {"text": "冰块放在太阳下，已经腐败了。", "explanation": "这里应该用〈融化〉。冰块受热变成水要用「融化」，腐败只用于食物等变质。"}, {"text": "这块塑料放在火上，已经腐败了。", "explanation": "这里应该用〈变形〉。塑料受热改变形状要用「变形」，塑料不会腐败。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腐败", "is_correct": true, "explanation": "腐败：肉已经变质。此处指变质的肉，所以要扔掉。"}, {"text": "美味", "is_correct": false, "explanation": "语义：「美味」指好吃，与扔进垃圾桶的情景相矛盾。"}, {"text": "清香", "is_correct": false, "explanation": "语义：「清香」形容气味清爽，与被扔掉的肉的状态不相符。"}, {"text": "发光", "is_correct": false, "explanation": "搭配：「发光」形容物体自身发亮，不用来描述肉的状态。"}], "explanations": {"腐败": "腐败：肉已经变质。此处指变质的肉，所以要扔掉。", "美味": "语义：「美味」指好吃，与扔进垃圾桶的情景相矛盾。", "清香": "语义：「清香」形容气味清爽，与被扔掉的肉的状态不相符。", "发光": "搭配：「发光」形容物体自身发亮，不用来描述肉的状态。"}, "sentence_index": 6, "correct_answer": "腐败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上的油漆已经腐败了。", "explanation": "这里应该用〈褪色〉。腐败指食物等有机物变质，油漆颜色变淡要用「褪色」。"}, {"text": "这台旧手机用了五年，已经腐败了。", "explanation": "这里应该用〈老化〉。手机用久了性能变差要用「老化」，腐败不用于电子产品。"}, {"text": "杯子不小心摔在地上，已经腐败了。", "explanation": "这里应该用〈破碎〉。杯子摔裂成碎片要用「破碎」，腐败只用于食物等变质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些菜在厨房里放了三天，被腐败了。", "corrected_sentence": "这些菜在厨房里放了三天，已经腐败了。", "error_description": "「腐败」是形容词，不能用「被」构成被动句。应说「已经腐败了」，去掉「被」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块肉放在厨房一夜，就腐败很厉害了。", "corrected_sentence": "这块肉放在厨房一夜，就腐败得很厉害了。", "error_description": "「腐败」后面要用补语标志「得」引出程度补语。应说「腐败得很厉害」，不能直接说「腐败很厉害」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
