INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25844, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "基石是建房子时放在最下面的石头，用来让房子更稳。", "primary_collocate": null, "pronunciation": "jī shí", "ipa": "tɕi˥ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "盖房子时，工人先放好最下面的基石。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座老房子的基石是一块大石头。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子的基石放得稳，房子才不会歪。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们在地基上放了第一块基石。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块基石很重，两个人才搬得动。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老桥最下面的基石已经有一百年了。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在新楼的基石上刻了日期。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，房子下面的基石还是很稳。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅用车把一块基石运到了工地。", "target_word": "基石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有基石，房子盖得再高也不稳。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}], "register": "中性", "sense_fingerprint": "本义：建房时放在最底下、使房子稳固的石头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07a53c-a9cf-4bf8-a96d-3c0a8dd8e503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25844, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集市", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是集市。"}, {"text": "基石", "is_correct": true, "explanation": "正确：基石，jī shí，建房时放在最下面、使房子稳固的石头。"}, {"text": "纪实", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，shí 相同，意思是记录真实的情况。"}, {"text": "即使", "is_correct": false, "explanation": "jí（第二声）与 jī 声调不同，shǐ（第三声）与 shí 的声调也不同，意思是“即便”。"}, {"text": "几十", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，shí 相同，意思是几十。"}], "explanations": {"集市": "jí（第二声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是集市。", "基石": "正确：基石，jī shí，建房时放在最下面、使房子稳固的石头。", "纪实": "jì（第四声）与 jī（第一声）声调不同，shí 相同，意思是记录真实的情况。", "即使": "jí（第二声）与 jī 声调不同，shǐ（第三声）与 shí 的声调也不同，意思是“即便”。", "几十": "jǐ（第三声）与 jī（第一声）声调不同，shí 相同，意思是几十。"}, "sentence_index": null, "correct_answer": "基石"}, "level_3": {"options": [{"text": "屋顶", "is_correct": false, "explanation": "语义：屋顶在房子的最上面，与“最下面的”相矛盾。"}, {"text": "云", "is_correct": false, "explanation": "语义：云是天上的水汽，不能被“放好”，与施工的语境冲突。"}, {"text": "基石", "is_correct": true, "explanation": "正确：“基石”指建房时放在最下面的石头，与“放好最下面的”搭配。"}, {"text": "信心", "is_correct": false, "explanation": "搭配：“放好”不能与“信心”搭配，“信心”也不是建筑构件。"}], "explanations": {"屋顶": "语义：屋顶在房子的最上面，与“最下面的”相矛盾。", "云": "语义：云是天上的水汽，不能被“放好”，与施工的语境冲突。", "基石": "正确：“基石”指建房时放在最下面的石头，与“放好最下面的”搭配。", "信心": "搭配：“放好”不能与“信心”搭配，“信心”也不是建筑构件。"}, "sentence_index": 0, "correct_answer": "基石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这枚戒指上镶着一块基石。", "explanation": "这里应该用〈宝石〉。“宝石”是镶在戒指上的装饰石，“基石”指建房时放在最下面的石头，不能用来指戒指上的宝石，应说“宝石”。"}, {"text": "这块基石很透明。", "explanation": "这里应该用〈玻璃〉。“玻璃”可以透明，“基石”是建房用的石头，不能用“透明”来形容，应说“玻璃”。"}, {"text": "这块基石很嫩。", "explanation": "这里应该用〈豆腐〉。“嫩”形容豆腐、蔬菜等柔软的食物，“基石”是坚硬的石头，不能用“嫩”来形容，应说“豆腐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25844, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "急事", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是紧急的事。"}, {"text": "基石", "is_correct": true, "explanation": "正确：基石，jī shí，建房时放在最下面、使房子稳固的石头。"}, {"text": "几时", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，shí 相同，意思是“什么时候”。"}, {"text": "纪实", "is_correct": false, "explanation": "jì（第四声）与 jī 声调不同，shí 相同，意思是记录真实的情况。"}, {"text": "记事", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是记录事情。"}], "explanations": {"急事": "jí（第二声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是紧急的事。", "基石": "正确：基石，jī shí，建房时放在最下面、使房子稳固的石头。", "几时": "jǐ（第三声）与 jī（第一声）声调不同，shí 相同，意思是“什么时候”。", "纪实": "jì（第四声）与 jī 声调不同，shí 相同，意思是记录真实的情况。", "记事": "jì（第四声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是记录事情。"}, "sentence_index": null, "correct_answer": "基石"}, "level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不能在上面刻字或刻日期。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光照下的暗像，无法刻上日期。"}, {"text": "基石", "is_correct": true, "explanation": "正确：“基石”是建筑的实体构件，能刻上日期，与“新楼的”搭配。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“脸”是人的面部，不能用来指新楼的部件。"}], "explanations": {"空气": "语义：空气是无形的气体，不能在上面刻字或刻日期。", "影子": "语义：影子是光照下的暗像，无法刻上日期。", "基石": "正确：“基石”是建筑的实体构件，能刻上日期，与“新楼的”搭配。", "脸": "体貌：“脸”是人的面部，不能用来指新楼的部件。"}, "sentence_index": 6, "correct_answer": "基石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在书里夹了一块基石当书签。", "explanation": "这里应该用〈书签〉。“书签”是夹在书里做标记的东西，“基石”指建房的石头，不能当书签用，应说“书签”。"}, {"text": "这块基石很快就化了。", "explanation": "这里应该用〈冰〉。“化”用于冰、雪等融化，“基石”是石头，不会融化，应说“冰”。"}, {"text": "她的基石很动听。", "explanation": "这里应该用〈歌声〉。“动听”形容声音，“基石”是建房用的石头，不能用来形容动听，应说“歌声”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子的角落里摆着一只基石。", "corrected_sentence": "院子的角落里摆着一块基石。", "error_description": "量词错误：“基石”应搭配量词“块”，“只”用于动物等，应说“一块基石”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们挖了出那块基石。", "corrected_sentence": "工人们挖出了那块基石。", "error_description": "补语位置错误：“挖出”是结果补语，“了”应放在“出”之后，说“挖出了那块基石”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "再次活过来或重新开始生活。", "primary_collocate": null, "pronunciation": "chóng shēng", "ipa": "ʈʂʰʊŋ˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "传说中，凤凰会在火里重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在游戏里死了，过一会儿又重生了。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人希望死后可以重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说，要是能重生，还想当老师。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的主角重生到了十年前。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话里，这个英雄死后又重生了。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火过后，草地上的小草慢慢重生了。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想离开旧生活，重生一次。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络小说常写主角重生回到学生时代。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你相信人死后能重生吗？", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重生了", "label": "体标"}, {"form": "重生过", "label": "体标"}], "register": "中性", "sense_fingerprint": "死后再次活过来，或重新开始生活（动词用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f08d9b0-eeda-4784-a384-1aff1574232b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重生", "is_correct": true, "explanation": "正确。“凤凰会在火里重生”指凤凰在火中再次活过来，符合神话情境。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：凤凰的神话是再生，“逃跑”表示离开，与“在火里”的再生情境不合。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”描述的是火的状态，不能用来描述凤凰的行为。"}, {"text": "哭泣", "is_correct": false, "explanation": "搭配：“哭泣”不能与“在火里”搭配来描述凤凰的行为。"}], "explanations": {"重生": "正确。“凤凰会在火里重生”指凤凰在火中再次活过来，符合神话情境。", "逃跑": "语义：凤凰的神话是再生，“逃跑”表示离开，与“在火里”的再生情境不合。", "熄灭": "语义：“熄灭”描述的是火的状态，不能用来描述凤凰的行为。", "哭泣": "搭配：“哭泣”不能与“在火里”搭配来描述凤凰的行为。"}, "sentence_index": 0, "correct_answer": "重生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爷爷是在一个寒冷的冬天重生的。", "explanation": "这里应该用〈出生〉。重生指再次活过来或重新开始生活，人第一次来到世界应说“出生”。"}, {"text": "我们下周重生。", "explanation": "这里应该用〈搬家〉。重生不指迁移居住地，句中“下周”的安排应说“搬家”。"}, {"text": "这台电脑昨天重生了。", "explanation": "这里应该用〈重启〉。重生指人或生命、状态重新开始，电脑重新开机应说“重启”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重生", "is_correct": true, "explanation": "正确。“草地上的小草慢慢重生了”指大火后小草重新生长，符合句意。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：小草不能结婚，与句子主语及描写的情境不合。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：小草不会歌唱，“歌唱”与描写植物恢复的语境不合。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”不能与“小草”搭配，句意不通。"}], "explanations": {"重生": "正确。“草地上的小草慢慢重生了”指大火后小草重新生长，符合句意。", "结婚": "语义：小草不能结婚，与句子主语及描写的情境不合。", "歌唱": "语义：小草不会歌唱，“歌唱”与描写植物恢复的语境不合。", "游泳": "搭配：“游泳”不能与“小草”搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "重生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子昨天重生了。", "explanation": "这里应该用〈修复〉。重生指再次活过来或重新开始生活，损坏的家具恢复原状应说“修复”。"}, {"text": "这个孩子去年重生了三公分。", "explanation": "这里应该用〈长高〉。重生指再次活过来或重新开始生活，身高增加应说“长高”。"}, {"text": "这封信刚才重生了。", "explanation": "这里应该用〈寄到〉。重生指人或生命、状态重新开始，信件送达应说“寄到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人终于被重生了。", "corrected_sentence": "这位老人终于重生了。", "error_description": "“重生”是不及物动词，不能用“被”构成被动句，应说“重生了”，这里误加了“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在那场病后重生着一次。", "corrected_sentence": "他在那场病后重生了一次。", "error_description": "错误：“重生”表示一次性的变化，不能用表示持续状态的“着”，应用“了”，说“重生了一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
