INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人心里的想法、感受和情绪。", "primary_collocate": null, "pronunciation": "xīn lǐ", "ipa": "ɕin˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "孩子的心理很简单。", "target_word": "心理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想了解小孩的心理。", "target_word": "心理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试以前，很多人心理压力很大。", "target_word": "心理", "complexity_tier": "T3", "furigana": "xīnlǐ", "sentence_source": "generated"}, {"text": "老师很关心学生的心理。", "target_word": "心理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "了解客人的心理，才能把东西卖好。", "target_word": "心理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不明白她为什么这样做，也不懂她的心理。", "target_word": "心理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的话让他的心理负担轻了很多。", "target_word": "心理", "complexity_tier": "T3", "furigana": "xīnlǐ", "sentence_source": "generated"}, {"text": "搬家以后，孩子的心理有一些变化。", "target_word": "心理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛以前，运动员的心理很重要。", "target_word": "心理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人一个人住，心理上常常觉得孤单。", "target_word": "心理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词，指人心里的想法、感受和情绪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20eaa319-c57d-469c-b2b7-b9adb94399fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25848, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "心理", "is_correct": true, "explanation": "正确：心理（xīnlǐ）指人心里的想法、感受和情绪。"}, {"text": "欣喜", "is_correct": false, "explanation": "欣喜（xīnxǐ）指高兴。xǐ 与 lǐ 声母不同（x／l），听起来不同。"}, {"text": "行李", "is_correct": false, "explanation": "行李（xínglǐ）指出门带的箱包。xíng 与 xīn 韵母不同，声调也不同。"}, {"text": "心领", "is_correct": false, "explanation": "心领（xīnlǐng）指领情、心里领会。lǐng 比 lǐ 多一个 ng 韵尾。"}, {"text": "心底", "is_correct": false, "explanation": "心底（xīndǐ）指心里深处。dǐ 与 lǐ 声母不同（d／l）。"}], "explanations": {"心理": "正确：心理（xīnlǐ）指人心里的想法、感受和情绪。", "欣喜": "欣喜（xīnxǐ）指高兴。xǐ 与 lǐ 声母不同（x／l），听起来不同。", "行李": "行李（xínglǐ）指出门带的箱包。xíng 与 xīn 韵母不同，声调也不同。", "心领": "心领（xīnlǐng）指领情、心里领会。lǐng 比 lǐ 多一个 ng 韵尾。", "心底": "心底（xīndǐ）指心里深处。dǐ 与 lǐ 声母不同（d／l）。"}, "sentence_index": null, "correct_answer": "心理"}, "level_3": {"options": [{"text": "心理", "is_correct": true, "explanation": "正确：心理指人的想法和感受，“孩子的心理很简单”成立。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“简单”不能用来形容身高。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是孩子自身的属性，“孩子的天气”说不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“很简单”不能用来形容体温。"}], "explanations": {"心理": "正确：心理指人的想法和感受，“孩子的心理很简单”成立。", "身高": "搭配：“简单”不能用来形容身高。", "天气": "语义：天气不是孩子自身的属性，“孩子的天气”说不通。", "体温": "搭配：“很简单”不能用来形容体温。"}, "sentence_index": 0, "correct_answer": "心理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心理很善良，经常帮助别人。", "explanation": "这里应该用〈心地〉。说人品性善良要用心地，心理指心里的想法和感受，不用来形容品性。"}, {"text": "他把所有心理都放在学习上。", "explanation": "这里应该用〈心思〉。“把心思放在某事上”说的是注意力，心理不这样用。"}, {"text": "听到好消息，他的心理十分高兴。", "explanation": "这里应该用〈心情〉。“高兴”说的是一时的情绪，心理不用来表示心情好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25848, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "心理", "is_correct": true, "explanation": "正确：心理（xīnlǐ）指人心里的想法、感受和情绪。"}, {"text": "心力", "is_correct": false, "explanation": "心力（xīnlì）指精神和力量。lì（第四声）与 lǐ（第三声）声调不同。"}, {"text": "心灵", "is_correct": false, "explanation": "心灵（xīnlíng）指内心、精神世界。líng 比 lǐ 多一个 ng 韵尾，声调也不同。"}, {"text": "心死", "is_correct": false, "explanation": "心死（xīnsǐ）指心灰意冷。sǐ 与 lǐ 声母不同（s／l）。"}], "explanations": {"心理": "正确：心理（xīnlǐ）指人心里的想法、感受和情绪。", "心力": "心力（xīnlì）指精神和力量。lì（第四声）与 lǐ（第三声）声调不同。", "心灵": "心灵（xīnlíng）指内心、精神世界。líng 比 lǐ 多一个 ng 韵尾，声调也不同。", "心死": "心死（xīnsǐ）指心灰意冷。sǐ 与 lǐ 声母不同（s／l）。"}, "sentence_index": null, "correct_answer": "心理"}, "level_3": {"options": [{"text": "心理", "is_correct": true, "explanation": "正确：“心理负担”是常用搭配，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会形成负担，句子说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不会形成负担，句子说不通。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“负担”只说心理、经济、学习等负担，不与尺寸搭配。"}], "explanations": {"心理": "正确：“心理负担”是常用搭配，句意通顺。", "颜色": "语义：颜色不会形成负担，句子说不通。", "味道": "语义：味道不会形成负担，句子说不通。", "尺寸": "搭配：“负担”只说心理、经济、学习等负担，不与尺寸搭配。"}, "sentence_index": 6, "correct_answer": "心理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一紧张，心理就跳得很快。", "explanation": "这里应该用〈心脏〉。“跳得很快”说的是心脏的活动，心理指心里的想法和感受，不指器官。"}, {"text": "他为这本书花了很多心理。", "explanation": "这里应该用〈心血〉。“花心血”说的是付出的精力，心理指心里的想法和感受，不能用来表示付出。"}, {"text": "这是我的一点心理，请收下。", "explanation": "这里应该用〈心意〉。送礼时说“一点心意”，心理指心里的想法和感受，不能用来表示礼物的心意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很在意孩子的心理们。", "corrected_sentence": "他很在意孩子的心理。", "error_description": "用法错误：“心理”是抽象名词，不能加“们”表示复数；“孩子的心理们”不通，应删去“们”，写作“他很在意孩子的心理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地心理素质很好，不怕困难。", "corrected_sentence": "他的心理素质很好，不怕困难。", "error_description": "结构助词错误：“心理素质”是名词短语，修饰语后应用“的”，不能用“地”（地多用于修饰动词、形容词），应说“他的心理素质很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
