INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25850, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这个词的意思是某件事包含的意义。", "primary_collocate": null, "pronunciation": "yì hán", "ipa": "i˥˩ xan˧˥", "syllable_count": 2, "sentences": [{"text": "这件事的意涵很重要。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了解这个手势的意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标志有什么意涵？", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有看出这封信的意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "礼物的价格不重要，意涵才重要。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要明白这次活动的意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个仪式对家人有特别的意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个符号的意涵是和平。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们课文的意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句广告词没有什么意涵。", "target_word": "意涵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层意涵", "label": "量词"}], "register": "书面", "sense_fingerprint": "某件事所包含的意义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f08d9b0-eeda-4784-a384-1aff1574232b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意涵", "is_correct": true, "explanation": "「意涵」指某件事所包含的意义，与「这件事的……很重要」的语境一致。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指人或动物的重量，不能用于「这件事的」。"}, {"text": "身高", "is_correct": false, "explanation": "语义：「身高」指人的高度，与一件事的内容无关。"}, {"text": "尺码", "is_correct": false, "explanation": "搭配：「尺码」指衣物或鞋的大小，不能与「这件事的」搭配。"}], "explanations": {"意涵": "「意涵」指某件事所包含的意义，与「这件事的……很重要」的语境一致。", "体重": "语义：「体重」指人或动物的重量，不能用于「这件事的」。", "身高": "语义：「身高」指人的高度，与一件事的内容无关。", "尺码": "搭配：「尺码」指衣物或鞋的大小，不能与「这件事的」搭配。"}, "sentence_index": 0, "correct_answer": "意涵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是我送你的一点意涵。", "explanation": "这里应该用〈心意〉。意涵指事物所包含的意义，送礼表达诚意要说心意。"}, {"text": "这幅画的意涵很鲜艳。", "explanation": "这里应该用〈颜色〉。意涵是抽象的意义，不能用「鲜艳」形容。"}, {"text": "这杯咖啡的意涵很烫。", "explanation": "这里应该用〈温度〉。意涵不能用「烫」来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意涵", "is_correct": true, "explanation": "「意涵」指仪式所包含的意义，与「对家人有特别的」的语境一致。"}, {"text": "体积", "is_correct": false, "explanation": "语义：「体积」指物体占据的空间，与仪式的意义无关。"}, {"text": "腰围", "is_correct": false, "explanation": "语义：「腰围」指人的腰部尺寸，不能用于仪式。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「特别的」不能与「年龄」搭配来描述仪式。"}], "explanations": {"意涵": "「意涵」指仪式所包含的意义，与「对家人有特别的」的语境一致。", "体积": "语义：「体积」指物体占据的空间，与仪式的意义无关。", "腰围": "语义：「腰围」指人的腰部尺寸，不能用于仪式。", "年龄": "搭配：「特别的」不能与「年龄」搭配来描述仪式。"}, "sentence_index": 6, "correct_answer": "意涵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路的意涵很长。", "explanation": "这里应该用〈长度〉。意涵是抽象的意义，不能用「长」来衡量。"}, {"text": "这道汤的意涵很鲜。", "explanation": "这里应该用〈味道〉。意涵不能用「鲜」来形容。"}, {"text": "这辆车的意涵很快。", "explanation": "这里应该用〈速度〉。意涵不能用速度来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首诗有一只深刻的意涵。", "corrected_sentence": "这首诗有一层深刻的意涵。", "error_description": "错误：量词用错。「意涵」应使用量词「层」，不用「只」。正确是「一层深刻的意涵」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个符号的意涵是清楚。", "corrected_sentence": "这个符号的意涵很清楚。", "error_description": "错误：「清楚」作谓语时前面应用「很」，不能用「是」。「是」后接形容词不通顺，应说「意涵很清楚」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
