INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25852, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放错了地方。", "primary_collocate": null, "pronunciation": "cuò zhì", "ipa": "tsʰuo˥˩ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈把我的作业错置在了桌子下面。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把盐错置在糖罐旁边，差点用错。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把货错置在别的架子上。", "target_word": "错置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本词典错置在儿童书架上。", "target_word": "错置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把护照错置了，现在到处找。", "target_word": "错置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她发现眼镜错置在了洗手间。", "target_word": "错置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作人员错置了几份文件，所以客人没收到。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把玩具错置在厨房门口。", "target_word": "错置", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药错置在孩子够得到的地方很危险。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是把东西错置，所以常常找不到。", "target_word": "错置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "错置了", "label": "体标"}, {"form": "错置过", "label": "体标"}, {"form": "錯置", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把具体的东西放错了地方，一时找不到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14c65f7f-0b0a-4240-89c9-7a856accbf3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25852, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "错置", "is_correct": true, "explanation": "错置：把东西放错了地方。"}, {"text": "挫折", "is_correct": false, "explanation": "zhé（第二声）与 zhì（第四声）声调不同，意思是挫折。"}, {"text": "错字", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），意思是写错的字。"}, {"text": "错事", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是做错的事。"}], "explanations": {"错置": "错置：把东西放错了地方。", "挫折": "zhé（第二声）与 zhì（第四声）声调不同，意思是挫折。", "错字": "zì 与 zhì 声母不同（z 与 zh），意思是写错的字。", "错事": "shì 与 zhì 声母不同（sh 与 zh），意思是做错的事。"}, "sentence_index": null, "correct_answer": "错置"}, "level_3": {"options": [{"text": "错置", "is_correct": true, "explanation": "正确：「错置」指把东西放错地方，符合「作业被放在桌子下面」的语境。"}, {"text": "修补", "is_correct": false, "explanation": "语义：「修补」指修好破损的地方，与「放在桌子下面」的动作无关。"}, {"text": "赞美", "is_correct": false, "explanation": "配价：「赞美」的受事是人或作品，不能带「在……下面」这样的处所补语。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：「翻译」指转换语言，与「把作业放在桌子下面」的动作不相符。"}], "explanations": {"错置": "正确：「错置」指把东西放错地方，符合「作业被放在桌子下面」的语境。", "修补": "语义：「修补」指修好破损的地方，与「放在桌子下面」的动作无关。", "赞美": "配价：「赞美」的受事是人或作品，不能带「在……下面」这样的处所补语。", "翻译": "语义：「翻译」指转换语言，与「把作业放在桌子下面」的动作不相符。"}, "sentence_index": 0, "correct_answer": "错置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店员特意把新款皮鞋错置在橱窗里。", "explanation": "这里应该用〈陈列〉。错置指无意中放错地方，与「特意」矛盾。"}, {"text": "妈妈把孩子错置在床上，让他睡觉。", "explanation": "这里应该用〈放〉。错置只用于物品放错地方，不能用来指人；把孩子放在床上应说放。"}, {"text": "我把这本书错置给了同学。", "explanation": "这里应该用〈借〉。错置只表示东西放错了地方，不能带接受者，把书借给同学要说借。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错置", "is_correct": true, "explanation": "正确：「错置」指文件被放错地方，因此客人没有收到。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：「歌颂」指赞美颂扬，与文件的递送无关。"}, {"text": "热爱", "is_correct": false, "explanation": "搭配：「热爱」的对象是事业或人，不能说「热爱几份文件」。"}, {"text": "安慰", "is_correct": false, "explanation": "配价：「安慰」的对象是人，不能以「文件」为受事。"}], "explanations": {"错置": "正确：「错置」指文件被放错地方，因此客人没有收到。", "歌颂": "语义：「歌颂」指赞美颂扬，与文件的递送无关。", "热爱": "搭配：「热爱」的对象是事业或人，不能说「热爱几份文件」。", "安慰": "配价：「安慰」的对象是人，不能以「文件」为受事。"}, "sentence_index": 6, "correct_answer": "错置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这件事错置了三天，没有处理。", "explanation": "这里应该用〈搁置〉。错置指把东西放错地方，不指暂时不处理的事。"}, {"text": "她把花草错置得错落有致，大家都很喜欢。", "explanation": "这里应该用〈布置〉。错置只表示放错位置，不能用来描述错落有致的效果。"}, {"text": "他把大量精力错置在了工作上。", "explanation": "这里应该用〈投入〉。错置用于东西放错地方，精力用在某事上要说投入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸把一只钥匙错置在了鞋柜上。", "corrected_sentence": "爸爸把一把钥匙错置在了鞋柜上。", "error_description": "错误：「一只钥匙」，钥匙的量词应为「把」，「只」多用于动物或成对物品中的一个。正确：「一把钥匙」，「把」用于有柄或成串的器物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把钥匙错置了抽屉里，找了半天。", "corrected_sentence": "他把钥匙错置在了抽屉里，找了半天。", "error_description": "错误：「错置了抽屉里」，缺少处所介词「在」，「错置」后要用「在」引出放置的处所。正确：「错置在了抽屉里」，「在」引出处所，「了」表示动作完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcd36771-17d4-4423-9451-362cc475cad7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
