INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "市政就是管理城市的事情，比如修路、打扫街道。", "primary_collocate": null, "pronunciation": "shì zhèng", "ipa": "ʂɻ̩˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "修路是市政的工作。", "target_word": "市政", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "市政工人在扫街道。", "target_word": "市政", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我叔叔做市政工作，每天都很忙。", "target_word": "市政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的花是市政种的。", "target_word": "市政", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨后，市政马上来清理路上的水。", "target_word": "市政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政每年都会修很多路。", "target_word": "市政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街很干净，因为市政天天打扫。", "target_word": "市政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有大坑，市政已经来看过了。", "target_word": "市政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想进市政部门，为城市做事。", "target_word": "市政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政管的是城市里的大事小事。", "target_word": "市政", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "管理城市的事务如修路扫街", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78fdf4f0-324a-48ce-8d2c-3732d912f7c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25858, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市政", "is_correct": true, "explanation": "正确：指管理城市事务，如修路、打扫街道，即本题释义所说的市政。"}, {"text": "时政", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是时事政治。"}, {"text": "施政", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是施行政务。"}, {"text": "市镇", "is_correct": false, "explanation": "zhèn 与 zhèng 韵尾不同，意思是城镇。"}], "explanations": {"市政": "正确：指管理城市事务，如修路、打扫街道，即本题释义所说的市政。", "时政": "shí（第二声）与 shì（第四声）声调不同，意思是时事政治。", "施政": "shī（第一声）与 shì（第四声）声调不同，意思是施行政务。", "市镇": "zhèn 与 zhèng 韵尾不同，意思是城镇。"}, "sentence_index": null, "correct_answer": "市政"}, "level_3": {"options": [{"text": "市政", "is_correct": true, "explanation": "正确：“修路是市政的工作”中，市政指管理城市事务，与修路相符。"}, {"text": "农业", "is_correct": false, "explanation": "语义：修路不属于农业工作，“农业的工作”与句意不合。"}, {"text": "医疗", "is_correct": false, "explanation": "语义：修路不是医疗工作，“医疗的工作”与句意不合。"}, {"text": "文化", "is_correct": false, "explanation": "语义：修路与文化事务无关，与句意不合。"}], "explanations": {"市政": "正确：“修路是市政的工作”中，市政指管理城市事务，与修路相符。", "农业": "语义：修路不属于农业工作，“农业的工作”与句意不合。", "医疗": "语义：修路不是医疗工作，“医疗的工作”与句意不合。", "文化": "语义：修路与文化事务无关，与句意不合。"}, "sentence_index": 0, "correct_answer": "市政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个市政很热闹，有很多人在买东西。", "explanation": "这里应该用〈市场〉。市政指管理事务，不是人们买东西的地方。"}, {"text": "市政今天来学校演讲，同学们都很兴奋。", "explanation": "这里应该用〈市长〉。市政指管理事务，不能像人一样来学校演讲。"}, {"text": "他是一位市政，每天很忙。", "explanation": "指人时应说〈市政人员〉。“市政”本身不表示人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市政", "is_correct": true, "explanation": "正确：“因为市政天天打扫”中，市政指管理城市事务的部门，与打扫街道相符。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不会打扫街道，“因为狗天天打扫”与句意不合。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不会主动打扫，“因为花园天天打扫”与句意不合。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气天天打扫”不成搭配，空气不能被打扫。"}], "explanations": {"市政": "正确：“因为市政天天打扫”中，市政指管理城市事务的部门，与打扫街道相符。", "狗": "语义：狗不会打扫街道，“因为狗天天打扫”与句意不合。", "花园": "语义：花园不会主动打扫，“因为花园天天打扫”与句意不合。", "空气": "搭配：“空气天天打扫”不成搭配，空气不能被打扫。"}, "sentence_index": 6, "correct_answer": "市政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座市政很大，人口很多。", "explanation": "这里应该用〈城市〉。市政指管理事务，不能指城市本身。"}, {"text": "市政里有很多老人，大家都很友好。", "explanation": "这里应该用〈社区〉。市政指管理事务，不是人们居住的地方。"}, {"text": "厨房里的市政很香，大家都想吃。", "explanation": "这里应该用〈菜〉。市政指管理事务，不是食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐很在市政部门上班。", "corrected_sentence": "我姐姐在市政部门上班。", "error_description": "副词位置错误：“很”是程度副词，不能用在介词短语“在市政部门”前，应删去“很”，说“我姐姐在市政部门上班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事很市政。", "corrected_sentence": "这件事属于市政。", "error_description": "词性错误：市政是名词，不能被“很”修饰；应说“属于市政”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0effabb2-768f-4d54-a8ea-0deaa2336a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
