INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25860, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "帮助别人做事。", "primary_collocate": null, "pronunciation": "fǔ zhù", "ipa": "fu˨˩˦ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他每天辅助爸爸打理小店。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在会议上辅助经理记录。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者辅助老人过马路。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在实验室辅助教授做研究。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟来辅助我搬家。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你辅助我完成这份工作吧。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王辅助同事整理了资料。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里，小李辅助师傅切菜。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不会走路时，大人要辅助他。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她愿意辅助朋友开一家咖啡店。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辅助了", "label": "体标"}, {"form": "辅助过", "label": "体标"}], "register": "书面", "sense_fingerprint": "帮助别人做事（动词用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f08d9b0-eeda-4784-a384-1aff1574232b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辅助", "is_correct": true, "explanation": "「辅助」表示从旁帮助别人做事，与「爸爸打理小店」的语境一致。"}, {"text": "出版", "is_correct": false, "explanation": "语义：「出版」的对象是书刊，不能用于「爸爸打理小店」。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：「翻译」的对象是语言文字，不能与「打理小店」搭配。"}, {"text": "发明", "is_correct": false, "explanation": "语义：「发明」指创造新事物，与日常打理小店的事不合。"}], "explanations": {"辅助": "「辅助」表示从旁帮助别人做事，与「爸爸打理小店」的语境一致。", "出版": "语义：「出版」的对象是书刊，不能用于「爸爸打理小店」。", "翻译": "搭配：「翻译」的对象是语言文字，不能与「打理小店」搭配。", "发明": "语义：「发明」指创造新事物，与日常打理小店的事不合。"}, "sentence_index": 0, "correct_answer": "辅助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "王经理亲自辅助这个项目的全部工作。", "explanation": "这里应该用〈领导〉。辅助是从旁帮忙，不能表示主导整个项目。"}, {"text": "工人辅助了一座大桥。", "explanation": "这里应该用〈建造〉。辅助的对象是人或具体任务，不能是建成的物体。"}, {"text": "老师辅助学生的成绩。", "explanation": "这里应该用〈提高〉。辅助指从旁帮忙做事，不用于直接改变成绩这种结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辅助", "is_correct": true, "explanation": "「辅助」表示帮助同事做事，与「整理了资料」的语境一致。"}, {"text": "销售", "is_correct": false, "explanation": "搭配：「销售」的对象是商品，不能用于「同事整理了资料」。"}, {"text": "录取", "is_correct": false, "explanation": "语义：「录取」指录用人员，与整理资料的事无关。"}, {"text": "测量", "is_correct": false, "explanation": "语义：「测量」指量取长度、面积等，与整理资料不符。"}], "explanations": {"辅助": "「辅助」表示帮助同事做事，与「整理了资料」的语境一致。", "销售": "搭配：「销售」的对象是商品，不能用于「同事整理了资料」。", "录取": "语义：「录取」指录用人员，与整理资料的事无关。", "测量": "语义：「测量」指量取长度、面积等，与整理资料不符。"}, "sentence_index": 6, "correct_answer": "辅助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她愿意辅助朋友的书包。", "explanation": "这里应该用〈背〉。辅助的对象是做事的人，不能以书包这类物品为对象；帮朋友拿书包应说“背”。"}, {"text": "她愿意辅助朋友的失败。", "explanation": "这里应该用〈承受〉。辅助是从旁帮忙做事，不能用于朋友的失败这类结果。"}, {"text": "她愿意辅助朋友的汽车。", "explanation": "这里应该用〈修〉。辅助的对象是做事的人，不能以汽车这类物品为对象；修理汽车应说“修”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我会不辅助他做这件事。", "corrected_sentence": "我不会辅助他做这件事。", "error_description": "错误：否定词「不」的位置不对。正确是「不会辅助」，「不」应放在助动词「会」之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我愿意辅助过弟弟学习英语。", "corrected_sentence": "我愿意辅助弟弟学习英语。", "error_description": "错误：“愿意”表示意愿，“过”表示经历，二者不搭配，应去掉“过”，说“我愿意辅助弟弟学习英语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87dd9e1c-0684-4949-bdc1-6e131bc0d105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
