INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做各种各样的事情，比如吃饭、穿衣服、打扫卫生。", "primary_collocate": null, "pronunciation": "shēng huó shí jiàn", "ipa": "ʂɤŋ˥ xuɔ˧˥ ʂʐ̩˧˥ tɕjɛn˥˩", "syllable_count": 4, "sentences": [{"text": "吃饭、穿衣、打扫卫生都是每天的生活实践。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子每天自己穿衣服，这是一种生活实践。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校让学生做饭、洗衣服，这些都是生活实践。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打扫房间也是生活实践的一部分。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友在家里做饭、洗碗，这就是生活实践。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天吃饭、睡觉、洗衣服，都是我们的生活实践。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会穿衣、整理房间，是孩子最早的生活实践。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课教孩子做饭、洗衣，都是日常的生活实践。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚搬家，每天的生活实践就是买菜和打扫。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我多做家务，这些都是很好的生活实践。", "target_word": "生活实践", "complexity_tier": "T3", "furigana": "shēnghuó shíjiàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活实践", "label": "原形"}], "register": "书面", "sense_fingerprint": "吃饭、穿衣、打扫等日常要做的具体事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d26fe1-76de-4d72-b2de-845fecb9db9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生活实践", "is_correct": true, "explanation": "生活实践指日常要做的具体事情，与「吃饭、穿衣、打扫卫生」相符。"}, {"text": "工具", "is_correct": false, "explanation": "语义：工具是用来做事的器物，不是吃饭、穿衣这类日常活动本身，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是人每天要去做的事，与前面列举的活动不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：「每天的……」后接的应是人要去做的活动，「每天的冰箱」搭配不当。"}], "explanations": {"生活实践": "生活实践指日常要做的具体事情，与「吃饭、穿衣、打扫卫生」相符。", "工具": "语义：工具是用来做事的器物，不是吃饭、穿衣这类日常活动本身，句意不通。", "天气": "语义：天气是自然现象，不是人每天要去做的事，与前面列举的活动不符。", "冰箱": "搭配：「每天的……」后接的应是人要去做的活动，「每天的冰箱」搭配不当。"}, "sentence_index": 0, "correct_answer": "生活实践"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把生活实践搬到了楼上。", "explanation": "生活实践是日常活动，是抽象概念，不能像实物一样搬到楼上，这里把它当成了具体物品。"}, {"text": "这台电脑是生活实践。", "explanation": "生活实践指日常要做的事，是抽象的活动，不能指一台电脑，这里把它当成了实物。"}, {"text": "他买了一只生活实践。", "explanation": "这里的量词「只」多用于动物。生活实践是抽象名词，不能用「只」来计量，这是量词误用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生活实践", "is_correct": true, "explanation": "生活实践指日常要做的具体事情，「学会穿衣、整理房间」正属于这一类。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是供玩耍的物品，「学会穿衣、整理房间」不是玩具，句意不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是戴在脸上的物品，与「学会穿衣、整理房间」这类日常要做的事没有关系。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：「孩子最早的……」后接的应是孩子要学会做的事，「孩子最早的手机」搭配不当。"}], "explanations": {"生活实践": "生活实践指日常要做的具体事情，「学会穿衣、整理房间」正属于这一类。", "玩具": "语义：玩具是供玩耍的物品，「学会穿衣、整理房间」不是玩具，句意不通。", "眼镜": "语义：眼镜是戴在脸上的物品，与「学会穿衣、整理房间」这类日常要做的事没有关系。", "手机": "搭配：「孩子最早的……」后接的应是孩子要学会做的事，「孩子最早的手机」搭配不当。"}, "sentence_index": 6, "correct_answer": "生活实践"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份生活实践很贵，花了我三百块。", "explanation": "「贵」说的是价格高，多用于商品和服务。生活实践是日常活动，不能用价格来衡量，这里搭配不当。"}, {"text": "他是一个很好的生活实践，什么事都会做。", "explanation": "生活实践指日常要做的事，是活动和经验，不能用来称呼人，这里把它当成了人。"}, {"text": "他的生活实践很高，比爸爸还高。", "explanation": "「高」形容人的身高或物体的高矮，生活实践没有高矮之分，这里搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洗碗是一块日常的生活实践。", "corrected_sentence": "洗碗是一项日常的生活实践。", "error_description": "「生活实践」是抽象名词，量词应用「项」。「块」用于块状的东西，这里误用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学会洗衣服是一只重要的生活实践。", "corrected_sentence": "学会洗衣服是一项重要的生活实践。", "error_description": "「生活实践」是抽象名词，量词应用「项」。「只」多用于动物，这里误用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25866, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开始", "is_correct": true, "explanation": "反义：“停止”与“开始”构成反义关系，指由静止变为运动。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”与“停止”既非近义也非反义。"}, {"text": "收集", "is_correct": false, "explanation": "无关：“收集”与“停止”既非近义也非反义。"}, {"text": "参加", "is_correct": false, "explanation": "无关：“参加”与“停止”既非近义也非反义。"}], "correct_answer": "开始", "explanations": {"开始": "反义：“停止”与“开始”构成反义关系，指由静止变为运动。", "研究": "无关：“研究”与“停止”既非近义也非反义。", "收集": "无关：“收集”与“停止”既非近义也非反义。", "参加": "无关：“参加”与“停止”既非近义也非反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25866, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开始", "is_correct": true, "explanation": "反义：“停止”与“开始”构成反义关系，指由静止变为运动。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”与“停止”既非近义也非反义。"}, {"text": "整理", "is_correct": false, "explanation": "无关：“整理”与“停止”既非近义也非反义。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”与“停止”既非近义也非反义。"}], "correct_answer": "开始", "explanations": {"开始": "反义：“停止”与“开始”构成反义关系，指由静止变为运动。", "修理": "无关：“修理”与“停止”既非近义也非反义。", "整理": "无关：“整理”与“停止”既非近义也非反义。", "讨论": "无关：“讨论”与“停止”既非近义也非反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25866, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不再动了或不再做了。", "primary_collocate": null, "pronunciation": "tíng zhǐ", "ipa": "tʰiŋ˧˥ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "时钟突然停止了。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器停止了，屋里一下子安静了。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心跳停止了。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐一停止，大家都鼓掌。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风雨停止以后，天空变蓝了。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯突然停止，大家都很害怕。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛进行到一半，突然停止了。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨还没有停止，我们先别走。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小孩的哭声一直没有停止。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电扇停止转动，屋子里很热。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "停止了", "label": "完成体"}, {"form": "停止过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "运动或进行中的事物不再动、不再继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecc79bd2-c16d-4f8a-a9d7-dab736631f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25866, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "停止", "is_correct": true, "explanation": "正确：词目“停止”，意思是运动或进行中的事物不再动。"}, {"text": "停职", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是暂时免去职务，与“停止”不同。"}, {"text": "停置", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是停放或搁置不用，与“停止”的意思不同。"}, {"text": "挺直", "is_correct": false, "explanation": "tǐng zhí 与 tíng zhǐ 的两个音节声调都不同，意思是笔直、不弯曲。"}], "explanations": {"停止": "正确：词目“停止”，意思是运动或进行中的事物不再动。", "停职": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是暂时免去职务，与“停止”不同。", "停置": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是停放或搁置不用，与“停止”的意思不同。", "挺直": "tǐng zhí 与 tíng zhǐ 的两个音节声调都不同，意思是笔直、不弯曲。"}, "sentence_index": null, "correct_answer": "停止"}, "level_3": {"options": [{"text": "停止", "is_correct": true, "explanation": "正确：“停止”表示运动不再进行，与“时钟突然……了”的语境相合。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的主语应是人，“时钟唱了”不成立。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“时钟突然讨论了”与常识相悖，时钟不能进行讨论。"}, {"text": "研究", "is_correct": false, "explanation": "语义：“时钟突然研究了”与常识相悖，时钟不能进行研究。"}], "explanations": {"停止": "正确：“停止”表示运动不再进行，与“时钟突然……了”的语境相合。", "唱": "配价：“唱”的主语应是人，“时钟唱了”不成立。", "讨论": "语义：“时钟突然讨论了”与常识相悖，时钟不能进行讨论。", "研究": "语义：“时钟突然研究了”与常识相悖，时钟不能进行研究。"}, "sentence_index": 0, "correct_answer": "停止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他顺路停止了我家。", "explanation": "这里应该用〈顺路去〉。停止指东西不再动或事情不再发生，不能表示顺道到某人家。"}, {"text": "他把自行车停止在楼下。", "explanation": "这里应该用〈停放〉。停止指不再动，不能表示把车辆放在某处，那是停放。"}, {"text": "他终于停止了烟瘾。", "explanation": "这里应该用〈戒掉〉。“停止”不能直接带“烟瘾”这类习惯作宾语，戒掉习惯要说“戒掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停止", "is_correct": true, "explanation": "正确：“停止”表示比赛中途中止，与“进行到一半，突然……了”的语境相合。"}, {"text": "降临", "is_correct": false, "explanation": "语义：“降临”多指灾难或好事忽然到来，不能用来指比赛中途中止。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，不能以“比赛”为主语或施事对象。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”指印刷发行，不能用于比赛。"}], "explanations": {"停止": "正确：“停止”表示比赛中途中止，与“进行到一半，突然……了”的语境相合。", "降临": "语义：“降临”多指灾难或好事忽然到来，不能用来指比赛中途中止。", "吃": "配价：“吃”的宾语应是食物，不能以“比赛”为主语或施事对象。", "出版": "搭配：“出版”指印刷发行，不能用于比赛。"}, "sentence_index": 6, "correct_answer": "停止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在火车站停止了一封信。", "explanation": "这里应该用〈写〉。停止指事物不再动或事情不再进行，不能用来表示写信。"}, {"text": "他在窗边停止了一幅画。", "explanation": "这里应该用〈画〉。停止指不再进行，不能用来表示作画。"}, {"text": "他在门口停止了一杯咖啡。", "explanation": "这里应该用〈喝〉。停止指不再进行，不能用来表示喝咖啡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电梯很停止了，大家都很害怕。", "corrected_sentence": "电梯突然停止了，大家都很害怕。", "error_description": "错误：“很”不能修饰表示事件结束的“停止”。这里表示突发，应用“突然”，说“电梯突然停止了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛进行到一半，很停止了。", "corrected_sentence": "比赛进行到一半，忽然停止了。", "error_description": "错误：“很”不能修饰表示事件结束的“停止”。这里表示突发，应把“很”换成“突然”，说“比赛进行到一半，突然停止了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
