INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用布做的小袋子，可以装东西。", "primary_collocate": null, "pronunciation": "bù dài zi", "ipa": "pu˥˩ taɪ˥˩ tsɨ", "syllable_count": 3, "sentences": [{"text": "买菜的时候，我喜欢带自己的布袋子。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个布袋子可以洗，洗完还能再用。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把零钱放进一个小布袋子里。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她背着一个红色的布袋子去上学。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用布袋子买东西，对环境很好。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个布袋子是用旧裤子做的。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的布袋子破了，要换一个新的。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书太多了，一个布袋子装不下。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶给我做了一个小布袋子，里面装着糖。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市门口有人卖布袋子，十块钱一个。", "target_word": "布袋子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "布袋", "label": "复合"}], "register": "中性", "sense_fingerprint": "用布做的小袋子，装东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '774c926e-fb1f-4488-8915-497812d93261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "布袋子", "is_correct": true, "explanation": "与句中“布袋子”相同。“买菜的时候带”正适合装菜的布袋子。"}, {"text": "行李箱", "is_correct": false, "explanation": "体貌：行李箱太大太重，买菜时带着不方便，不适合买菜时携带。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是买菜时随身携带的东西，“带自己的汽车买菜”说不通。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子是戴在头上的，不能用来装菜，与“买菜的时候带”的用途不合。"}], "explanations": {"布袋子": "与句中“布袋子”相同。“买菜的时候带”正适合装菜的布袋子。", "行李箱": "体貌：行李箱太大太重，买菜时带着不方便，不适合买菜时携带。", "汽车": "语义：汽车不是买菜时随身携带的东西，“带自己的汽车买菜”说不通。", "帽子": "语义：帽子是戴在头上的，不能用来装菜，与“买菜的时候带”的用途不合。"}, "sentence_index": 0, "correct_answer": "布袋子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙放进了裤子的布袋子里。", "explanation": "这里应该用〈口袋〉。口袋是衣服裤子上缝的部分，布袋子是独立的袋子，不能说“裤子的布袋子”。"}, {"text": "奶奶缝了一条布袋子，给我装糖。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，布袋子不能用“条”。"}, {"text": "妈妈买了一张布袋子，用来装菜。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子等扁平的东西，布袋子不能用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "布袋子", "is_correct": true, "explanation": "与句中“布袋子”相同。“破了要换一个新的”说的是可以更换的袋子。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口不会“破”，也不能“换一个新的”，与“破了”不搭。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”一般说“发”或“改”，不说“破”，“脾气破了”说不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不会破，也不能换一个新的，与句意冲突。"}], "explanations": {"布袋子": "与句中“布袋子”相同。“破了要换一个新的”说的是可以更换的袋子。", "人口": "语义：人口不会“破”，也不能“换一个新的”，与“破了”不搭。", "脾气": "搭配：“脾气”一般说“发”或“改”，不说“破”，“脾气破了”说不通。", "海洋": "语义：海洋不会破，也不能换一个新的，与句意冲突。"}, "sentence_index": 6, "correct_answer": "布袋子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在路上捡到一根布袋子。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，布袋子不能用“根”。"}, {"text": "他买了一朵布袋子送给妹妹。", "explanation": "这里应该用〈个〉。“朵”用于花、云等，布袋子不能用“朵”。"}, {"text": "他有一座布袋子，用来装书。", "explanation": "这里应该用〈个〉。“座”用于山、桥、房屋等大型固定的东西，布袋子不能用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一本布袋子。", "corrected_sentence": "我买了一个布袋子。", "error_description": "布袋子的量词应该用“个”，不能用“本”。“本”用于书籍、本子等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天在超市买了一把布袋子。", "corrected_sentence": "我昨天在超市买了一个布袋子。", "error_description": "布袋子的量词应该用“个”，不能用“把”。“把”用于有柄或可握持的东西，如伞、刀，布袋子不能用“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
