INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25884, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看看东西对不对。", "primary_collocate": null, "pronunciation": "jiǎn chá", "ipa": "tɕjɛn˨˩ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "出门前，请检查一下门有没有锁好。", "target_word": "检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用机器检查我的身体。", "target_word": "检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "交作业以前，请你再检查一遍。", "target_word": "检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师正在检查大家的作业。", "target_word": "检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机起飞前，工人要仔细检查每个地方。", "target_word": "检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他检查了三次，还是没找到错误。", "target_word": "检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关人员要检查每个人的行李。", "target_word": "检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去医院检查一下，看看哪儿不舒服。", "target_word": "检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写完以后，我检查了一遍，没有错字。", "target_word": "检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈检查了孩子的书包，看有没有带书。", "target_word": "检查", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "检查了", "label": "体标（了）"}, {"form": "检查过", "label": "体标（过）"}, {"form": "检查检查", "label": "重叠"}, {"form": "检查员", "label": "复合"}], "register": "中性", "sense_fingerprint": "查看事物是否正确、完好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be7eb40f-7d8a-4232-9c49-ff679e0a5a7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "检查", "is_correct": true, "explanation": "“检查”指查看事物是否正确、完好，与“看看门有没有锁好”相合，是正确答案。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清理卫生，与确认门是否锁好无关。"}, {"text": "举行", "is_correct": false, "explanation": "搭配：“举行”多接活动、仪式，不能接“一下门”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是擦拭，不能用来确认门是否锁好。"}], "explanations": {"检查": "“检查”指查看事物是否正确、完好，与“看看门有没有锁好”相合，是正确答案。", "打扫": "语义：打扫是清理卫生，与确认门是否锁好无关。", "举行": "搭配：“举行”多接活动、仪式，不能接“一下门”。", "擦": "语义：擦是擦拭，不能用来确认门是否锁好。"}, "sentence_index": 0, "correct_answer": "检查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家正在检查比赛。", "explanation": "这里应该用〈观看〉。检查指查看是否正确或完好，不指看比赛。"}, {"text": "她在晚会上检查了一个魔术。", "explanation": "这里应该用〈表演〉。检查指看看对不对，不能用来说在晚会上演出节目。"}, {"text": "他在会上检查了一个奖。", "explanation": "这里应该用〈赢得〉。检查指看看对不对，不能用来说获得奖项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "检查", "is_correct": true, "explanation": "“检查”指查看事物是否正确、完好，与“海关人员要……行李”相合，是正确答案。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植是栽培植物，不能用于对行李的处理。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”接的是人或客人，不能接“行李”。"}, {"text": "安慰", "is_correct": false, "explanation": "搭配：“安慰”接的是人，不能接“行李”。"}], "explanations": {"检查": "“检查”指查看事物是否正确、完好，与“海关人员要……行李”相合，是正确答案。", "种植": "语义：种植是栽培植物，不能用于对行李的处理。", "欢迎": "搭配：“欢迎”接的是人或客人，不能接“行李”。", "安慰": "搭配：“安慰”接的是人，不能接“行李”。"}, "sentence_index": 6, "correct_answer": "检查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们检查他考上了大学。", "explanation": "这里应该用〈恭喜〉。检查指查看对错或完好，不能用来表示庆贺别人的成功。"}, {"text": "这次旅行我们检查得很开心。", "explanation": "这里应该用〈玩〉。检查指看看对不对，不能用来说玩得开心。"}, {"text": "全家人一起检查新年。", "explanation": "这里应该用〈迎接〉。检查指看看对不对，不能用来说迎接节日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他检查的很仔细。", "corrected_sentence": "他检查得很仔细。", "error_description": "补语标记错误：程度补语应用“得”，不能用“的”。错误形式“检查的很仔细”，正确形式“检查得很仔细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈检查了三个次门。", "corrected_sentence": "妈妈检查了三次门。", "error_description": "量词错误：“次”本身是动量词，前面不能再加“个”，应说“检查了三次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
