INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25888, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体不舒服，比如发烧、咳嗽或肚子疼。", "primary_collocate": null, "pronunciation": "shēng bìng", "ipa": "ʂɤŋ˥ piŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我生病了，发烧又咳嗽。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，肚子很疼。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟生病了，不想吃饭。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我生病了，一直在睡觉。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生病了，脸红红的。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你生病了，要多喝热水。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗生病了，不吃东西。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我生病了，所以今天不去学校。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学生病了，我去看看他。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病的时候，不想说话。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生病了", "label": "体标"}, {"form": "生了病", "label": "离合"}, {"form": "生过病", "label": "离合"}], "register": "中性", "sense_fingerprint": "身体不舒服，有发烧、咳嗽、肚子疼等症状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea494939-a4c9-431c-bc0d-cd219d6a4140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生病", "is_correct": true, "explanation": "“生病”与“发烧又咳嗽”的症状相合，表示身体不舒服。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与发烧、咳嗽的症状毫无关系，句意说不通。"}, {"text": "停电", "is_correct": false, "explanation": "搭配：“停电”的主语通常是地方或房屋，不能用于人。"}, {"text": "倒闭", "is_correct": false, "explanation": "搭配：“倒闭”的主语是企业或商店，不能用于人。"}], "explanations": {"生病": "“生病”与“发烧又咳嗽”的症状相合，表示身体不舒服。", "结婚": "语义：“结婚”与发烧、咳嗽的症状毫无关系，句意说不通。", "停电": "搭配：“停电”的主语通常是地方或房屋，不能用于人。", "倒闭": "搭配：“倒闭”的主语是企业或商店，不能用于人。"}, "sentence_index": 0, "correct_answer": "生病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在篮球场上生病了，腿摔得很疼。", "explanation": "这里应该用〈摔伤〉。“生病”指身体不舒服，摔伤是外伤，不能用“生病”。"}, {"text": "他跑步时生病了，脚踝扭得很厉害。", "explanation": "这里应该用〈扭伤〉。“生病”不用于运动中扭伤，要说“扭伤”。"}, {"text": "她切菜时生病了，手指被刀割伤了。", "explanation": "这里应该用〈割伤〉。“生病”不用于刀割造成的伤，要说“割伤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生病", "is_correct": true, "explanation": "“生病”与“不吃东西”的症状相合，表示身体不舒服。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，小狗不能退休，句意说不通。"}, {"text": "下班", "is_correct": false, "explanation": "搭配：“下班”的主语应是工作的人，不能用于小狗。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，小狗不能毕业，与“不吃东西”说不通。"}], "explanations": {"生病": "“生病”与“不吃东西”的症状相合，表示身体不舒服。", "退休": "语义：“退休”指离开工作岗位，小狗不能退休，句意说不通。", "下班": "搭配：“下班”的主语应是工作的人，不能用于小狗。", "毕业": "语义：“毕业”指完成学业，小狗不能毕业，与“不吃东西”说不通。"}, "sentence_index": 6, "correct_answer": "生病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下楼时生病了，脚扭得很厉害。", "explanation": "这里应该用〈扭伤〉。“生病”指身体不舒服，脚扭伤是外伤，要说“扭伤”。"}, {"text": "他被自行车撞后生病了，正在医院。", "explanation": "这里应该用〈撞伤〉。“生病”不用于被撞造成的伤，要说“撞伤”。"}, {"text": "妈妈做饭时生病了，手被油烫伤了。", "explanation": "这里应该用〈烫伤〉。“生病”不用于油烫造成的伤，要说“烫伤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹生病了一场，不能来。", "corrected_sentence": "我妹妹生病了，不能来。", "error_description": "“生病”是离合词，不能直接带“一场”。这里多出“一场”，应只说“我妹妹生病了，不能来”；若要说次数，应说“生了一场病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她生病时候很需要人照顾。", "corrected_sentence": "她生病的时候很需要人照顾。", "error_description": "“……的时候”中的“的”不能省略，应说“生病的时候”；省去“的”是错误的结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
