INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用布做的袋子，可以装东西。", "primary_collocate": null, "pronunciation": "bù dài", "ipa": "pu˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我有一个旧布袋，里面装着书。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个布袋是妈妈用旧衣服做的。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从布袋里拿出两个苹果。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把脏衣服放进布袋里。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "布袋上有两根长带子，背起来很方便。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "布袋太重，我一个人提不动。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用布袋装着花生去看朋友。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布袋可以洗，所以很环保。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的布袋里有铅笔和本子。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天农民把玉米装进大布袋。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个布袋", "label": "量词"}], "register": "中性", "sense_fingerprint": "用布做成、可以装东西的袋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8dcf6e-820e-41d6-966b-7b4656bddf4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "布袋", "is_correct": true, "explanation": "正确：“旧布袋”里装着书，布袋是装东西的袋子，句意通顺。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是用来插花的，不能用来装书。"}, {"text": "水瓶", "is_correct": false, "explanation": "语义：水瓶是盛水的，不适合用来装书。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱是家电，不是用来装书的容器，“里面装着书”不搭配“冰箱”。"}], "explanations": {"布袋": "正确：“旧布袋”里装着书，布袋是装东西的袋子，句意通顺。", "花瓶": "语义：花瓶是用来插花的，不能用来装书。", "水瓶": "语义：水瓶是盛水的，不适合用来装书。", "冰箱": "搭配：冰箱是家电，不是用来装书的容器，“里面装着书”不搭配“冰箱”。"}, "sentence_index": 0, "correct_answer": "布袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一把布袋，装满了玉米。", "explanation": "这里应该用〈个〉。布袋是立体的袋子，量词用“个”；“把”用于有柄或能握住的东西，不用于布袋。"}, {"text": "下雨了，他撑着布袋走在路上。", "explanation": "这里应该用〈伞〉。“撑”用于雨伞、阳伞，布袋不能撑。"}, {"text": "她用布袋写字，写得很整齐。", "explanation": "这里应该用〈笔〉。写字要用笔，布袋不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "布袋", "is_correct": true, "explanation": "正确：“用……装着花生”需要容器，布袋正是用来装东西的。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“装”需要容器作工具，桌子不能用来装花生。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能拿来装花生。"}, {"text": "嘴", "is_correct": false, "explanation": "语义：嘴是身体器官，不是盛装东西的器具。"}], "explanations": {"布袋": "正确：“用……装着花生”需要容器，布袋正是用来装东西的。", "桌子": "配价：“装”需要容器作工具，桌子不能用来装花生。", "窗户": "语义：窗户是建筑部件，不能拿来装花生。", "嘴": "语义：嘴是身体器官，不是盛装东西的器具。"}, "sentence_index": 6, "correct_answer": "布袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她穿着布袋去学校上课。", "explanation": "这里应该用〈鞋〉。“穿”用于鞋袜、衣服，布袋不能穿。"}, {"text": "奶奶用布袋煮面条，煮得很快。", "explanation": "这里应该用〈锅〉。煮面条要用锅，布袋不能下锅煮。"}, {"text": "她用布袋梳头，头发很整齐。", "explanation": "这里应该用〈梳子〉。梳头要用梳子，布袋不能用来梳头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用一张布袋装了花生。", "corrected_sentence": "她用一个布袋装了花生。", "error_description": "量词错误：布袋是立体的袋子，量词应用“个”，不能用平面物体的量词“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把钥匙放进布袋上了。", "corrected_sentence": "妈妈把钥匙放进布袋里了。", "error_description": "方位词错误：把东西放进袋子应说“布袋里”，“上”表示在表面之上，不能说“布袋上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违反", "is_correct": true, "explanation": "反义：「违反」与「遵守」相对，指不依约定或规定行事。"}, {"text": "挑选", "is_correct": false, "explanation": "无关：「挑选」与「遵守」没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "无关：「修理」与「遵守」没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：「散步」与「遵守」没有反义关系。"}], "correct_answer": "违反", "explanations": {"违反": "反义：「违反」与「遵守」相对，指不依约定或规定行事。", "挑选": "无关：「挑选」与「遵守」没有反义关系。", "修理": "无关：「修理」与「遵守」没有反义关系。", "散步": "无关：「散步」与「遵守」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违反", "is_correct": true, "explanation": "反义：「违反」与「遵守」相对，指不依规定行事。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：「唱歌」与「遵守」没有反义关系。"}, {"text": "种植", "is_correct": false, "explanation": "无关：「种植」与「遵守」没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：「打扫」与「遵守」没有反义关系。"}], "correct_answer": "违反", "explanations": {"违反": "反义：「违反」与「遵守」相对，指不依规定行事。", "唱歌": "无关：「唱歌」与「遵守」没有反义关系。", "种植": "无关：「种植」与「遵守」没有反义关系。", "打扫": "无关：「打扫」与「遵守」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做事情时按照规则或别人的要求来。", "primary_collocate": null, "pronunciation": "zūn shǒu", "ipa": "tswən˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "玩游戏时要遵守规则。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们遵守老师的要求，排好队。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好了，你要遵守时间。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他遵守了和妈妈的约定。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在图书馆里，请遵守安静的要求。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人遵守医生的要求，按时吃药。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在这里的人都要遵守小区的规矩。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个好学生，遵守所有的课堂规则。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都遵守约定，游戏才好玩。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸要求早睡，我遵守了。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遵守了", "label": "体标"}, {"form": "遵守着", "label": "体标"}, {"form": "遵守过", "label": "体标"}], "register": "中性", "sense_fingerprint": "做事时按规则、约定或他人要求来做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea494939-a4c9-431c-bc0d-cd219d6a4140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遵守", "is_correct": true, "explanation": "正确。「遵守规则」表示玩游戏时依规则行事。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：「提高」用于水平、质量，不能说提高规则。"}, {"text": "修理", "is_correct": false, "explanation": "语义：「修理」指修补器物，不能用于规则。"}, {"text": "喂", "is_correct": false, "explanation": "配价：「喂」要求动物或人作对象，不能以「规则」作宾语。"}], "explanations": {"遵守": "正确。「遵守规则」表示玩游戏时依规则行事。", "提高": "搭配：「提高」用于水平、质量，不能说提高规则。", "修理": "语义：「修理」指修补器物，不能用于规则。", "喂": "配价：「喂」要求动物或人作对象，不能以「规则」作宾语。"}, "sentence_index": 0, "correct_answer": "遵守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种植物遵守四季的变化开花。", "explanation": "这里应该用〈遵循〉。「遵守」用于规定、约定，自然变化的规律要用「遵循」。"}, {"text": "他终于遵守了自己的梦想。", "explanation": "这里应该用〈实现〉。「遵守」用于规则、约定，梦想要说「实现」。"}, {"text": "我们要遵守环境。", "explanation": "这里应该用〈保护〉。「遵守」的对象是规则、要求，保护环境要用「保护」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遵守", "is_correct": true, "explanation": "正确。「遵守规矩」表示依照小区的规矩行事。"}, {"text": "搬", "is_correct": false, "explanation": "配价：「搬」要求具体的物体作宾语，不能搬规矩。"}, {"text": "烧", "is_correct": false, "explanation": "语义：「烧」指燃烧，与规矩无关。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」指烹调食物，与规矩无关。"}], "explanations": {"遵守": "正确。「遵守规矩」表示依照小区的规矩行事。", "搬": "配价：「搬」要求具体的物体作宾语，不能搬规矩。", "烧": "语义：「烧」指燃烧，与规矩无关。", "煮": "语义：「煮」指烹调食物，与规矩无关。"}, "sentence_index": 6, "correct_answer": "遵守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他遵守了老师的问题。", "explanation": "这里应该用〈回答〉。「遵守」的对象是规定、要求，回应问题要用「回答」。"}, {"text": "我遵守这幅画。", "explanation": "这里应该用〈欣赏〉。「遵守」用于规则、要求，欣赏艺术品要用「欣赏」。"}, {"text": "我们要遵守教室。", "explanation": "这里应该用〈打扫〉。「遵守」的对象是规定，打扫场所要用「打扫」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟没遵守了和我的约定。", "corrected_sentence": "弟弟没遵守和我的约定。", "error_description": "「没」否定动作时，动词后不能再加「了」。错误在“遵守”后面的“了”；应说「没遵守」，去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们遵守很好。", "corrected_sentence": "同学们遵守得很好。", "error_description": "动词带程度补语时，中间要加「得」。应说「遵守得很好」，不能说「遵守很好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免费", "is_correct": true, "explanation": "正确。“免费”与“付费”意思相反，指不用付钱。"}, {"text": "下载", "is_correct": false, "explanation": "下载指把文件存到自己的设备上，与“付费”没有反义关系。"}, {"text": "点赞", "is_correct": false, "explanation": "点赞指表示喜欢，与“付费”没有反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "观看指看视频或节目，与“付费”不是反义关系。"}], "correct_answer": "免费", "explanations": {"免费": "正确。“免费”与“付费”意思相反，指不用付钱。", "下载": "下载指把文件存到自己的设备上，与“付费”没有反义关系。", "点赞": "点赞指表示喜欢，与“付费”没有反义关系。", "观看": "观看指看视频或节目，与“付费”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免费", "is_correct": true, "explanation": "正确。“免费”与“付费”意思相反，指不用付钱。"}, {"text": "分享", "is_correct": false, "explanation": "分享指与别人共同使用，与“付费”不是反义关系。"}, {"text": "评论", "is_correct": false, "explanation": "评论指发表看法，与“付费”没有反义关系。"}, {"text": "转发", "is_correct": false, "explanation": "转发指把内容传给别人，与“付费”没有反义关系。"}], "correct_answer": "免费", "explanations": {"免费": "正确。“免费”与“付费”意思相反，指不用付钱。", "分享": "分享指与别人共同使用，与“付费”不是反义关系。", "评论": "评论指发表看法，与“付费”没有反义关系。", "转发": "转发指把内容传给别人，与“付费”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "付钱才能得到东西。", "primary_collocate": null, "pronunciation": "fù fèi", "ipa": "fu˥˩ feɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这个游戏要付费才能玩。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这门网课需要付费。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想听全部的歌，就要付费。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不付费的人只能看前十分钟。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想付费，所以只看免费的视频。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月付费听音乐。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡馆的无线网络不用付费。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付费以后，你会收到一个密码。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的小火车要付费，大门不用。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门票要付费才能进，朋友替我付费，我很不好意思。", "target_word": "付费", "complexity_tier": "T3", "furigana": "mén piào yào fù fèi cái néng jìn, péng yǒu tì wǒ fù fèi, wǒ hěn bù hǎo yì sī.", "sentence_source": "generated"}], "morphological_forms": [{"form": "付了费", "label": "体标"}, {"form": "付过费", "label": "体标"}, {"form": "付費", "label": "繁体"}, {"form": "付费会员", "label": "复合"}], "register": "中性", "sense_fingerprint": "先付钱才能使用或得到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0fbe80-3322-4a2e-a4d7-d218a61d1e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付费", "is_correct": true, "explanation": "正确。“这个游戏要付费才能玩”指先交钱才能玩，符合句意。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记不是玩游戏的条件，与“玩”的意思不符。"}, {"text": "退出", "is_correct": false, "explanation": "语义：退出游戏就不能玩了，与“才能玩”的意思矛盾。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“要洗澡才能玩”搭配不通，洗澡与游戏没有关系。"}], "explanations": {"付费": "正确。“这个游戏要付费才能玩”指先交钱才能玩，符合句意。", "忘记": "语义：忘记不是玩游戏的条件，与“玩”的意思不符。", "退出": "语义：退出游戏就不能玩了，与“才能玩”的意思矛盾。", "洗澡": "搭配：“要洗澡才能玩”搭配不通，洗澡与游戏没有关系。"}, "sentence_index": 0, "correct_answer": "付费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每年清明都向烈士付费。", "explanation": "这里应该用〈缅怀〉。付费指交钱获得服务，向烈士表达敬意不能用付费。"}, {"text": "他说错了话，就付费向朋友赔礼。", "explanation": "这里应该用〈道歉〉。付费指交钱获得服务，向朋友道歉不能用钱买，不能说付费。"}, {"text": "他在超市门口捡到一把伞，就付费还给了失主。", "explanation": "这里应该用〈归还〉。付费指为获得商品或服务交钱，把捡到的东西还给失主是无偿的，不能说付费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付费", "is_correct": true, "explanation": "正确。“无线网络不用付费”指不用交钱，符合句意。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步与无线网络无关，句子说的是网络的收费情况。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：网络不会发烧，“无线网络不用发烧”搭配不通。"}, {"text": "讲笑话", "is_correct": false, "explanation": "语义：讲笑话与无线网络的收费无关，句意不通。"}], "explanations": {"付费": "正确。“无线网络不用付费”指不用交钱，符合句意。", "散步": "语义：散步与无线网络无关，句子说的是网络的收费情况。", "发烧": "搭配：网络不会发烧，“无线网络不用发烧”搭配不通。", "讲笑话": "语义：讲笑话与无线网络的收费无关，句意不通。"}, "sentence_index": 6, "correct_answer": "付费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树要付费才能长大。", "explanation": "搭配：树不能付费，“付费”的主体应是人或机构，搭配不通。"}, {"text": "他每天付费上班，很辛苦。", "explanation": "搭配：上班是劳动并领取工资，不是付费获得的服务，“付费上班”搭配不通。"}, {"text": "她很高兴，因为朋友付费夸了她。", "explanation": "搭配：〈夸〉不是可以付费获得的服务，“付费夸”搭配不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你付费过以后，就能看全部内容。", "corrected_sentence": "你付过费以后，就能看全部内容。", "error_description": "体标位置错误：“过”应紧跟动词，应说“付过费”，不能放在“付费”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "付费完的人可以进去。", "corrected_sentence": "付完费的人可以进去。", "error_description": "结果补语位置错误：“完”应紧跟动词，应说“付完费”，不能说“付费完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
