INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用塑料做的东西。", "primary_collocate": null, "pronunciation": "sù liào zhì pǐn", "ipa": "su˥˩ liɑʊ˥˩ ʈʂɻ̩˥˩ pin˨˩˦", "syllable_count": 4, "sentences": [{"text": "孩子的玩具大多是塑料制品。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子和盘子都是塑料制品。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料制品遇到高温会变软。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的二楼卖各种塑料制品，比如盆和桶。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的水桶是塑料制品，不是铁的。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们工厂用旧瓶子做新的塑料制品。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料制品不会生锈，所以浴室里常用。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不喜欢用塑料制品装热汤。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些塑料制品是用机器做出来的。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买塑料制品时，要看看有没有环保标志。", "target_word": "塑料制品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "塑料製品", "label": "繁体"}, {"form": "塑料制品厂", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常生活中用塑料做成的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0fbe80-3322-4a2e-a4d7-d218a61d1e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塑料制品", "is_correct": true, "explanation": "正确。“孩子的玩具大多是塑料制品”，指玩具多用塑料做成，语境相符。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具不是玩具，与“孩子的玩具”的语境相矛盾。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是孩子的玩具，与句意相矛盾。"}, {"text": "煤炭", "is_correct": false, "explanation": "搭配：煤炭不用来做玩具的材料，“大多是煤炭”搭配不通。"}], "explanations": {"塑料制品": "正确。“孩子的玩具大多是塑料制品”，指玩具多用塑料做成，语境相符。", "家具": "语义：家具不是玩具，与“孩子的玩具”的语境相矛盾。", "电视": "语义：电视不是孩子的玩具，与句意相矛盾。", "煤炭": "搭配：煤炭不用来做玩具的材料，“大多是煤炭”搭配不通。"}, "sentence_index": 0, "correct_answer": "塑料制品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他饿了，就去厨房煮了塑料制品。", "explanation": "这里应该用〈面条〉。〈煮〉的对象是食物，塑料制品不能煮。"}, {"text": "这位老人买了三头塑料制品。", "explanation": "这里量词应该用〈件〉。〈头〉用于牲畜，不能用来数塑料制品。"}, {"text": "饭后我用塑料制品跑了三公里。", "explanation": "跑步的是人，塑料制品不能跑；这里应该说“我跑了三公里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塑料制品", "is_correct": true, "explanation": "正确。塑料制品不会生锈，放在浴室里常用，符合句意。"}, {"text": "铁器", "is_correct": false, "explanation": "语义：铁器会生锈，与句中“不会生锈”的说法相矛盾。"}, {"text": "铁锅", "is_correct": false, "explanation": "语义：铁锅会生锈，而且不是浴室里常用的东西，与句意相矛盾。"}, {"text": "煤油", "is_correct": false, "explanation": "搭配：煤油易燃，不适合在浴室里常用，“浴室里常用”搭配不通。"}], "explanations": {"塑料制品": "正确。塑料制品不会生锈，放在浴室里常用，符合句意。", "铁器": "语义：铁器会生锈，与句中“不会生锈”的说法相矛盾。", "铁锅": "语义：铁锅会生锈，而且不是浴室里常用的东西，与句意相矛盾。", "煤油": "搭配：煤油易燃，不适合在浴室里常用，“浴室里常用”搭配不通。"}, "sentence_index": 6, "correct_answer": "塑料制品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈让我把塑料制品吃掉。", "explanation": "搭配：〈吃〉的对象是食物，塑料制品不能吃。"}, {"text": "他经常在台上唱塑料制品。", "explanation": "搭配：〈唱〉的对象是歌曲，塑料制品不能唱。"}, {"text": "这位司机开着塑料制品去上班。", "explanation": "搭配：〈开〉的对象是车辆等交通工具，塑料制品不能开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈塑料制品放进了柜子。", "corrected_sentence": "妈妈把塑料制品放进了柜子。", "error_description": "缺少“把”：“放进”前的宾语“塑料制品”要用“把”引出，应说“妈妈把塑料制品放进了柜子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了两张塑料制品。", "corrected_sentence": "他买了两件塑料制品。", "error_description": "量词错误：塑料制品应用量词“件”，应说“两件塑料制品”。“张”多用于纸、桌子等扁平的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
