INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25916, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某种办法、意见或措施拿来采用，照着去做。", "primary_collocate": null, "pronunciation": "cǎi qǔ", "ipa": "tsʰaɪ²¹⁴ tɕʰy²¹⁴", "syllable_count": 2, "sentences": [{"text": "经理采取了我的方法，改了计划。", "target_word": "采取", "complexity_tier": "T3", "furigana": "cǎi qǔ", "sentence_source": "generated"}, {"text": "这个方法不错，我们采取了它。", "target_word": "采取", "complexity_tier": "T3", "furigana": "cǎi qǔ", "sentence_source": "generated"}, {"text": "他的方法很好，我想采取他的做法。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司采取了客人提出的办法。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都不同意，所以没有采取他的计划。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们采取了王老师讲的学习方法。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书里的方法，你可以采取一些。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他采取了别人的好办法，用在自己的工作里。", "target_word": "采取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子想出的办法很有意思，妈妈采取了他的办法。", "target_word": "采取", "complexity_tier": "T3", "furigana": "cǎi qǔ", "sentence_source": "generated"}, {"text": "会上大家提了很多办法，经理只采取了两个。", "target_word": "采取", "complexity_tier": "T3", "furigana": "cǎi qǔ", "sentence_source": "generated"}], "morphological_forms": [{"form": "采取了", "label": "完成体"}, {"form": "采取过", "label": "经历体"}, {"form": "採取", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把别人的意见、办法拿来自己用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd050e39d-2ea0-4db5-ae84-c11939194167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25916, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿", "is_correct": false, "explanation": "搭配：“穿”接衣物，不能说“穿方法”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，“我的方法”不能被唱。"}, {"text": "采取", "is_correct": true, "explanation": "采取：把别人的办法拿来自己用，与“我的方法”搭配，符合“改了计划”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，“方法”不能被吃。"}], "explanations": {"穿": "搭配：“穿”接衣物，不能说“穿方法”。", "唱": "语义：“唱”指发声演唱，“我的方法”不能被唱。", "采取": "采取：把别人的办法拿来自己用，与“我的方法”搭配，符合“改了计划”的语境。", "吃": "语义：“吃”指进食，“方法”不能被吃。"}, "sentence_index": 0, "correct_answer": "采取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校向学生采取了学费。", "explanation": "这里应该用〈收取〉。采取指把办法拿来用，向学生收钱要说“收取”。"}, {"text": "我们去果园，采取了一筐苹果。", "explanation": "这里应该用〈采摘〉。采取指把办法拿来用，摘果实要说“采摘”。"}, {"text": "公司采取了新的设备，提高了效率。", "explanation": "这里应该用〈采购〉。采取针对办法、意见，买设备要说“采购”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，“这本书里的方法”不能被喝。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”接帽子、眼镜等，不接“方法”。"}, {"text": "采取", "is_correct": true, "explanation": "采取：把别人的办法拿来自己用，与“这本书里的方法”搭配，符合“你可以……一些”的语境。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使燃烧，“方法”不能被点燃。"}], "explanations": {"喝": "语义：“喝”指饮用，“这本书里的方法”不能被喝。", "戴": "搭配：“戴”接帽子、眼镜等，不接“方法”。", "采取": "采取：把别人的办法拿来自己用，与“这本书里的方法”搭配，符合“你可以……一些”的语境。", "点燃": "语义：“点燃”指使燃烧，“方法”不能被点燃。"}, "sentence_index": 6, "correct_answer": "采取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "记者采取了市长，写了一篇报道。", "explanation": "这里应该用〈采访〉。采取只用于办法、措施，不能用来指人；采访人要说“采访”。"}, {"text": "学校采取了两位新老师。", "explanation": "这里应该用〈聘请〉。采取不用于指人，请老师任教要说“聘请”。"}, {"text": "这家工厂采取了德国的生产线。", "explanation": "这里应该用〈引进〉。采取针对办法、意见，生产线要说“引进”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没有采取了他的做法。", "corrected_sentence": "我没有采取他的做法。", "error_description": "错误形式是“没有采取了”，正确形式是“没有采取”。“没有”否定已完成的动作时，句中不能再用“了”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理采取了小王的一条方案。", "corrected_sentence": "经理采取了小王的一项方案。", "error_description": "量词错误：“方案”应用量词“项”，说“小王的一项方案”。量词“条”用于细长的东西，不能用来修饰“方案”，说“一条方案”不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指用的多少。", "primary_collocate": null, "pronunciation": "shǐ yòng liàng", "ipa": "ʂʐ̩²¹⁴ jʊŋ⁵¹ ljaŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "这个房间灯的使用量很小。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的使用量不大，一个月只用一瓶。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水的使用量，夏天比冬天大。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我这种药的使用量是多少。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里网络的使用量越来越大了。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电的使用量可以在手机上看到。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王的纸张使用量比同事多得多。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件的使用量最近上升了。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做菜时盐的使用量不能太多。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想减少办公用品的使用量，节约钱。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用的多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd050e39d-2ea0-4db5-ae84-c11939194167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "体貌：“颜色”指外观，“很小”不能用来描述颜色。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的个性，不能用于灯。"}, {"text": "使用量", "is_correct": true, "explanation": "使用量：用的多少，“灯的使用量很小”指用得少。"}, {"text": "作者", "is_correct": false, "explanation": "语义：“作者”指写作的人，不能用于灯。"}], "explanations": {"颜色": "体貌：“颜色”指外观，“很小”不能用来描述颜色。", "性格": "语义：“性格”指人的个性，不能用于灯。", "使用量": "使用量：用的多少，“灯的使用量很小”指用得少。", "作者": "语义：“作者”指写作的人，不能用于灯。"}, "sentence_index": 0, "correct_answer": "使用量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的使用量很广。", "explanation": "这里应该用〈用途〉。使用量指用的多少，说药的用处广要用“用途”。"}, {"text": "这家餐厅的顾客使用量很多。", "explanation": "这里应该用〈数量〉。使用量指用在物品上的多少，指人数时要说“数量”。"}, {"text": "我们学习的使用量很长。", "explanation": "这里应该用〈时间〉。使用量只说用的多少，说学习的长短要用“时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用于纸张。"}, {"text": "使用量", "is_correct": true, "explanation": "使用量：用的多少，“比同事多得多”说明用得多。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”不是可以比多少的量，“比同事多得多”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，不能用于纸张。"}], "explanations": {"身高": "体貌：“身高”指人的高矮，不能用于纸张。", "使用量": "使用量：用的多少，“比同事多得多”说明用得多。", "形状": "语义：“形状”不是可以比多少的量，“比同事多得多”说不通。", "脾气": "语义：“脾气”指人的性情，不能用于纸张。"}, "sentence_index": 6, "correct_answer": "使用量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的使用量很贵。", "explanation": "这里应该用〈价格〉。使用量指用的多少，说衣服值多少钱要用“价格”。"}, {"text": "这条路的使用量很长。", "explanation": "这里应该用〈长度〉。使用量只说用的多少，说路的长短要用“长度”。"}, {"text": "他的使用量增加了三公斤。", "explanation": "这里应该用〈体重〉。使用量指用的多少，不能用来说人的体重增加了多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台空调的使用量的很小。", "corrected_sentence": "这台空调的使用量很小。", "error_description": "错误形式是“使用量的很小”，正确形式是“使用量很小”。“使用量”后直接接形容词作谓语时不加“的”，多出的“的”应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的水的使用量少很。", "corrected_sentence": "我家的水的使用量很少。", "error_description": "错误形式是“使用量少很”，正确形式是“使用量很少”。程度副词“很”应放在形容词“少”之前，不能放在其后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
