INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25920, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用塑料做的东西。", "primary_collocate": null, "pronunciation": "sù liào chǎn pǐn", "ipa": "su˥˩ liɑu˥˩ ʈʂʰan˨˩˦ pʰin˨˩˦", "syllable_count": 4, "sentences": [{"text": "塑料桶、塑料盒都是塑料产品。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料产品掉在地上，一般不会摔坏。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子是塑料产品，不是玻璃的。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的玩具大多是塑料产品。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料产品太热会变软。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家厨房里有不少塑料产品。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买塑料产品时，请看一下材料标签。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商店只卖便宜的塑料产品。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料产品用坏了，别随便扔在河里。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧的塑料产品送去回收站了。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "件", "label": "量词"}, {"form": "塑料產品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "塑料产品:用塑料做的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23dfa03-b845-44a8-b153-08ac3a942371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食物", "is_correct": false, "explanation": "语义：“塑料桶、塑料盒”不是食物，“都是食物”与句子事实矛盾。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：“塑料桶、塑料盒”不是书，“都是书籍”不成立。"}, {"text": "金属", "is_correct": false, "explanation": "搭配：“都是”后接的类别名词应与“桶、盒”同属器物，“金属”是材料名，不能作这样的类别。"}, {"text": "塑料产品", "is_correct": true, "explanation": "“塑料桶、塑料盒”都是用塑料做的东西，属于“塑料产品”，填入后语义通顺。"}], "explanations": {"食物": "语义：“塑料桶、塑料盒”不是食物，“都是食物”与句子事实矛盾。", "书籍": "语义：“塑料桶、塑料盒”不是书，“都是书籍”不成立。", "金属": "搭配：“都是”后接的类别名词应与“桶、盒”同属器物，“金属”是材料名，不能作这样的类别。", "塑料产品": "“塑料桶、塑料盒”都是用塑料做的东西，属于“塑料产品”，填入后语义通顺。"}, "sentence_index": 0, "correct_answer": "塑料产品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都读塑料产品。", "explanation": "这里应该用〈报纸〉。读的是文字材料，塑料产品是实物，不能用来阅读。"}, {"text": "他用一件塑料产品煮饭。", "explanation": "这里应该用〈锅〉。塑料产品是泛称，不能用来煮饭，应说具体的炊具。"}, {"text": "他家养了很多塑料产品。", "explanation": "这里应该用〈鸡〉。养的是活的动物，塑料产品是实物，不能养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人", "is_correct": false, "explanation": "语义：人不是可以购买的商品，“买人时”与“材料标签”的语境不符。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍一般不贴“材料标签”，“买书籍时请看材料标签”语义不合。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“买”后接的应是可买卖的商品，“空气”不能作买卖的对象。"}, {"text": "塑料产品", "is_correct": true, "explanation": "“买塑料产品时”指购买以塑料为原料制成的物品，需要看材料标签，语义通顺。"}], "explanations": {"人": "语义：人不是可以购买的商品，“买人时”与“材料标签”的语境不符。", "书籍": "语义：书籍一般不贴“材料标签”，“买书籍时请看材料标签”语义不合。", "空气": "搭配：“买”后接的应是可买卖的商品，“空气”不能作买卖的对象。", "塑料产品": "“买塑料产品时”指购买以塑料为原料制成的物品，需要看材料标签，语义通顺。"}, "sentence_index": 6, "correct_answer": "塑料产品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天听塑料产品。", "explanation": "这里应该用〈音乐〉。听的是声音，塑料产品不能听。"}, {"text": "这家超市的塑料产品很新鲜。", "explanation": "这里应该用〈食品〉。新鲜形容食物，塑料产品不能说新鲜。"}, {"text": "他每天早上吃一个塑料产品当早饭。", "explanation": "这里应该用〈包子〉。塑料产品不能吃，早饭要说具体食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个商店只卖一座塑料产品。", "corrected_sentence": "这个商店只卖一种塑料产品。", "error_description": "量词错误：“座”用于山、桥等大型固定物，不能用于塑料产品。这里表示种类，应说“一种塑料产品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一双塑料产品。", "corrected_sentence": "他买了一件塑料产品。", "error_description": "量词错误：“双”用于成对的东西，塑料产品不成对，应说“一件塑料产品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25922, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "沿用", "is_correct": true, "explanation": "“沿用”指继续使用原来的方法或东西，与“改用”正相反，是这一义项的反义词。"}, {"text": "游泳", "is_correct": false, "explanation": "与“改用”无反义关系，“游泳”指在水中活动。"}, {"text": "思考", "is_correct": false, "explanation": "与“改用”无反义关系，“思考”指用脑子考虑问题。"}, {"text": "打扫", "is_correct": false, "explanation": "与“改用”无反义关系，“打扫”指清除脏物。"}], "correct_answer": "沿用", "explanations": {"沿用": "“沿用”指继续使用原来的方法或东西，与“改用”正相反，是这一义项的反义词。", "游泳": "与“改用”无反义关系，“游泳”指在水中活动。", "思考": "与“改用”无反义关系，“思考”指用脑子考虑问题。", "打扫": "与“改用”无反义关系，“打扫”指清除脏物。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25922, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "沿用", "is_correct": true, "explanation": "“沿用”指继续使用原来的方法或东西，与“改用”正相反，是这一义项的反义词。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“改用”无反义关系，“唱歌”指用声音表达旋律。"}, {"text": "阅读", "is_correct": false, "explanation": "与“改用”无反义关系，“阅读”指看书报等文字材料。"}, {"text": "浇灌", "is_correct": false, "explanation": "与“改用”无反义关系，“浇灌”指把水倒在植物或土地上。"}], "correct_answer": "沿用", "explanations": {"沿用": "“沿用”指继续使用原来的方法或东西，与“改用”正相反，是这一义项的反义词。", "唱歌": "与“改用”无反义关系，“唱歌”指用声音表达旋律。", "阅读": "与“改用”无反义关系，“阅读”指看书报等文字材料。", "浇灌": "与“改用”无反义关系，“浇灌”指把水倒在植物或土地上。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25922, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "换成别的东西来用。", "primary_collocate": null, "pronunciation": "gǎi yòng", "ipa": "kaɪ̯˨˩˦ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "刀钝了，妈妈改用新刀切菜。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话打不通，我改用微信联系他。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔没有水了，请你改用这支笔。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧电脑太慢，哥哥改用新电脑工作。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左手受伤了，他改用右手写字。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气冷了，我们改用厚被子。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现金不方便，很多人改用手机付钱。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞坏了，你改用我的吧。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤气用完了，我们改用电炉做饭。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请改用黑色的笔填表。", "target_word": "改用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改用了", "label": "体标"}, {"form": "改用过", "label": "体标"}], "register": "中性", "sense_fingerprint": "改用:换成别的东西来用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23dfa03-b845-44a8-b153-08ac3a942371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改用", "is_correct": true, "explanation": "“改用”指换成另一种东西来用，与“刀钝了”的原因相符，表示换用新刀。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：刚换的新刀又扔掉，与“切菜”的语境矛盾。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对坏了的东西，“新刀”不需要修理，搭配不当。"}, {"text": "收起", "is_correct": false, "explanation": "语义：收起新刀后又拿来切菜，前后语义矛盾。"}], "explanations": {"改用": "“改用”指换成另一种东西来用，与“刀钝了”的原因相符，表示换用新刀。", "扔掉": "语义：刚换的新刀又扔掉，与“切菜”的语境矛盾。", "修理": "搭配：“修理”针对坏了的东西，“新刀”不需要修理，搭配不当。", "收起": "语义：收起新刀后又拿来切菜，前后语义矛盾。"}, "sentence_index": 0, "correct_answer": "改用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姐姐把窗帘改用了红色。", "explanation": "这里应该用〈改成〉。改用指换另一种东西来用，颜色变化要说〈改成〉。"}, {"text": "他改用了作业上的错字。", "explanation": "这里应该用〈改正〉。改用指换另一种东西来用，修正错误要说〈改正〉。"}, {"text": "他改用了自己的坏脾气。", "explanation": "这里应该用〈改掉〉。改用指换另一种东西来用，戒除坏脾气要说〈改掉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改用", "is_correct": true, "explanation": "“改用”指换成别的东西来用，此处指改用手机付钱，与“现金不方便”的原因相符。"}, {"text": "停用", "is_correct": false, "explanation": "语义：“停用”指不再使用，与“很多人改用手机付钱”的意思相反，与“现金不方便”的原因矛盾。"}, {"text": "戒掉", "is_correct": false, "explanation": "搭配：“戒掉”多搭配习惯、烟酒，不能搭配“手机付钱”。"}, {"text": "失去", "is_correct": false, "explanation": "搭配：“失去”多搭配机会、信心，不能说“失去手机付钱”。"}], "explanations": {"改用": "“改用”指换成别的东西来用，此处指改用手机付钱，与“现金不方便”的原因相符。", "停用": "语义：“停用”指不再使用，与“很多人改用手机付钱”的意思相反，与“现金不方便”的原因矛盾。", "戒掉": "搭配：“戒掉”多搭配习惯、烟酒，不能搭配“手机付钱”。", "失去": "搭配：“失去”多搭配机会、信心，不能说“失去手机付钱”。"}, "sentence_index": 6, "correct_answer": "改用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他改用了对朋友的感情。", "explanation": "这里应该用〈培养〉。改用指换用物品或方法，感情要说〈培养〉。"}, {"text": "他改用了一场大雨。", "explanation": "这里应该用〈下〉。改用指换用物品或方法，下雨要说〈下〉。"}, {"text": "他改用了这个问题。", "explanation": "这里应该用〈解答〉。改用指换用物品或方法，回答问题要说〈解答〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我改用了了一台新打印机。", "corrected_sentence": "我改用了一台新打印机。", "error_description": "重复“了”：“改用”后只用一个“了”，应说“我改用了一台新打印机”，不能说“改用了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不改用了铅笔写字。", "corrected_sentence": "我不改用铅笔写字。", "error_description": "否定与“了”同用：“不”表示否定，“不改用”后不能加“了”，应删去“了”，说“我不改用铅笔写字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
