INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "押金是先给别人的一些钱，保证自己会遵守约定，以后可以拿回来。", "primary_collocate": null, "pronunciation": "yā jīn", "ipa": "ja˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "借相机要先交一千元押金。", "target_word": "押金", "complexity_tier": "T3", "furigana": "Jiè xiàngjī yào xiān jiāo yìqiān yuán yājīn.", "sentence_source": "generated"}, {"text": "你放心，东西还回来，押金就退给你。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租伞时，我交了二十元押金。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆借钥匙要交五十元押金。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把押金交给了老师，明天来拿回。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "押金不多，但是你要记得拿回来。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租车公司要收三千元押金，可以刷卡。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭盒用完要还，不然押金不退。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家公司的师傅说不用交押金。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手机付了押金，很快就借到了雨伞。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "押金制度", "label": "复合"}], "register": "中性", "sense_fingerprint": "押金:先给别人、保证守约、以后可拿回的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23dfa03-b845-44a8-b153-08ac3a942371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25924, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "押金", "is_correct": true, "explanation": "正确：押金（yā jīn）是为担保而预先支付、事后可退还的钱。"}, {"text": "压紧", "is_correct": false, "explanation": "压紧（yā jǐn，第三声）与 yā jīn（第一声）声调不同，意思是紧紧按住。"}, {"text": "压惊", "is_correct": false, "explanation": "压惊（yā jīng）与 yā jīn 韵母不同（-ing 与 -in），意思是安慰受惊的人。"}, {"text": "压进", "is_correct": false, "explanation": "压进（yā jìn，第四声）与 yā jīn（第一声）声调不同，意思是压入。"}], "explanations": {"押金": "正确：押金（yā jīn）是为担保而预先支付、事后可退还的钱。", "压紧": "压紧（yā jǐn，第三声）与 yā jīn（第一声）声调不同，意思是紧紧按住。", "压惊": "压惊（yā jīng）与 yā jīn 韵母不同（-ing 与 -in），意思是安慰受惊的人。", "压进": "压进（yā jìn，第四声）与 yā jīn（第一声）声调不同，意思是压入。"}, "sentence_index": null, "correct_answer": "押金"}, "level_3": {"options": [{"text": "押金", "is_correct": true, "explanation": "正确：借相机要先交的是押金，还回相机后可以拿回。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“一千元”是钱款，“钥匙”不是钱，不能作为交付的数额。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是学校收取的费用，与借相机无关。"}, {"text": "饭钱", "is_correct": false, "explanation": "语义：饭钱是吃饭的费用，借相机时不需要交饭钱。"}], "explanations": {"押金": "正确：借相机要先交的是押金，还回相机后可以拿回。", "钥匙": "搭配：“一千元”是钱款，“钥匙”不是钱，不能作为交付的数额。", "学费": "语义：学费是学校收取的费用，与借相机无关。", "饭钱": "语义：饭钱是吃饭的费用，借相机时不需要交饭钱。"}, "sentence_index": 0, "correct_answer": "押金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个月要交五百元押金。", "explanation": "这里应该用〈租金〉。押金是一次性预付、事后退还的钱，每月按期交的是租金。"}, {"text": "他靠押金赚了很多钱。", "explanation": "押金是担保用的钱，事后要退还，不是收入，不能用来赚钱。"}, {"text": "我把押金发给了员工当奖金。", "explanation": "这里应该用〈奖金〉。押金是担保用、事后要退还的钱，不能当作奖金发放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "押金", "is_correct": true, "explanation": "正确：租车时要收的是押金，可以刷卡支付。"}, {"text": "礼品", "is_correct": false, "explanation": "语义：礼品是送人的东西，租车公司不会收取三千元礼品。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是付给员工的钱，不是租车公司收取的费用。"}, {"text": "饭票", "is_correct": false, "explanation": "搭配：“饭票”是换饭的凭证，不能和“收三千元”搭配。"}], "explanations": {"押金": "正确：租车时要收的是押金，可以刷卡支付。", "礼品": "语义：礼品是送人的东西，租车公司不会收取三千元礼品。", "工资": "语义：工资是付给员工的钱，不是租车公司收取的费用。", "饭票": "搭配：“饭票”是换饭的凭证，不能和“收三千元”搭配。"}, "sentence_index": 6, "correct_answer": "押金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "吃完饭，我给服务员留了二十元押金。", "explanation": "这里应该用〈小费〉。押金是担保用、事后要退还的钱，留给服务员的额外钱要用“小费”。"}, {"text": "我弟弟每个学期要交押金。", "explanation": "这里应该用〈学费〉。学费是按学期交的费用，押金是担保用、事后退还的钱，不是每学期交的。"}, {"text": "他把押金送给朋友当生日礼物。", "explanation": "这里应该用〈礼金〉。押金是担保用、事后要退还的钱，不能当作赠品送人；送人的贺礼钱要用“礼金”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他借了一本书，先交了一本押金。", "corrected_sentence": "他借了一本书，先交了一笔押金。", "error_description": "量词错误：“本”用于书籍等，不能用来计量“押金”，应用量词“笔”。应改为“一笔押金”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她借书时交了三十个押金，还书就能拿回来。", "corrected_sentence": "她借书时交了三十元押金，还书就能拿回来。", "error_description": "量词错误：押金的金额应用“元”计量，“个”不能用来计量押金，应说“三十元押金”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
