INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25938, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让两个东西不再在一起。", "primary_collocate": null, "pronunciation": "fēn kāi", "ipa": "fən˥ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "请把这两种药分开吃。", "target_word": "分开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色衣服要和彩色衣服分开洗。", "target_word": "分开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们俩一直在一起，从不分开。", "target_word": "分开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课后，朋友们在路口分开了。", "target_word": "分开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这对双胞胎出生后就分开了。", "target_word": "分开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把绑在一起的两根绳子分开了。", "target_word": "分开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把大苹果和小苹果分开。", "target_word": "分开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶和果汁要分开装，不能混在一起。", "target_word": "分开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸妈妈吵架后，分开住了一段时间。", "target_word": "分开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上班的时间和休息的时间要分开。", "target_word": "分开", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "分开了", "label": "体标：完成"}, {"form": "分开过", "label": "体标：经历"}, {"form": "分不开", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "让两个东西或两个人离开彼此，不再同处一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d5ca48-c41f-404e-b8aa-feb7d9f3a2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分开", "is_correct": true, "explanation": "正确：“分开吃”表示两种药分别服用，符合句中的要求。"}, {"text": "混合", "is_correct": false, "explanation": "语义：“混合吃”是把两种药混在一起服用，与“分开”的要求正相反。"}, {"text": "合并", "is_correct": false, "explanation": "搭配：“合并”指使事物合为一体，不能直接与“吃”搭配。"}, {"text": "咀嚼", "is_correct": false, "explanation": "搭配：药物一般吞服，“咀嚼吃”不是服药时的常见搭配。"}], "explanations": {"分开": "正确：“分开吃”表示两种药分别服用，符合句中的要求。", "混合": "语义：“混合吃”是把两种药混在一起服用，与“分开”的要求正相反。", "合并": "搭配：“合并”指使事物合为一体，不能直接与“吃”搭配。", "咀嚼": "搭配：药物一般吞服，“咀嚼吃”不是服药时的常见搭配。"}, "sentence_index": 0, "correct_answer": "分开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把试卷分开给学生了。", "explanation": "这里应该用〈分发〉。分开表示让两方离开彼此，不表示把东西派发给别人。"}, {"text": "我把好消息和大家分开了。", "explanation": "这里应该用〈分享〉。分开指人或物离开彼此，不表示与别人共同拥有。"}, {"text": "老板把任务分开给了我。", "explanation": "这里应该用〈分配〉。分开表示使双方离开，不表示把任务分派给某人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分开", "is_correct": true, "explanation": "正确：“请把大苹果和小苹果分开”表示把两种苹果分别放置，符合句意。"}, {"text": "融合", "is_correct": false, "explanation": "语义：“融合”指使不同事物合成一体，与“分开”的要求正相反。"}, {"text": "掺和", "is_correct": false, "explanation": "语义：“掺和”指把东西混在一起，与把大苹果和小苹果分开的要求相反。"}, {"text": "结合", "is_correct": false, "explanation": "搭配：“结合”多用于抽象事物或力量，不用于两堆具体的水果。"}], "explanations": {"分开": "正确：“请把大苹果和小苹果分开”表示把两种苹果分别放置，符合句意。", "融合": "语义：“融合”指使不同事物合成一体，与“分开”的要求正相反。", "掺和": "语义：“掺和”指把东西混在一起，与把大苹果和小苹果分开的要求相反。", "结合": "搭配：“结合”多用于抽象事物或力量，不用于两堆具体的水果。"}, "sentence_index": 6, "correct_answer": "分开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他往牛奶里分开了一勺糖。", "explanation": "这里应该用〈溶解〉。分开指使原本在一起的东西不再聚合，不能表示固体在液体里化开。"}, {"text": "工人把那堵旧墙分开了。", "explanation": "这里应该用〈拆除〉。分开指使原本在一起的东西分离，不能用来表示把整堵墙拆掉。"}, {"text": "他这次数学分开了九十分。", "explanation": "这里应该用〈得〉。分开表示使原本在一起的东西不再聚合，不能用来表示获得分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩车站分开了。", "corrected_sentence": "他们俩在车站分开了。", "error_description": "错误形式：“车站分开了”。正确形式：“在车站分开了”。地点状语需要介词“在”引出，“在”不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把大西瓜和小西瓜分开了。", "corrected_sentence": "请把大西瓜和小西瓜分开。", "error_description": "错误形式：“分开了”。“请”引出的祈使句不能用完成体“了”，应去掉，说“请把大西瓜和小西瓜分开。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
