INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25944, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西按类别放好。", "primary_collocate": null, "pronunciation": "fēn lèi guǎn lǐ", "ipa": "fən˥ lei˥˩ kwan˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "他把书分类管理，放在不同的书架上。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把衣服分类管理，夏天的和冬天的分开放。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把工具分类管理。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把玩具分类管理，放进三个盒子。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教孩子分类管理自己的文具。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个周末都分类管理家里的东西。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库的东西太乱了，得分类管理。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把照片分类管理一下，找起来更快。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把螺丝分类管理，放进小盒子里。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员把新到的衣服分类管理好了。", "target_word": "分类管理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分类管理了", "label": "体标"}, {"form": "分类管理过", "label": "体标"}, {"form": "分類管理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把物品按类别整理放好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b637169d-fc3a-4445-b0ef-7e8b7705b7e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撕", "is_correct": false, "explanation": "语义：撕书之后不能再把书放在书架上，与句意不合。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧掉的书无法放在书架上，与句意相反。"}, {"text": "借", "is_correct": false, "explanation": "搭配：“借”搭配借还、借给等动作，不能说把书借了再放在书架上。"}, {"text": "分类管理", "is_correct": true, "explanation": "分类管理：把书按类别放好，与“放在不同的书架上”相符。"}], "explanations": {"撕": "语义：撕书之后不能再把书放在书架上，与句意不合。", "烧": "语义：烧掉的书无法放在书架上，与句意相反。", "借": "搭配：“借”搭配借还、借给等动作，不能说把书借了再放在书架上。", "分类管理": "分类管理：把书按类别放好，与“放在不同的书架上”相符。"}, "sentence_index": 0, "correct_answer": "分类管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明把房间分类管理干净。", "explanation": "这里应该用〈打扫〉。把房间收拾干净要用打扫，分类管理是按类别放好，不能说把房间分类管理干净。"}, {"text": "他把花瓶分类管理在桌子上。", "explanation": "这里应该用〈摆放〉。把物品放在某处要用摆放或放，分类管理强调按类别放好，不能带处所宾语。"}, {"text": "他把书分类管理给图书馆。", "explanation": "这里应该用〈归还〉。把书交还给图书馆要用归还，分类管理不表示交还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浇水", "is_correct": false, "explanation": "搭配：“浇水”的对象是植物，不能说东西要浇水。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌，不能用于东西的整理。"}, {"text": "分类管理", "is_correct": true, "explanation": "分类管理：把东西按类别放好，与“仓库的东西太乱了”的语境相符。"}, {"text": "放大", "is_correct": false, "explanation": "语义：放大与“东西太乱，需要整理”的语义不符。"}], "explanations": {"浇水": "搭配：“浇水”的对象是植物，不能说东西要浇水。", "唱": "搭配：“唱”的对象是歌，不能用于东西的整理。", "分类管理": "分类管理：把东西按类别放好，与“仓库的东西太乱了”的语境相符。", "放大": "语义：放大与“东西太乱，需要整理”的语义不符。"}, "sentence_index": 6, "correct_answer": "分类管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把碗分类管理干净。", "explanation": "这里应该用〈清洗〉。把碗洗干净要用清洗，分类管理是按类别放好，不能说把碗分类管理干净。"}, {"text": "他把木材分类管理在院子里。", "explanation": "这里应该用〈堆放〉。把物品堆放在某处要用堆放，分类管理强调按类别放好，不能带处所宾语。"}, {"text": "班长把任务分类管理给每个人。", "explanation": "这里应该用〈分配〉。任务的分派要用分配，分类管理不表示把任务交给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把衣服分类管理地很好。", "corrected_sentence": "妈妈把衣服分类管理得很好。", "error_description": "补语标记应为“得”，用于引出结果程度；“地”是状语标记，只能放在动词前，不能用在“分类管理”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把工具分类管理了好。", "corrected_sentence": "我们把工具分类管理好了。", "error_description": "补语“好”应紧跟在“分类管理”之后，说“分类管理好了”；不能把“了”放在“好”之前，说“分类管理了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9f7013d-6a9d-4857-ae33-ae9e3066d6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做一件事想要达到的结果或目标。", "primary_collocate": "达到", "pronunciation": "mù dì", "ipa": "mu˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "为了达到目的，他每天都练习。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于达到了目的。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的目的达到了，可以回家了。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不达目的，他不会放手。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不择手段，只为达到自己的目的。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法能让你达到目的。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的目的没有达到，很不高兴。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了这个目的，大家都很努力。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用了很多办法，才实现目的。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有达到目的，我们不会停下来。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "目的地", "label": "复合"}], "register": "中性", "sense_fingerprint": "努力想要到达或实现的那个结果", "collocate_grounding": {"status": "corpus_validated", "reason": "corpus_collocations PMI 12.28 >= 5.0", "source": "corpus_collocations", "score": 12.275}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730e64f6-c995-4cfd-ab89-a28de46c42ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "目的", "is_correct": true, "explanation": "正确。目的（mù dì）指做一件事想要达到的结果或目标。"}, {"text": "木笛", "is_correct": false, "explanation": "木笛（mù dí）与目的（mù dì）第二音节声调不同（dí 第二声，dì 第四声），意思是木头做的笛子。"}, {"text": "木底", "is_correct": false, "explanation": "木底（mù dǐ）与目的第二音节声调不同（dǐ 第三声），意思是木头做的鞋底。"}, {"text": "亩地", "is_correct": false, "explanation": "亩地（mǔ dì）与目的第一音节声调不同（mǔ 第三声，mù 第四声），意思是农田。"}], "explanations": {"目的": "正确。目的（mù dì）指做一件事想要达到的结果或目标。", "木笛": "木笛（mù dí）与目的（mù dì）第二音节声调不同（dí 第二声，dì 第四声），意思是木头做的笛子。", "木底": "木底（mù dǐ）与目的第二音节声调不同（dǐ 第三声），意思是木头做的鞋底。", "亩地": "亩地（mǔ dì）与目的第一音节声调不同（mǔ 第三声，mù 第四声），意思是农田。"}, "sentence_index": null, "correct_answer": "目的"}, "level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "搭配：“达到”不能带“天气”作宾语，句中表达不出做事想要得到的结果。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的属性，不是做事想要达到的结果，“为了达到颜色”句意不通。"}, {"text": "目的", "is_correct": true, "explanation": "正确：“目的”是做事想要达到的结果，与“达到”搭配，“为了达到目的”表示做事的目标。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“达到”后面接“目的”“目标”“水平”等，不接“感情”，句中无法成立。"}], "explanations": {"天气": "搭配：“达到”不能带“天气”作宾语，句中表达不出做事想要得到的结果。", "颜色": "语义：“颜色”是事物的属性，不是做事想要达到的结果，“为了达到颜色”句意不通。", "目的": "正确：“目的”是做事想要达到的结果，与“达到”搭配，“为了达到目的”表示做事的目标。", "感情": "搭配：“达到”后面接“目的”“目标”“水平”等，不接“感情”，句中无法成立。"}, "sentence_index": 0, "correct_answer": "目的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的目的很充分，所以不参加比赛。", "explanation": "这里应该用〈理由〉。「充分」修饰理由或根据，目的指想要达到的结果，不能说「目的很充分」。"}, {"text": "这次比赛的目的已经出来了。", "explanation": "这里应该用〈结果〉。比赛的结果可以出来，目的是事先设定的，不能说“出来”。"}, {"text": "这次失误的目的很严重。", "explanation": "这里应该用〈后果〉。“严重”形容失误造成的影响，目的是人想要达到的目标，不能用“严重”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”是一顿饭，不是可以“达到”的结果，“他的午饭没有达到”句意荒谬。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“达到”不能与“性格”搭配，“性格没有达到”无法表达句中的意思。"}, {"text": "目的", "is_correct": true, "explanation": "正确：“目的”是人想要达到的结果，“没有达到”与“很不高兴”前后呼应。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是具体的建筑物件，不能“达到”，句意荒谬。"}], "explanations": {"午饭": "语义：“午饭”是一顿饭，不是可以“达到”的结果，“他的午饭没有达到”句意荒谬。", "性格": "搭配：“达到”不能与“性格”搭配，“性格没有达到”无法表达句中的意思。", "目的": "正确：“目的”是人想要达到的结果，“没有达到”与“很不高兴”前后呼应。", "窗户": "语义：“窗户”是具体的建筑物件，不能“达到”，句意荒谬。"}, "sentence_index": 6, "correct_answer": "目的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动的目的很精彩。", "explanation": "这里应该用〈过程〉。“精彩”形容活动进行的经过，目的是想要达到的结果，不能用“精彩”来形容。"}, {"text": "他脸上的目的很平静。", "explanation": "这里应该用〈表情〉。“平静”形容人的表情或心情，目的指做事想要达到的结果，不能描述脸色。"}, {"text": "这列火车的目的很快。", "explanation": "这里应该用〈速度〉。“快”描述的是运行的快慢，目的不能用来描述速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一座明确的目的。", "corrected_sentence": "他有一个明确的目的。", "error_description": "量词错误：“目的”应该用量词“个”，不能用“座”。“座”用于山、桥、房屋等大型固定的物体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的目的们已经达到了。", "corrected_sentence": "我们的目的已经达到了。", "error_description": "“们”的使用错误：“们”只用于指人的名词，抽象名词“目的”后面不能加“们”，应说“我们的目的”，不能说“我们的目的们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
