INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25956, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25956, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把借来的东西还回去。", "primary_collocate": null, "pronunciation": "guī huán", "ipa": "ku̯eɪ̯⁵⁵ xu̯an³⁵", "syllable_count": 2, "sentences": [{"text": "我借你的书，周五一定归还。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学借了我的笔，今天归还了。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆的书要在三十天内归还。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把借来的自行车归还给了邻居。", "target_word": "归还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用完工具后，请马上归还。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟忘了归还朋友的玩具。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "借来的雨伞，我下午会归还。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你什么时候归还我的字典？", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她按时归还了借来的光盘。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，借的教室钥匙要及时归还。", "target_word": "归还", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "归还了", "label": "体标"}, {"form": "归还过", "label": "体标"}, {"form": "歸還", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把借来的东西还回去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23dfa03-b845-44a8-b153-08ac3a942371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25956, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "归还", "is_correct": true, "explanation": "归还 guī huán，意思是把借来的东西还回去。"}, {"text": "规划", "is_correct": false, "explanation": "规划 guī huà：第一个音节相同，第二个音节 huà 去掉了韵尾 n 且声调不同（第四声），意思是计划。"}, {"text": "桂花", "is_correct": false, "explanation": "桂花 guì huā：第一个音节声调不同（guì 为第四声），第二个音节 huā 去掉了韵尾 n，意思是桂花。"}, {"text": "鬼话", "is_correct": false, "explanation": "鬼话 guǐ huà：第一个音节声调不同（guǐ 为第三声），第二个音节去掉韵尾 n，意思是胡说的话。"}, {"text": "鬼混", "is_correct": false, "explanation": "鬼混 guǐ hùn：第一个音节声调不同（guǐ 为第三声），第二个音节韵母 uan 变为 un，意思是厮混。"}], "explanations": {"归还": "归还 guī huán，意思是把借来的东西还回去。", "规划": "规划 guī huà：第一个音节相同，第二个音节 huà 去掉了韵尾 n 且声调不同（第四声），意思是计划。", "桂花": "桂花 guì huā：第一个音节声调不同（guì 为第四声），第二个音节 huā 去掉了韵尾 n，意思是桂花。", "鬼话": "鬼话 guǐ huà：第一个音节声调不同（guǐ 为第三声），第二个音节去掉韵尾 n，意思是胡说的话。", "鬼混": "鬼混 guǐ hùn：第一个音节声调不同（guǐ 为第三声），第二个音节韵母 uan 变为 un，意思是厮混。"}, "sentence_index": null, "correct_answer": "归还"}, "level_3": {"options": [{"text": "归还", "is_correct": true, "explanation": "“借你的书”之后承诺周五归还，符合句意。"}, {"text": "购买", "is_correct": false, "explanation": "语义：购买是买入，与“借你的书”的前提矛盾，句意不通。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：撕毁的书无法再还，与“周五一定”的承诺冲突。"}, {"text": "赠送", "is_correct": false, "explanation": "搭配：“借你的书”后接“赠送”会改变借还关系，不能说周五一定赠送。"}], "explanations": {"归还": "“借你的书”之后承诺周五归还，符合句意。", "购买": "语义：购买是买入，与“借你的书”的前提矛盾，句意不通。", "撕毁": "语义：撕毁的书无法再还，与“周五一定”的承诺冲突。", "赠送": "搭配：“借你的书”后接“赠送”会改变借还关系，不能说周五一定赠送。"}, "sentence_index": 0, "correct_answer": "归还"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不小心弄坏了邻居的自行车，已经归还了两百元。", "explanation": "这里应该用〈赔偿〉。归还是把借来的东西还给原主；因损坏而付钱要说赔偿。"}, {"text": "我终于归还了父母的养育之恩。", "explanation": "这里应该用〈报答〉。归还用于把借来的东西还给原主，恩情要说报答。"}, {"text": "他把自己的杂志归还给了朋友。", "explanation": "这里应该用〈赠送〉。杂志是他自己的，不是借来的，只能说赠送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "归还", "is_correct": true, "explanation": "“借来的雨伞”下午归还，符合句意。"}, {"text": "偷走", "is_correct": false, "explanation": "语义：偷走是非法拿走，与“借来的雨伞”需要还回去的句意相反。"}, {"text": "转让", "is_correct": false, "explanation": "语义：转让是把所有权交给别人，与借来的物品需要还回去矛盾。"}, {"text": "抛弃", "is_correct": false, "explanation": "搭配：“抛弃”多用于人或感情，不能用于“借来的雨伞”。"}], "explanations": {"归还": "“借来的雨伞”下午归还，符合句意。", "偷走": "语义：偷走是非法拿走，与“借来的雨伞”需要还回去的句意相反。", "转让": "语义：转让是把所有权交给别人，与借来的物品需要还回去矛盾。", "抛弃": "搭配：“抛弃”多用于人或感情，不能用于“借来的雨伞”。"}, "sentence_index": 6, "correct_answer": "归还"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器有故障，我昨天去商店归还了。", "explanation": "这里应该用〈退还〉。归还指把借来的东西还给原主；买来的商品退回商店要用退还。"}, {"text": "他按时归还了房租。", "explanation": "这里应该用〈支付〉。归还指把借来的东西或钱还给原主，房租不是借来的钱，而是按期交给房东的费用，要说支付。"}, {"text": "她把全部工资归还给了希望小学。", "explanation": "这里应该用〈捐献〉。工资是自己的收入，主动无偿交给学校要说捐献，归还只用于借来的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把借来的相机归还了朋友。", "corrected_sentence": "他把借来的相机归还给了朋友。", "error_description": "错误：“归还了朋友”；正确：“归还给了朋友”。“归还”后面接收件人要用“归还给”，漏掉了“给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把借来的光盘归还了给同学。", "corrected_sentence": "她把借来的光盘归还给了同学。", "error_description": "错误：“归还了给同学”；正确：“归还给了同学”。“归还给”是一个结构，“了”应放在“给”之后，不能插在“归还”和“给”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
