INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25960, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一起做一件事，让事情变得更好。", "primary_collocate": null, "pronunciation": "gòng tóng nǔ lì", "ipa": "kʊŋ˥˩ tʰʊŋ˧˥ nu˨˩˦ li˥˩", "syllable_count": 4, "sentences": [{"text": "大家共同努力，把教室打扫得干干净净。", "target_word": "共同努力", "complexity_tier": "T3", "furigana": "dà jiā gòng tóng nǔ lì bǎ jiào shì dǎ sǎo de gān gān jìng jìng", "sentence_source": "generated"}, {"text": "想让班级更好，大家要共同努力。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈共同努力，给我们买了新房子。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们共同努力，把花园种得很漂亮。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有共同努力，我们才能拿到第一名。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们共同努力，修好了小路。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组共同努力，作业很快就做完了。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "让地球更干净，需要每个人共同努力。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们共同努力过，所以不后悔。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生和护士共同努力，救了那位老人。", "target_word": "共同努力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大家一起做事使其更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d5ca48-c41f-404e-b8aa-feb7d9f3a2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共同努力", "is_correct": true, "explanation": "正确：“共同努力”表示大家一起做事，让教室变得干净，符合句中的语境。"}, {"text": "闲聊", "is_correct": false, "explanation": "语义：“闲聊”与“把教室打扫得干干净净”的任务相矛盾，句意不通。"}, {"text": "偷懒", "is_correct": false, "explanation": "语义：“偷懒”与“把教室打扫得干干净净”的结果相矛盾，句意不通。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”与“打扫得干干净净”所表示的结果不搭配。"}], "explanations": {"共同努力": "正确：“共同努力”表示大家一起做事，让教室变得干净，符合句中的语境。", "闲聊": "语义：“闲聊”与“把教室打扫得干干净净”的任务相矛盾，句意不通。", "偷懒": "语义：“偷懒”与“把教室打扫得干干净净”的结果相矛盾，句意不通。", "吵闹": "搭配：“吵闹”与“打扫得干干净净”所表示的结果不搭配。"}, "sentence_index": 0, "correct_answer": "共同努力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们共同努力，偷偷溜出了教室。", "explanation": "这里误用了〈共同努力〉的意思。“共同努力”指为让事情变好而出力，偷偷溜出教室是逃避，与之意思相反，这里不能这样用。"}, {"text": "我一个人共同努力，把花园种好了。", "explanation": "这里应该用〈独自〉。“共同”指多人一起做事，只有一个人时不能用“共同”。"}, {"text": "我们共同努力，去超市买了一箱牛奶。", "explanation": "这里应该用〈一起〉。“共同努力”表示为了让事情变好而付出努力，买牛奶不需要这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共同努力", "is_correct": true, "explanation": "正确：“共同努力”表示小组成员一起做事，符合“作业很快就做完了”的结果。"}, {"text": "玩耍", "is_correct": false, "explanation": "语义：“玩耍”与“作业很快就做完了”的结果相矛盾，句意不通。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”与“作业很快就做完了”的结果相矛盾，句意不通。"}, {"text": "独自忙碌", "is_correct": false, "explanation": "搭配：“独自”只指一个人，与“小组”这样的多人集体不搭配。"}], "explanations": {"共同努力": "正确：“共同努力”表示小组成员一起做事，符合“作业很快就做完了”的结果。", "玩耍": "语义：“玩耍”与“作业很快就做完了”的结果相矛盾，句意不通。", "拖延": "语义：“拖延”与“作业很快就做完了”的结果相矛盾，句意不通。", "独自忙碌": "搭配：“独自”只指一个人，与“小组”这样的多人集体不搭配。"}, "sentence_index": 6, "correct_answer": "共同努力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个人为了抢一个座位共同努力。", "explanation": "这里应该用〈竞争〉。“共同努力”要求参与者目标一致，两人为抢座位是对手关系，应该用竞争来描述。"}, {"text": "几个人共同努力，把花园的花都踩坏了。", "explanation": "这里应该用〈破坏〉。“共同努力”指为让事情变好而出力，踩坏花园的意思正相反，这里不能这样用。"}, {"text": "我们共同努力，太阳就下山了。", "explanation": "这里误用了〈共同努力〉的意思。“共同努力”要求人为同一目标出力，太阳下山是自然现象，不能靠努力促成，这里用法错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的同学共同共同努力，把教室收拾得很整齐。", "corrected_sentence": "我们班的同学共同努力，把教室收拾得很整齐。", "error_description": "重复错误：“共同”只需说一次，应说“共同努力”，不能说“共同共同努力”，多写了一个“共同”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位老师共同努力，把学校办得很好。", "corrected_sentence": "几位老师共同努力，把学校办得很好。", "error_description": "数量错误：“共同”表示多人一起做事，主语只有一位老师时不能用“共同”，应改为“几位老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f525357-ca96-4cfc-b562-78c019393760') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
