INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25964, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一样东西和另一样东西放在一起。", "primary_collocate": null, "pronunciation": "jiā rù", "ipa": "tɕja˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "水开了以后，请加入一点盐。", "target_word": "加入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做蛋糕时，要在面粉里加入两个鸡蛋。", "target_word": "加入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把糖加入牛奶里，再搅一搅。", "target_word": "加入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在茶里加入了一点蜂蜜。", "target_word": "加入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做汤的时候，别忘了加入葱。", "target_word": "加入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把一点牛奶加入咖啡里。", "target_word": "加入", "complexity_tier": "T3", "furigana": "jiārù", "sentence_source": "generated"}, {"text": "菜快好了，再加入一点水。", "target_word": "加入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验时，老师在水里加入了一些盐。", "target_word": "加入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在饺子馅里加入了很多肉。", "target_word": "加入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先放米，再加入水，然后煮三十分钟。", "target_word": "加入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加入了", "label": "体标（了）"}, {"form": "加入过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "把一物放进另一物中混合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be7eb40f-7d8a-4232-9c49-ff679e0a5a7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25964, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加入", "is_correct": true, "explanation": "jiā rù 对应“加入”，指把一样东西放进另一样东西中。"}, {"text": "假如", "is_correct": false, "explanation": "声调混淆：jiǎ rú 与 jiā rù 声母韵母相同，只差声调，意思是如果。"}, {"text": "扎入", "is_correct": false, "explanation": "zhā 与 jiā 声母不同，意思是扎进去。"}, {"text": "加数", "is_correct": false, "explanation": "shù 与 rù 声母不同，意思是加法里被加的数。"}], "explanations": {"加入": "jiā rù 对应“加入”，指把一样东西放进另一样东西中。", "假如": "声调混淆：jiǎ rú 与 jiā rù 声母韵母相同，只差声调，意思是如果。", "扎入": "zhā 与 jiā 声母不同，意思是扎进去。", "加数": "shù 与 rù 声母不同，意思是加法里被加的数。"}, "sentence_index": null, "correct_answer": "加入"}, "level_3": {"options": [{"text": "加入", "is_correct": true, "explanation": "“加入”指放进去，与“水开了以后，请……一点盐”相合，是正确答案。"}, {"text": "逃跑", "is_correct": false, "explanation": "配价：“逃跑”不能带宾语，不能接“一点盐”。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”接的是活动、比赛，不能接“一点盐”。"}, {"text": "出现", "is_correct": false, "explanation": "配价：“出现”不能带“盐”这类宾语，“请出现一点盐”说不通。"}], "explanations": {"加入": "“加入”指放进去，与“水开了以后，请……一点盐”相合，是正确答案。", "逃跑": "配价：“逃跑”不能带宾语，不能接“一点盐”。", "参加": "搭配：“参加”接的是活动、比赛，不能接“一点盐”。", "出现": "配价：“出现”不能带“盐”这类宾语，“请出现一点盐”说不通。"}, "sentence_index": 0, "correct_answer": "加入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在毕业典礼上加入了话。", "explanation": "这里应该用〈讲〉。加入指把东西加到混合物中，不能用来说讲话。"}, {"text": "他加入了学校的篮球队。", "explanation": "这里是“成为组织成员”的意思，是“加入”的另一个义项，不是本词所教的“放进混合”义。"}, {"text": "他加入了一场电影。", "explanation": "这里应该用〈看〉。加入指把东西加到一起，不能用来说看电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加入", "is_correct": true, "explanation": "“加入”指加到里面，与“菜快好了，再……一点水”相合，是正确答案。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”不能带“水”这类宾语，“再结婚一点水”说不通。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”接的是文章、意见，不能接“一点水”。"}, {"text": "出差", "is_correct": false, "explanation": "配价：“出差”不能带宾语，不能接“一点水”。"}], "explanations": {"加入": "“加入”指加到里面，与“菜快好了，再……一点水”相合，是正确答案。", "结婚": "配价：“结婚”不能带“水”这类宾语，“再结婚一点水”说不通。", "发表": "搭配：“发表”接的是文章、意见，不能接“一点水”。", "出差": "配价：“出差”不能带宾语，不能接“一点水”。"}, "sentence_index": 6, "correct_answer": "加入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子加入了一整天。", "explanation": "这里应该用〈哭〉。加入指把东西加到一起，不能用来说哭了多久。"}, {"text": "我们加入汉语。", "explanation": "这里应该用〈学习〉。加入不表示学习知识。"}, {"text": "爸爸加入了自行车。", "explanation": "这里应该用〈修〉。加入指把东西加到一起，不能用来说修理自行车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶在汤里加入着一点葱。", "corrected_sentence": "奶奶在汤里加入了一点葱。", "error_description": "体标错误：“加入”是一次完成的动作，应用动态助词“了”，不能用“着”。正确：“加入了一点葱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈往锅里加入的一点醋。", "corrected_sentence": "妈妈往锅里加入了一点醋。", "error_description": "助词错误：动态助词“了”写成了结构助词“的”，“加入的一点醋”只是名词短语，不能作句子。正确：“加入了一点醋”，“了”表示动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
