INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25966, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "多付就是给了比应该给的钱更多的钱。", "primary_collocate": null, "pronunciation": "duō fù", "ipa": "tu̯ɔ⁵⁵ fu⁵¹", "syllable_count": 2, "sentences": [{"text": "我在店里多付了二十块钱。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李多付了钱，却不知道。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生多付了两元，老师把钱还给他。", "target_word": "多付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打车时，我多付了一些小费。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她多付了钱，店员马上退给她。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人多付了车钱，司机很不好意思。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了方便，我常常多付一点钱。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你多付了三十元，请看一下小票。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我发现多付了钱，赶快回去问店员。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多付的钱，老板说下次买东西时再扣。", "target_word": "多付", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "多付了", "label": "体标"}, {"form": "多付过", "label": "体标"}], "register": "中性", "sense_fingerprint": "给出比应付更多的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23dfa03-b845-44a8-b153-08ac3a942371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25966, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "多付", "is_correct": true, "explanation": "正确：多付（duō fù）指付的钱超过应该付的数目。"}, {"text": "托付", "is_correct": false, "explanation": "托付（tuō fù）与 duō fù 声母不同（t 与 d），意思是委托别人照管。"}, {"text": "多福", "is_correct": false, "explanation": "多福（duō fú，第二声）与 duō fù（第四声）声调不同，意思是福气很多。"}, {"text": "多份", "is_correct": false, "explanation": "多份（duō fèn）与 duō fù 韵母不同（-en 与 -u），意思是多出的一份。"}], "explanations": {"多付": "正确：多付（duō fù）指付的钱超过应该付的数目。", "托付": "托付（tuō fù）与 duō fù 声母不同（t 与 d），意思是委托别人照管。", "多福": "多福（duō fú，第二声）与 duō fù（第四声）声调不同，意思是福气很多。", "多份": "多份（duō fèn）与 duō fù 韵母不同（-en 与 -u），意思是多出的一份。"}, "sentence_index": null, "correct_answer": "多付"}, "level_3": {"options": [{"text": "多付", "is_correct": true, "explanation": "正确：“多付”指付了超过应付的钱，与“二十块钱”相符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣服，不能和钱款搭配。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是字，“写了二十块钱”说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与钱款无关，“唱了二十块钱”读起来不成意思。"}], "explanations": {"多付": "正确：“多付”指付了超过应付的钱，与“二十块钱”相符。", "穿": "搭配：“穿”的对象是衣服，不能和钱款搭配。", "写": "搭配：“写”的对象是字，“写了二十块钱”说不通。", "唱": "语义：“唱”与钱款无关，“唱了二十块钱”读起来不成意思。"}, "sentence_index": 0, "correct_answer": "多付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我多付了一本书。", "explanation": "这里应该用〈多买〉。多付只用于钱款，买书的数量要用“多买”。"}, {"text": "我为了等车多付了一个小时。", "explanation": "这里应该用〈多花〉。多付只用于钱款，花费时间要用“多花”。"}, {"text": "老师多付了我一次机会。", "explanation": "这里应该用〈多给〉。多付用于钱款，给人机会要用“多给”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多付", "is_correct": true, "explanation": "正确：“多付一点钱”指付得比应付的多，符合“为了方便”的语境。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”不能接钱款，“看一点钱”说不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是表面，不能和钱款搭配。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬一点钱”不成意思，与“为了方便”的语境无关。"}], "explanations": {"多付": "正确：“多付一点钱”指付得比应付的多，符合“为了方便”的语境。", "看": "语义：“看”不能接钱款，“看一点钱”说不通。", "擦": "搭配：“擦”的对象是表面，不能和钱款搭配。", "咬": "语义：“咬一点钱”不成意思，与“为了方便”的语境无关。"}, "sentence_index": 6, "correct_answer": "多付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我多付了一部电影。", "explanation": "这里应该用〈多看〉。多付的对象是钱款，看电影要用“多看”。"}, {"text": "我今天多付了一首歌。", "explanation": "这里应该用〈多听〉。多付只用于钱款，听歌的量要用“多听”。"}, {"text": "他多付了一句话。", "explanation": "这里应该用〈多说〉。多付用于钱款，说话的量要用“多说”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在超市多付着三十块钱，收银员马上退给了我。", "corrected_sentence": "我在超市多付了三十块钱，收银员马上退给了我。", "error_description": "体标错误：“多付”是已经完成的动作，应用“了”；“着”表示动作持续或状态，不能用于这里。应改为“多付了三十块钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次我没多付了二十块，司机也没说什么。", "corrected_sentence": "那次我没多付二十块，司机也没说什么。", "error_description": "体标错误：“没”表示动作没有发生，否定句中不能再用“了”。应改为“没多付二十块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd5c8a1c-5dde-4c3c-8285-8d552d05e43a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
