INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "实体就是真实存在的东西。", "primary_collocate": null, "pronunciation": "shí tǐ", "ipa": "ʂɻ̩³⁵ tʰi²¹⁴", "syllable_count": 2, "sentences": [{"text": "梦里的东西不是实体，醒了就没有了。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你摸得到它，它就是实体。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影子看得见，但不是实体。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕里的花不是实体，花店里的才是。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彩虹看起来很美，却不是实体。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人是实体，不是电脑里的画面。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问：“云是实体吗？”", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实体有大小，有重量，我们可以摸到。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的怪兽不是实体，是电脑做的。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个模型是实体，你可以拿在手里看。", "target_word": "实体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "實體", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "真实存在、能摸到的东西，与幻象或虚拟相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '281d9421-fb6f-489e-9c50-1dff686839f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实体", "is_correct": true, "explanation": "正确：“实体”指真实存在、能摸到的东西，与“醒了就没有了”的虚幻相对。"}, {"text": "梦境", "is_correct": false, "explanation": "语义：“梦境”指梦本身，梦里的东西就在梦境中，说它不是梦境与句意矛盾。"}, {"text": "幻影", "is_correct": false, "explanation": "语义：“幻影”指虚幻的影像，与“醒了就没有了”的特征一致，说“不是幻影”自相矛盾。"}, {"text": "数字", "is_correct": false, "explanation": "语义：“数字”指数码或数目，与“梦里的东西”无关，句意不通。"}], "explanations": {"实体": "正确：“实体”指真实存在、能摸到的东西，与“醒了就没有了”的虚幻相对。", "梦境": "语义：“梦境”指梦本身，梦里的东西就在梦境中，说它不是梦境与句意矛盾。", "幻影": "语义：“幻影”指虚幻的影像，与“醒了就没有了”的特征一致，说“不是幻影”自相矛盾。", "数字": "语义：“数字”指数码或数目，与“梦里的东西”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "实体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的实体很长，我读了很久。", "explanation": "这里应该用〈篇幅〉。“实体”指真实存在的东西，不表示文章的长短；说“文章的实体很长”不通，这里词义用错了。"}, {"text": "这个计划理论上可行，但实体上很难做到。", "explanation": "这里应该用〈实际〉。“实体”指真实存在的东西，不表示“实际、实在”，不能说“实体上”。"}, {"text": "他的实体很强，大家都有点怕他。", "explanation": "这里应该用〈实力〉。“实体”指真实存在的东西，不表示力量；说“实体很强”不通，这里词义用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实体", "is_correct": true, "explanation": "正确：孩子问的是云是不是真实存在、能摸到的东西。"}, {"text": "念头", "is_correct": false, "explanation": "语义：“念头”是头脑中的想法，云不是念头，这样发问无法理解。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”只用来说人或动物的样子，不能用来问云是否存在。"}, {"text": "行动", "is_correct": false, "explanation": "语义：“行动”指人的做事，云不是行动，这样发问没有意义。"}], "explanations": {"实体": "正确：孩子问的是云是不是真实存在、能摸到的东西。", "念头": "语义：“念头”是头脑中的想法，云不是念头，这样发问无法理解。", "外貌": "体貌：“外貌”只用来说人或动物的样子，不能用来问云是否存在。", "行动": "语义：“行动”指人的做事，云不是行动，这样发问没有意义。"}, "sentence_index": 6, "correct_answer": "实体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个词的实体很多，需要查字典。", "explanation": "这里应该用〈意思〉。“实体”指真实存在的东西，不指词语的含义；说“词的实体很多”不通，这里词义用错了。"}, {"text": "我的实体很饿，想吃点东西。", "explanation": "这里应该用〈肚子〉。觉得饿要说“肚子饿”，“实体”指真实存在的东西，不能用来指身体的部位，这里词义用错了。"}, {"text": "他的实体很快乐，一直在唱歌。", "explanation": "这里应该用〈心情〉。快乐是心情，应说“心情很好”；“实体”指真实存在的东西，不能用来形容情绪，这里词义用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木头是一棵实体，你可以摸到它。", "corrected_sentence": "这块木头是一个实体，你可以摸到它。", "error_description": "量词错误：“实体”前应用量词“个”。“棵”只用于树木、植物，不能用来数“实体”，应改为“一个实体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把椅子是一条实体，能摸到，也能坐。", "corrected_sentence": "这把椅子是一个实体，能摸到，也能坐。", "error_description": "量词错误：“实体”前应用量词“个”。“条”多用于细长的东西，如绳子、河流，不能用来数“实体”，应改为“一个实体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
