INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25972, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人或事物走过的道路或者经历的事情。", "primary_collocate": null, "pronunciation": "lì chéng", "ipa": "li˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这本书讲了老人一生的历程。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的创业历程很不容易。", "target_word": "历程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子的成长历程让妈妈很高兴。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想写下自己的学习历程。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的发展历程很长。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们介绍了那位科学家的研究历程。", "target_word": "历程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店走过了一百年的历程。", "target_word": "历程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回头看这段历程，他笑了。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷常说起自己的人生历程。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影记录了球队的奋斗历程。", "target_word": "历程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段历程", "label": "量词"}, {"form": "人生历程", "label": "复合"}, {"form": "歷程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或事物一路走过、经历的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0fbe80-3322-4a2e-a4d7-d218a61d1e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程（第四声）指走过的道路或经历的事情，与听到的读音一致。"}, {"text": "日程", "is_correct": false, "explanation": "声调无关的单音位混淆：rì chéng 与 lì chéng 仅声母 r/l 不同，意思是每天的安排。"}, {"text": "礼成", "is_correct": false, "explanation": "声调混淆：lǐ chéng 与 lì chéng 仅首音节声调不同，意思是典礼结束。"}, {"text": "里程", "is_correct": false, "explanation": "声调混淆：lǐ chéng 与 lì chéng 仅首音节声调不同，意思是路程的长度。"}], "explanations": {"历程": "历程（第四声）指走过的道路或经历的事情，与听到的读音一致。", "日程": "声调无关的单音位混淆：rì chéng 与 lì chéng 仅声母 r/l 不同，意思是每天的安排。", "礼成": "声调混淆：lǐ chéng 与 lì chéng 仅首音节声调不同，意思是典礼结束。", "里程": "声调混淆：lǐ chéng 与 lì chéng 仅首音节声调不同，意思是路程的长度。"}, "sentence_index": null, "correct_answer": "历程"}, "level_3": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程指一生走过的道路或经历，与“一生”搭配，指老人的人生经历。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句的书面语体不合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的钱数，不能是一本书讲述的人生内容。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与讲老人一生的经历无关。"}], "explanations": {"历程": "历程指一生走过的道路或经历，与“一生”搭配，指老人的人生经历。", "玩意儿": "语域：“玩意儿”是口语说法，与这句的书面语体不合。", "价格": "语义：“价格”指商品的钱数，不能是一本书讲述的人生内容。", "体温": "语义：“体温”指身体的温度，与讲老人一生的经历无关。"}, "sentence_index": 0, "correct_answer": "历程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这面墙的历程很亮。", "explanation": "这里应该用〈颜色〉。说墙亮不亮，指的是颜色；历程指一个人或事物走过的道路或经历，不能形容颜色。"}, {"text": "这个历程里人很多。", "explanation": "这里应该用〈市场〉。人很多的场所是市场；历程指走过的道路或经历的事情，不指场所。"}, {"text": "他用钥匙打开了历程。", "explanation": "这里应该用〈门〉。钥匙能打开的是门；历程指走过的道路或经历的事情，不是可以打开的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25972, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程（第四声）指走过的道路或经历的事情，与听到的读音一致。"}, {"text": "黎城", "is_correct": false, "explanation": "lí chéng 与 lì chéng 仅首字声调不同，黎城是山西省的一个县名。"}, {"text": "议程", "is_correct": false, "explanation": "yì chéng 与 lì chéng 仅声母不同（y 与 l），议程指会议的进行安排。"}, {"text": "立场", "is_correct": false, "explanation": "lì chǎng 与 lì chéng 后字的韵母与声调不同，立场指对问题的态度或观点。"}], "explanations": {"历程": "历程（第四声）指走过的道路或经历的事情，与听到的读音一致。", "黎城": "lí chéng 与 lì chéng 仅首字声调不同，黎城是山西省的一个县名。", "议程": "yì chéng 与 lì chéng 仅声母不同（y 与 l），议程指会议的进行安排。", "立场": "lì chǎng 与 lì chéng 后字的韵母与声调不同，立场指对问题的态度或观点。"}, "sentence_index": null, "correct_answer": "历程"}, "level_3": {"options": [{"text": "历程", "is_correct": true, "explanation": "历程指走过的道路或经历，老店走过一百年的经历可以说历程。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性格和情绪，老店不能走过一百年的脾气。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“走过”可以用于道路、岁月，不搭配“数量”。"}, {"text": "气温", "is_correct": false, "explanation": "语义：“气温”是空气的冷热，与老店走过的时间无关。"}], "explanations": {"历程": "历程指走过的道路或经历，老店走过一百年的经历可以说历程。", "脾气": "语义：“脾气”指性格和情绪，老店不能走过一百年的脾气。", "数量": "搭配：“走过”可以用于道路、岁月，不搭配“数量”。", "气温": "语义：“气温”是空气的冷热，与老店走过的时间无关。"}, "sentence_index": 6, "correct_answer": "历程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的历程很冷，冻得发抖。", "explanation": "这里应该用〈手〉。冻得发抖、感到冷的是身体部位；历程指走过的道路或经历的事情，不能形容身体的冷。"}, {"text": "历程很烫，小心别碰。", "explanation": "这里应该用〈汤〉。这句说的是可以烫人的东西；历程指经历的过程，不是可以触碰的东西。"}, {"text": "孩子们在历程里踢球。", "explanation": "这里应该用〈操场〉。孩子们踢球的地方是操场；历程指经历的过程或道路，不能表示场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她回顾了一段漫长地历程。", "corrected_sentence": "她回顾了一段漫长的历程。", "error_description": "修饰语错误：“漫长”作定语修饰名词“历程”，应用“的”连接；用“地”（标示状语）错误。应说“漫长的历程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于走完了一颗艰难的历程。", "corrected_sentence": "他们终于走完了一段艰难的历程。", "error_description": "量词错误：“历程”用“段”计量，应说“一段艰难的历程”；“颗”用于圆粒状的东西，不能用于历程。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fce6ab56-25c3-41a0-a957-ca934474f575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
