INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西里面出现很多小泡泡。", "primary_collocate": null, "pronunciation": "fā pào", "ipa": "fa˥ pʰau˥˩", "syllable_count": 2, "sentences": [{"text": "沐浴露一揉就发泡，味道也好闻。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水泥里加了药粉，就会发泡变轻。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂用机器让塑料发泡，做成软垫。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个牌子的洗碗液发泡不多。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把洗发水倒在手上，一搓就发泡了。", "target_word": "发泡", "complexity_tier": "T3", "furigana": "wǒ bǎ xǐ fà shuǐ dào zài shǒu shàng, yì cuō jiù fā pào le.", "sentence_source": "generated"}, {"text": "这罐饮料摇过以后会发泡。", "target_word": "发泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油漆发泡了，墙面看起来不平。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋清用打蛋器搅，很快就发泡。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种材料一加热就发泡，体积变大。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这盆水里加了洗洁精，搅几下就发泡了。", "target_word": "发泡", "complexity_tier": "T3", "furigana": "zhè pén shuǐ lǐ jiā le xǐ jié jīng, jiǎo jǐ xià jiù fā pào le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "发泡了", "label": "体标"}, {"form": "发泡剂", "label": "复合"}, {"form": "發泡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西里面出现许多小泡泡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '281d9421-fb6f-489e-9c50-1dff686839f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发泡", "is_correct": true, "explanation": "发泡（fā pào）：东西里面出现很多小泡泡。"}, {"text": "发报", "is_correct": false, "explanation": "发报（fā bào）与 fā pào 只差声母 b/p，声调相同，意思是拍发电报。"}, {"text": "发包", "is_correct": false, "explanation": "发包（fā bāo）与 fā pào 声母不同（b/p），声调也不同，意思是把工程或业务承包出去。"}, {"text": "发票", "is_correct": false, "explanation": "发票（fā piào）比 fā pào 多一个介音 i，意思是开具的收款凭证。"}], "explanations": {"发泡": "发泡（fā pào）：东西里面出现很多小泡泡。", "发报": "发报（fā bào）与 fā pào 只差声母 b/p，声调相同，意思是拍发电报。", "发包": "发包（fā bāo）与 fā pào 声母不同（b/p），声调也不同，意思是把工程或业务承包出去。", "发票": "发票（fā piào）比 fā pào 多一个介音 i，意思是开具的收款凭证。"}, "sentence_index": null, "correct_answer": "发泡"}, "level_3": {"options": [{"text": "发泡", "is_correct": true, "explanation": "“一揉就发泡”指沐浴露揉搓后产生小泡泡，与“味道也好闻”的描述一致。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”指遇冷变硬，与“一揉”的动作不符，沐浴露揉后不会冻结。"}, {"text": "烘干", "is_correct": false, "explanation": "搭配：“烘干”指烘去水分，与“一揉就”的动作和结果不搭配。"}, {"text": "切开", "is_correct": false, "explanation": "语义：“切开”需要人主动切割，且会把物体割开，与句中“揉”的情况不符。"}], "explanations": {"发泡": "“一揉就发泡”指沐浴露揉搓后产生小泡泡，与“味道也好闻”的描述一致。", "冻结": "语义：“冻结”指遇冷变硬，与“一揉”的动作不符，沐浴露揉后不会冻结。", "烘干": "搭配：“烘干”指烘去水分，与“一揉就”的动作和结果不搭配。", "切开": "语义：“切开”需要人主动切割，且会把物体割开，与句中“揉”的情况不符。"}, "sentence_index": 0, "correct_answer": "发泡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "铁锅放在潮湿的地方，很快就发泡了。", "explanation": "这里应该用〈生锈〉。铁遇潮氧化生成铁锈，应说“生锈”；“发泡”指东西里出现很多小泡泡，不能形容金属氧化。"}, {"text": "石头长期暴露在风雨中，会发泡。", "explanation": "这里应该用〈风化〉。石头受风雨侵蚀逐渐变松，应说“风化”；“发泡”指东西里出现很多小泡泡，与石头变松无关。"}, {"text": "盐放进水里会发泡。", "explanation": "这里应该用〈溶解〉。盐溶于水并不产生泡沫，“发泡”不能用于此情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发泡", "is_correct": true, "explanation": "“油漆发泡了”指油漆膜鼓起成泡，导致墙面不平，句意通顺。"}, {"text": "抹平", "is_correct": false, "explanation": "语义：“抹平”表示使表面平整，与句末的“墙面看起来不平”矛盾。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：“煮沸”指加热到水沸腾，油漆不会被煮沸，与句意不符。"}, {"text": "刷新", "is_correct": false, "explanation": "搭配：“刷新”指更新、提高，不能用来描述油漆的状态，搭配不当。"}], "explanations": {"发泡": "“油漆发泡了”指油漆膜鼓起成泡，导致墙面不平，句意通顺。", "抹平": "语义：“抹平”表示使表面平整，与句末的“墙面看起来不平”矛盾。", "煮沸": "语义：“煮沸”指加热到水沸腾，油漆不会被煮沸，与句意不符。", "刷新": "搭配：“刷新”指更新、提高，不能用来描述油漆的状态，搭配不当。"}, "sentence_index": 6, "correct_answer": "发泡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玻璃杯遇到热水就发泡了。", "explanation": "这里应该用〈开裂〉。玻璃骤遇热水会裂开，应说“开裂”；“发泡”指东西里出现很多小泡泡，不能形容玻璃破裂。"}, {"text": "孩子用吸管发泡泡玩。", "explanation": "这里应该用〈吹〉。“吹泡泡”是人主动吹出，“发泡”指物质自身产生泡沫，不能表示人的动作。"}, {"text": "牛奶加入柠檬汁后，很快就发泡了。", "explanation": "这里应该用〈凝固〉。牛奶遇酸会凝结成块，并不产生泡沫，不能用“发泡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这瓶洗洁精一摇就被发泡了。", "corrected_sentence": "这瓶洗洁精一摇就发泡了。", "error_description": "“发泡”是不及物动词，不能用“被”构成被动句，应说“就发泡了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种洗洁精一搓就发泡的很快。", "corrected_sentence": "这种洗洁精一搓就发泡得很快。", "error_description": "“发泡”后面引出程度补语时要用助词「得」，不能用「的」，应说“发泡得很快”，不能说“发泡的很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
