INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们买来用的东西。", "primary_collocate": null, "pronunciation": "xiāo fèi pǐn", "ipa": "ɕiɑʊ˥ feɪ˥˩ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个商场里的消费品很便宜。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙刷和毛巾都是常见的消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每天都在买各种消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想开一家卖消费品的商店。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些消费品质量很好，大家都喜欢。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈去市场买了不少消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打折的时候，消费品卖得特别快。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场上每年都有新的消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣液是家里必须买的消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上买消费品又快又方便。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种消费品", "label": "量词"}, {"form": "日用消费品", "label": "复合"}, {"form": "耐用消费品", "label": "复合"}, {"form": "消費品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们购买来使用的日常东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ab76373-a806-4838-933e-5ef3747780ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消费品", "is_correct": true, "explanation": "正确。“消费品”指人们买来用的东西，商场里卖的正是这类东西。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”是上学交的钱，不是商场里的东西，与“商场里的”不符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“便宜”用于价格或商品，不能说天气很便宜。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气没有价格，不能说很便宜。"}], "explanations": {"消费品": "正确。“消费品”指人们买来用的东西，商场里卖的正是这类东西。", "学费": "语义：“学费”是上学交的钱，不是商场里的东西，与“商场里的”不符。", "天气": "搭配：“便宜”用于价格或商品，不能说天气很便宜。", "空气": "搭配：空气没有价格，不能说很便宜。"}, "sentence_index": 0, "correct_answer": "消费品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家网站很重视消费品的建议。", "explanation": "这里应该用〈消费者〉。消费品是物品，不能提建议；提建议的是人，要用〈消费者〉。"}, {"text": "这家厂子出售的消费品都是重型机械。", "explanation": "这里应该用〈商品〉。消费品专指供人们生活使用的东西，重型机械不属于这一类。"}, {"text": "工地上堆放的消费品主要是水泥和沥青。", "explanation": "这里应该用〈物品〉。消费品专指供人们生活使用的东西，水泥和沥青是建筑材料，不属于这一类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消费品", "is_correct": true, "explanation": "正确。“卖”的对象是人们买来使用的东西，打折时卖得快的正是消费品。"}, {"text": "经验", "is_correct": false, "explanation": "搭配：此处是打折促销，卖的是商品，“经验”不是可以打折出售的东西，与语境不符。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：心情不能拿去卖，“卖”不搭配“心情”。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“节日”是时间，不是可以卖出去的东西，与“打折”的语境不符。"}], "explanations": {"消费品": "正确。“卖”的对象是人们买来使用的东西，打折时卖得快的正是消费品。", "经验": "搭配：此处是打折促销，卖的是商品，“经验”不是可以打折出售的东西，与语境不符。", "心情": "搭配：心情不能拿去卖，“卖”不搭配“心情”。", "节日": "语义：“节日”是时间，不是可以卖出去的东西，与“打折”的语境不符。"}, "sentence_index": 6, "correct_answer": "消费品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校的消费品包括教学楼和操场。", "explanation": "这里应该用〈资产〉。消费品专指供人们生活使用的东西，教学楼和操场属于学校资产，不能算消费品。"}, {"text": "这家工厂采购的消费品主要是铁矿石和焦炭。", "explanation": "这里应该用〈原材料〉。消费品专指供人们生活使用的东西，铁矿石和焦炭是生产用的原材料，不属于这一类。"}, {"text": "这家洗车店提供的消费品是洗车和打蜡。", "explanation": "语义：洗车、打蜡属于服务，不是有形的消费品，这里不能用“消费品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个市场里有很多只消费品。", "corrected_sentence": "这个市场里有很多种消费品。", "error_description": "量词误用：“消费品”前应用“种”或“件”，“只”多用于动物或成对、单个的物品，不能用于“消费品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些消费品们价格都很便宜。", "corrected_sentence": "这些消费品价格都很便宜。", "error_description": "词尾误加：“们”只用于指人的名词，“消费品”是物品，不能加“们”，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25978, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "启用", "is_correct": true, "explanation": "反义：“启用”指开始使用某物，与“禁用”的不可使用正相反。"}, {"text": "推荐", "is_correct": false, "explanation": "推荐指介绍给别人选用，与禁用不构成反义，意思上不相对。"}, {"text": "赞助", "is_correct": false, "explanation": "赞助指出钱或出力支持某事，与禁用没有反义关系。"}, {"text": "吸收", "is_correct": false, "explanation": "吸收指把外来的东西接收进来，与禁用没有反义关系，这里不成立。"}], "correct_answer": "启用", "explanations": {"启用": "反义：“启用”指开始使用某物，与“禁用”的不可使用正相反。", "推荐": "推荐指介绍给别人选用，与禁用不构成反义，意思上不相对。", "赞助": "赞助指出钱或出力支持某事，与禁用没有反义关系。", "吸收": "吸收指把外来的东西接收进来，与禁用没有反义关系，这里不成立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25978, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "启用", "is_correct": true, "explanation": "反义：“启用”指开始使用某物，与“禁用”的不可使用正相反。"}, {"text": "扩大", "is_correct": false, "explanation": "扩大指使范围变大，与禁用没有反义关系，这里不成立。"}, {"text": "普及", "is_correct": false, "explanation": "普及指广泛推行，与禁用不构成反义，意思上不相对。"}, {"text": "试用", "is_correct": false, "explanation": "试用指先用一用看效果，与禁用没有反义关系，这里不成立。"}], "correct_answer": "启用", "explanations": {"启用": "反义：“启用”指开始使用某物，与“禁用”的不可使用正相反。", "扩大": "扩大指使范围变大，与禁用没有反义关系，这里不成立。", "普及": "普及指广泛推行，与禁用不构成反义，意思上不相对。", "试用": "试用指先用一用看效果，与禁用没有反义关系，这里不成立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25978, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不可以用。", "primary_collocate": null, "pronunciation": "jìn yòng", "ipa": "tɕin˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个功能还没开放，暂时禁用。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网站禁用了他的账号，他登不上去。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑里的摄像头禁用了，别人看不到你。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份药很强，小孩禁用。", "target_word": "禁用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司禁用这个软件，大家别下载。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里禁用手机，因为会影响仪器。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人身体不好，医生让他禁用这种药。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些词在网络游戏里禁用，不能发。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手机的定位功能禁用了。", "target_word": "禁用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加油站里禁用手机，很危险。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "禁用了", "label": "体标"}, {"form": "禁用过", "label": "体标"}, {"form": "禁用词", "label": "复合"}], "register": "书面", "sense_fingerprint": "某物、某功能或某种场合不可以使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '281d9421-fb6f-489e-9c50-1dff686839f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "禁用", "is_correct": true, "explanation": "正确：“暂时禁用”表示功能当前不能使用，与“还没开放”的语境相符。"}, {"text": "开放", "is_correct": false, "explanation": "语义：“开放”就是可以使用，与前句“还没开放”矛盾，说“暂时开放”不合句意。"}, {"text": "推广", "is_correct": false, "explanation": "语义：“推广”是大力普及，一个还没开放的功能不能说推广，句意说不通。"}, {"text": "允许", "is_correct": false, "explanation": "配价：“允许”需要带动作宾语，如“允许使用”，单独说“暂时允许”结构不完整。"}], "explanations": {"禁用": "正确：“暂时禁用”表示功能当前不能使用，与“还没开放”的语境相符。", "开放": "语义：“开放”就是可以使用，与前句“还没开放”矛盾，说“暂时开放”不合句意。", "推广": "语义：“推广”是大力普及，一个还没开放的功能不能说推广，句意说不通。", "允许": "配价：“允许”需要带动作宾语，如“允许使用”，单独说“暂时允许”结构不完整。"}, "sentence_index": 0, "correct_answer": "禁用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校禁用学生带手机。", "explanation": "这里应该用〈禁止〉。禁用的对象是物品或功能，不能直接带“学生”这样的人作宾语。"}, {"text": "这种坏习惯要禁用，不能再犯。", "explanation": "这里应该用〈杜绝〉。杜绝用于坏习惯、错误等，禁用指某物不能使用。"}, {"text": "那个黑帮已经被警方禁用。", "explanation": "这里应该用〈取缔〉。取缔用于组织、团伙，禁用用于物品或功能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禁用", "is_correct": true, "explanation": "正确：医生是让老人不再使用这种药，与“身体不好”的语境相符。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”是制造东西，医生不会让病人去生产药品，句意不通。"}, {"text": "研发", "is_correct": false, "explanation": "搭配：“研发”需要研究机构或专业人员，医生对病人这样说，搭配不当。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”是心理上的不喜欢，医生的指示是停止用药，与“讨厌”的意思不合。"}], "explanations": {"禁用": "正确：医生是让老人不再使用这种药，与“身体不好”的语境相符。", "生产": "语义：“生产”是制造东西，医生不会让病人去生产药品，句意不通。", "研发": "搭配：“研发”需要研究机构或专业人员，医生对病人这样说，搭配不当。", "讨厌": "语义：“讨厌”是心理上的不喜欢，医生的指示是停止用药，与“讨厌”的意思不合。"}, "sentence_index": 6, "correct_answer": "禁用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生禁用他喝酒，不让他抽烟。", "explanation": "这里应该用〈禁止〉。禁用的对象是物品、药品或功能，不能以人作宾语；“不让他……”应说“禁止”。"}, {"text": "消防员禁用大家进入火场。", "explanation": "这里应该用〈阻止〉。阻止可以针对人的行动，禁用用于物品或功能，不能用来限制人进入某地。"}, {"text": "大家禁用了那场争吵。", "explanation": "这里应该用〈制止〉。制止用于正在发生的争吵、打斗等行为，禁用指不准使用某物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个按钮暂时很禁用。", "corrected_sentence": "这个按钮暂时禁用。", "error_description": "副词错误：“禁用”是动词，前面不能加“很”。应说“暂时禁用”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个软件没禁用了，不能再打开。", "corrected_sentence": "这个软件禁用了，不能再打开。", "error_description": "否定形式错误：“没”与“了”不能同时用在动词前。错误的是“没禁用了”，肯定完成时说“禁用了”，否定时说“没禁用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
