INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25980, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "组成这个国家的各个地方或成员。", "primary_collocate": null, "pronunciation": "chéng yuán guó", "ipa": "ʈʂʰɤŋ˧˥ ɥɛn˧˥ kuɔ˧˥", "syllable_count": 3, "sentences": [{"text": "英国由四个成员国组成。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "苏格兰是英国的成员国之一。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "联合王国有四个成员国。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "威尔士也是英国的成员国。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "四个成员国都有自己的足球队。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "英国的每个成员国都有自己的旗子。", "target_word": "成员国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北爱尔兰是英国的一个成员国。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这四个成员国合起来叫英国。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "英国的成员国中，英格兰最大。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去过英国的三个成员国。", "target_word": "成员国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "成員國", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "组成联合王国等国家的各个部分，如英国的成员国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73af155f-4a0d-432b-a365-77d4bc223b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成员国", "is_correct": true, "explanation": "正确：英国由英格兰、苏格兰、威尔士、北爱尔兰四个组成部分构成，这些部分就是成员国。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：国家不是由大楼组成的，「大楼」与国家的组成部分无关，句意不通。"}, {"text": "公司", "is_correct": false, "explanation": "语义：国家不是由公司组成的，「公司」不能充当组成英国的部分。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：「家伙」是口语，指人，与书面语「组成」的语域和句意都不合。"}], "explanations": {"成员国": "正确：英国由英格兰、苏格兰、威尔士、北爱尔兰四个组成部分构成，这些部分就是成员国。", "大楼": "语义：国家不是由大楼组成的，「大楼」与国家的组成部分无关，句意不通。", "公司": "语义：国家不是由公司组成的，「公司」不能充当组成英国的部分。", "家伙": "语域：「家伙」是口语，指人，与书面语「组成」的语域和句意都不合。"}, "sentence_index": 0, "correct_answer": "成员国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班有四十个成员国。", "explanation": "这里应该用〈成员〉。班级的成员是学生，成员国指组成某个国家的地区，不能用于班级。"}, {"text": "这家公司有四个成员国。", "explanation": "这里应该用〈部门〉。成员国指组成国家的各个地方，公司的组成单位不是地方，应说〈部门〉。"}, {"text": "这个景点每年有一百万个成员国。", "explanation": "这里应该用〈游客〉。游客是来参观的人，成员国指组成某个国家的地区，不能用来数游客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成员国", "is_correct": true, "explanation": "正确：北爱尔兰是组成英国的一个地区，即一个成员国。"}, {"text": "首都", "is_correct": false, "explanation": "语义：北爱尔兰不是英国的首都，「首都」与句意矛盾。"}, {"text": "大学", "is_correct": false, "explanation": "语义：北爱尔兰是地区，不是大学，句意不通。"}, {"text": "窝", "is_correct": false, "explanation": "语域：「窝」是口语，还带有贬义色彩，不能用来指国家的组成部分。"}], "explanations": {"成员国": "正确：北爱尔兰是组成英国的一个地区，即一个成员国。", "首都": "语义：北爱尔兰不是英国的首都，「首都」与句意矛盾。", "大学": "语义：北爱尔兰是地区，不是大学，句意不通。", "窝": "语域：「窝」是口语，还带有贬义色彩，不能用来指国家的组成部分。"}, "sentence_index": 6, "correct_answer": "成员国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是足球队的成员国。", "explanation": "这里应该用〈队员〉。队员是球队里的人，成员国指组成某个国家的地区，不能用来指球队的人。"}, {"text": "这部剧有二十个成员国。", "explanation": "这里应该用〈演员〉。演员是演戏的人，成员国指组成某个国家的地区，不能用来数演员。"}, {"text": "这所学校有三千个成员国。", "explanation": "这里应该用〈学生〉。学生是在学校读书的人，成员国指组成某个国家的地区，不能用来数学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "英国由四个成员国们共同组成。", "corrected_sentence": "英国由四个成员国共同组成。", "error_description": "错误：在「成员国」后面加了「们」。「们」只用于指人的名词，「成员国」不能加「们」，应说「四个成员国」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "英国的四把成员国各自设有议会。", "corrected_sentence": "英国的四个成员国各自设有议会。", "error_description": "错误：量词用错了。「成员国」应用量词「个」，「把」用于有柄的器具，应说「四个成员国」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
