INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25982, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来装饭菜的盒子。", "primary_collocate": null, "pronunciation": "cān hé", "ipa": "tsʰan˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "学生们中午在教室里打开餐盒吃饭。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了一个新餐盒，每天带饭上班。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个餐盒有两层，可以放汤和菜。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完饭，我马上洗了餐盒。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "微波炉里不能放金属餐盒。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "餐盒的盖子坏了，菜汤流出来了。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐用不锈钢餐盒装午饭。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明忘了带餐盒，只好去食堂吃。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭店把外卖放进塑料餐盒里送来。", "target_word": "餐盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些餐盒洗干净后还可以再用。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "塑料餐盒", "label": "复合"}, {"form": "外卖餐盒", "label": "复合"}], "register": "中性", "sense_fingerprint": "装饭菜的盒子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '281d9421-fb6f-489e-9c50-1dff686839f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餐盒", "is_correct": true, "explanation": "“打开餐盒吃饭”符合语境，餐盒是盛放饭菜的容器。"}, {"text": "课本", "is_correct": false, "explanation": "语义：打开课本不能用来吃饭，句子不通。"}, {"text": "信封", "is_correct": false, "explanation": "语义：信封不能用来盛放饭菜，“打开信封吃饭”不成立。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“饮料”是饮用之物，不是盛饭的容器，“打开饮料吃饭”搭配不当。"}], "explanations": {"餐盒": "“打开餐盒吃饭”符合语境，餐盒是盛放饭菜的容器。", "课本": "语义：打开课本不能用来吃饭，句子不通。", "信封": "语义：信封不能用来盛放饭菜，“打开信封吃饭”不成立。", "饮料": "搭配：“饮料”是饮用之物，不是盛饭的容器，“打开饮料吃饭”搭配不当。"}, "sentence_index": 0, "correct_answer": "餐盒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房里用餐盒切菜。", "explanation": "这里应该用〈菜刀〉。切菜要用刀具，餐盒是盛放饭菜的盒子，不能用来切东西。"}, {"text": "他穿上了那个餐盒。", "explanation": "这里应该用〈衣服〉。穿是穿衣服的动作，要用于衣物；餐盒是盛放饭菜的盒子，不能穿在身上。"}, {"text": "我们去那家餐盒吃饭。", "explanation": "这里应该用〈餐厅〉。餐盒是盛放饭菜的盒子，不是吃饭的场所，“去……吃饭”要用餐厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餐盒", "is_correct": true, "explanation": "“用不锈钢餐盒装午饭”符合语境，不锈钢餐盒可以盛放饭菜。"}, {"text": "药瓶", "is_correct": false, "explanation": "语义：药瓶不是用来盛饭的，“用不锈钢药瓶装午饭”不成立。"}, {"text": "花盆", "is_correct": false, "explanation": "语义：花盆用于种植，不能用来装午饭，句子不通。"}, {"text": "布", "is_correct": false, "explanation": "搭配：“不锈钢”修饰的是金属器物，不能修饰布，搭配不当。"}], "explanations": {"餐盒": "“用不锈钢餐盒装午饭”符合语境，不锈钢餐盒可以盛放饭菜。", "药瓶": "语义：药瓶不是用来盛饭的，“用不锈钢药瓶装午饭”不成立。", "花盆": "语义：花盆用于种植，不能用来装午饭，句子不通。", "布": "搭配：“不锈钢”修饰的是金属器物，不能修饰布，搭配不当。"}, "sentence_index": 6, "correct_answer": "餐盒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他戴上餐盒看书。", "explanation": "这里应该用〈眼镜〉。戴在脸上的是眼镜，餐盒是盛放饭菜的盒子，不能戴在脸上。"}, {"text": "他开着餐盒去上班。", "explanation": "这里应该用〈汽车〉。开着去上班的是汽车等车辆，餐盒不能当交通工具开，这里词义用错了。"}, {"text": "她把餐盒插进插座充电。", "explanation": "这里应该用〈充电器〉。插进插座充电的是充电器或插头，餐盒不是电器，不能插入插座。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶给我装了一条餐盒，中午带着吃。", "corrected_sentence": "奶奶给我装了一个餐盒，中午带着吃。", "error_description": "量词错误：盛放饭菜的盒子应用“个”，“条”用于细长之物，不能用来数“餐盒”，应说“一个餐盒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐餐盒是蓝色的。", "corrected_sentence": "姐姐的餐盒是蓝色的。", "error_description": "领属“的”漏掉：表示所属应说“姐姐的餐盒”，不能说“姐姐餐盒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
