INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体上医生可以打针或者做检查的一个小点。", "primary_collocate": null, "pronunciation": "bǎ diǎn", "ipa": "pa²¹⁴ tjɛn²¹⁴", "syllable_count": 2, "sentences": [{"text": "医生在我的手臂上找了一个靶点。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打针以前，医生先找好靶点。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个靶点在肩膀上，打针不太疼。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士用笔在腿上画了靶点。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查的时候，医生按了按我背上的靶点。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腰上有一个靶点，要打针。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这个靶点要消毒。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "靶点找得准，打针就不会很疼。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩怕疼，医生轻轻碰了碰靶点。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做检查前，护士要先找到靶点。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "靶點", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "身体表面上医生打针或检查的小点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '281d9421-fb6f-489e-9c50-1dff686839f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "靶点", "is_correct": true, "explanation": "正确：「靶点」指医生打针或检查时选定的身体上的小点，与“找了一个”相符。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：「朋友」是人，不能在手臂上找到，填入后与“手臂”的语境矛盾。"}, {"text": "城市", "is_correct": false, "explanation": "语义：「城市」是地方，不能在手臂上找到，填入后句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「找了一个」后面接的是具体的物或人，不说“找了一个颜色”。"}], "explanations": {"靶点": "正确：「靶点」指医生打针或检查时选定的身体上的小点，与“找了一个”相符。", "朋友": "语义：「朋友」是人，不能在手臂上找到，填入后与“手臂”的语境矛盾。", "城市": "语义：「城市」是地方，不能在手臂上找到，填入后句意不通。", "颜色": "搭配：「找了一个」后面接的是具体的物或人，不说“找了一个颜色”。"}, "sentence_index": 0, "correct_answer": "靶点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生在我的腿上处理了靶点，然后包扎。", "explanation": "这里应该用〈伤口〉，表示受伤的部位；靶点是打针或检查时选定的小点，不能被处理、包扎。"}, {"text": "我们把靶点种在花园里，明年会开花。", "explanation": "这里应该用〈种子〉。靶点是身体上的小点，不能种在花园里；能种下去开花的是种子。"}, {"text": "护士在我的手臂上画了一只靶点。", "explanation": "这里应该用〈个〉。靶点用“个”作量词；“只”不用于这类身体上的小点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "靶点", "is_correct": true, "explanation": "正确：「靶点」指医生选定的身体上的打针点，与“医生说，这个……要消毒”的语境相符。"}, {"text": "亲戚", "is_correct": false, "explanation": "语义：「亲戚」是人，不能像器械或部位那样进行消毒，填入后句意与语境矛盾。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：「消毒」不能与“语言”搭配，“这个语言要消毒”不成立。"}, {"text": "星星", "is_correct": false, "explanation": "语义：「星星」在天上，不能被医生要求消毒，填入后与医疗语境矛盾。"}], "explanations": {"靶点": "正确：「靶点」指医生选定的身体上的打针点，与“医生说，这个……要消毒”的语境相符。", "亲戚": "语义：「亲戚」是人，不能像器械或部位那样进行消毒，填入后句意与语境矛盾。", "语言": "搭配：「消毒」不能与“语言”搭配，“这个语言要消毒”不成立。", "星星": "语义：「星星」在天上，不能被医生要求消毒，填入后与医疗语境矛盾。"}, "sentence_index": 6, "correct_answer": "靶点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生切除了靶点，病人恢复得很快。", "explanation": "这里应该用〈病灶〉，指病变的部位；靶点只是打针或检查时选定的小点，不能被切除。"}, {"text": "农民在靶点上种满了玉米。", "explanation": "这里应该用〈田地〉。种玉米的地方是田地，靶点是身体上的小点，不能用来种植。"}, {"text": "护士拿着靶点扎进去，病人很疼。", "explanation": "这里应该用〈针〉，指注射或扎进身体的器具；靶点是身体上的一个点，不能拿在手里扎进去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士在我的腿上找到了一只靶点。", "corrected_sentence": "护士在我的腿上找到了一个靶点。", "error_description": "“靶点”的量词应为“个”，“只”一般用于动物，不能用来数“靶点”，应改为“一个靶点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "护士找到了这些靶点们。", "corrected_sentence": "护士找到了这些靶点。", "error_description": "“靶点”是事物，不能加“们”表示复数，应删去“们”，说“这些靶点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9affae7e-c415-4850-84d6-4a2bebe3b2f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
