INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25988, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不让人用塑料袋。", "primary_collocate": null, "pronunciation": "jìn sù", "ipa": "tɕin˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市从今年一月开始禁塑，超市不再免费提供一次性塑料袋。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市禁塑后，大家都自己带购物袋。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定在全市禁塑。", "target_word": "禁塑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校已经禁塑了。", "target_word": "禁塑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保护海洋，很多国家都在禁塑。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店从上个月起禁塑，不再给顾客袋子。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想先在菜市场禁塑，不再发放塑料袋。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国南方的几个省已经禁塑了。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说该禁塑了，塑料袋太多了。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里也禁塑，请不要带塑料袋进来。", "target_word": "禁塑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "禁塑令", "label": "复合"}], "register": "中性", "sense_fingerprint": "不准人们使用塑料袋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4207cc0a-4bb8-4fbd-9cd2-7d60f346daa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25988, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "禁塑", "is_correct": true, "explanation": "正确。禁塑：不让人用塑料袋。"}, {"text": "近似", "is_correct": false, "explanation": "jìn sì（近似）与 jìn sù（禁塑）韵母不同（i 与 u），近似的意思是接近、相似。"}, {"text": "尽数", "is_correct": false, "explanation": "shù 与 sù 声母不同（sh 与 s），尽数的意思是全部、所有。"}, {"text": "竞速", "is_correct": false, "explanation": "jìng 与 jìn 韵尾不同（ng 与 n），竞速的意思是比赛速度。"}, {"text": "进驻", "is_correct": false, "explanation": "zhù 与 sù 声母不同（zh 与 s），进驻的意思是进入并驻扎。"}], "explanations": {"禁塑": "正确。禁塑：不让人用塑料袋。", "近似": "jìn sì（近似）与 jìn sù（禁塑）韵母不同（i 与 u），近似的意思是接近、相似。", "尽数": "shù 与 sù 声母不同（sh 与 s），尽数的意思是全部、所有。", "竞速": "jìng 与 jìn 韵尾不同（ng 与 n），竞速的意思是比赛速度。", "进驻": "zhù 与 sù 声母不同（zh 与 s），进驻的意思是进入并驻扎。"}, "sentence_index": null, "correct_answer": "禁塑"}, "level_3": {"options": [{"text": "禁塑", "is_correct": true, "explanation": "正确。“从今年一月开始禁塑”指开始实行不让人用塑料袋的措施。"}, {"text": "禁食", "is_correct": false, "explanation": "搭配：“禁食”指停止进食，主语应是人或动物，不能用于城市。"}, {"text": "禁足", "is_correct": false, "explanation": "语义：禁足指限制人的行动，不能说城市“从今年一月开始禁足”。"}, {"text": "禁锢", "is_correct": false, "explanation": "语义：禁锢指束缚限制，与城市实行的塑料袋管控不符。"}], "explanations": {"禁塑": "正确。“从今年一月开始禁塑”指开始实行不让人用塑料袋的措施。", "禁食": "搭配：“禁食”指停止进食，主语应是人或动物，不能用于城市。", "禁足": "语义：禁足指限制人的行动，不能说城市“从今年一月开始禁足”。", "禁锢": "语义：禁锢指束缚限制，与城市实行的塑料袋管控不符。"}, "sentence_index": 0, "correct_answer": "禁塑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校禁塑学生带手机进教室。", "explanation": "这里应该用〈禁止〉。禁止指一般性地不许做某事；禁塑只指不让人用塑料袋，不能用来禁止带手机。"}, {"text": "政府为了控制房价，决定禁塑住房。", "explanation": "这里应该用〈限购〉。限购指限制购买数量；禁塑只指不让人用塑料袋，不能用于住房。"}, {"text": "这名球员因为犯规，已经禁塑三场。", "explanation": "这里应该用〈禁赛〉。禁赛指停止参赛；禁塑只指不让人用塑料袋，不能用于比赛资格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禁塑", "is_correct": true, "explanation": "正确。“先在菜市场禁塑”指先在菜市场实行禁止用塑料袋的措施。"}, {"text": "禁赛", "is_correct": false, "explanation": "语义：禁赛指禁止参赛，与在菜市场做的事不搭。"}, {"text": "禁猎", "is_correct": false, "explanation": "搭配：“猎”搭配的对象是野生动物，不能与菜市场搭配。"}, {"text": "禁演", "is_correct": false, "explanation": "语义：禁演指禁止演出或放映，与菜市场不搭。"}], "explanations": {"禁塑": "正确。“先在菜市场禁塑”指先在菜市场实行禁止用塑料袋的措施。", "禁赛": "语义：禁赛指禁止参赛，与在菜市场做的事不搭。", "禁猎": "搭配：“猎”搭配的对象是野生动物，不能与菜市场搭配。", "禁演": "语义：禁演指禁止演出或放映，与菜市场不搭。"}, "sentence_index": 6, "correct_answer": "禁塑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校正在禁塑，只收费提供袋子。", "explanation": "这里应该用〈限塑〉。限塑指限制用量，收费仍可提供；禁塑指一律禁止，与收费提供矛盾。"}, {"text": "这条路因施工而禁塑。", "explanation": "这里应该用〈禁行〉。禁行指禁止车辆或行人通行；禁塑只指不让人用塑料袋，不能用于道路。"}, {"text": "这款饮料因含糖超标已经禁塑。", "explanation": "这里应该用〈禁售〉。禁售指不许销售；禁塑只指不让人用塑料袋，不能用于饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市已经很禁塑了。", "corrected_sentence": "这座城市已经禁塑了。", "error_description": "程度副词错误：“很”不能修饰动词“禁塑”，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们打算先在农贸市场禁塑了。", "corrected_sentence": "他们打算先在农贸市场禁塑。", "error_description": "体貌错误：“打算”表示将来的计划，“禁塑”尚未发生，不能加“了”，应去掉“了”，写作“他们打算先在农贸市场禁塑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
