INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "污染者就是弄脏环境的人或东西。", "primary_collocate": null, "pronunciation": "wū rǎn zhě", "ipa": "u˥ ʐan˨˩ ʈʂɤ˨˩", "syllable_count": 3, "sentences": [{"text": "弄脏河水的人是污染者。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排出黑烟，它就是空气的污染者。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乱扔垃圾的人也是污染者。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污染者要把脏东西清理干净。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小河的污染者找到了，是一家小工厂。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉我们，不要做环境的污染者。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污染者越多，我们的空气就越差。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的污染者留下了很多塑料瓶。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承认自己是这片草地的污染者，并道了歉。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污染者不清理，湖水就会越来越脏。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "弄脏环境的人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73af155f-4a0d-432b-a365-77d4bc223b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "污染者", "is_correct": true, "explanation": "正确：“污染者”指弄脏环境的人或东西，正好是“弄脏河水的人”。"}, {"text": "清洁工", "is_correct": false, "explanation": "语义：清洁工是去清理污物的人，恰好与“弄脏河水”相反。"}, {"text": "受害者", "is_correct": false, "explanation": "语义：受害者是遭受污染的一方，不会是弄脏河水的人。"}, {"text": "净化器", "is_correct": false, "explanation": "语义：净化器是用来清除污染的，不会弄脏河水，与句意相反。"}], "explanations": {"污染者": "正确：“污染者”指弄脏环境的人或东西，正好是“弄脏河水的人”。", "清洁工": "语义：清洁工是去清理污物的人，恰好与“弄脏河水”相反。", "受害者": "语义：受害者是遭受污染的一方，不会是弄脏河水的人。", "净化器": "语义：净化器是用来清除污染的，不会弄脏河水，与句意相反。"}, "sentence_index": 0, "correct_answer": "污染者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "污染者每天都在教室里讲课。", "explanation": "这里应该用〈老师〉。污染者指弄脏环境的人或东西，讲课的应说老师。"}, {"text": "污染者每天给客人剪头发。", "explanation": "这里应该用〈理发师〉。污染者指弄脏环境的人或东西，给客人剪头发的应说理发师。"}, {"text": "污染者在湖边救起了一个孩子。", "explanation": "这里应该用〈救生员〉。污染者不是救人的一方，救起孩子的应是救生员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "污染者", "is_correct": true, "explanation": "正确：“污染者越多”指弄脏空气的一方增加，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能说“越多”来导致空气变差，句子语义不通。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人的样子，不能说“外貌越多”让空气变差。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地理高度，与空气质量的变化没有这种关系。"}], "explanations": {"污染者": "正确：“污染者越多”指弄脏空气的一方增加，符合句意。", "天气": "语义：天气不能说“越多”来导致空气变差，句子语义不通。", "外貌": "体貌：“外貌”指人的样子，不能说“外貌越多”让空气变差。", "海拔": "语义：海拔是地理高度，与空气质量的变化没有这种关系。"}, "sentence_index": 6, "correct_answer": "污染者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位污染者的画很美，大家都想买。", "explanation": "这里应该用〈画家〉。污染者指弄脏环境的人或东西，画画的应说画家。"}, {"text": "这场比赛的污染者很公正，选手们都服气。", "explanation": "这里应该用〈裁判〉。污染者指弄脏环境的人或东西，主持比赛、判定公正的应说裁判。"}, {"text": "这位污染者写的小说很感人。", "explanation": "这里应该用〈作家〉。污染者指弄脏环境的人或东西，写小说的应说作家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他承认自己是一个很大污染者。", "corrected_sentence": "他承认自己是一个很大的污染者。", "error_description": "结构错误：“很大”修饰名词时要加“的”，应说“很大的污染者”，漏掉“的”就不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们找到了一座污染者，正在调查。", "corrected_sentence": "我们找到了一个污染者，正在调查。", "error_description": "量词错误：“污染者”应该用“个”，“座”多用于大型建筑或山，这里应改为“一个污染者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
