INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25998, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "想出一个东西的样子，然后把它做出来。", "primary_collocate": null, "pronunciation": "chǎn pǐn shè jì", "ipa": "ʈʂʰan˨˩ pʰin˨˩ ʂɤ˥˩ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "他的工作是产品设计，每天都在画新杯子。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子的产品设计很简单，也很好看。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做产品设计，要先想好东西给谁用。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在一家玩具公司做产品设计。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产品设计的第一步，是在纸上画出样子。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在为学校比赛做产品设计。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子的产品设计让坐的人很舒服。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产品设计做好以后，工厂才开始生产。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对产品设计很有兴趣，常常画新东西。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的产品设计，一看就知道怎么用。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "想出东西的样子并把它做出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73af155f-4a0d-432b-a365-77d4bc223b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产品设计", "is_correct": true, "explanation": "正确：“产品设计”是一种工作领域，与“每天都在画新杯子”的内容相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是报酬，不是工作的内容，不能说“他的工作是工资”。"}, {"text": "东西", "is_correct": false, "explanation": "语域：“东西”口语、泛指，不能清楚地说出一种工作，放在这里语域不对。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是工作，这句话无法读通。"}], "explanations": {"产品设计": "正确：“产品设计”是一种工作领域，与“每天都在画新杯子”的内容相符。", "工资": "语义：工资是报酬，不是工作的内容，不能说“他的工作是工资”。", "东西": "语域：“东西”口语、泛指，不能清楚地说出一种工作，放在这里语域不对。", "天气": "语义：天气不是工作，这句话无法读通。"}, "sentence_index": 0, "correct_answer": "产品设计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌是他的产品设计，旋律很感人。", "explanation": "这里应该用〈创作〉。产品设计指想出物品的样子并做出来，歌曲应说创作。"}, {"text": "这间教室的产品设计很漂亮，花了不少钱。", "explanation": "这里应该用〈装修〉。产品设计针对可以制造的物品，教室的布置应说装修。"}, {"text": "他把产品设计放进了厨房的冰箱。", "explanation": "这里把“产品设计”当成了可以放进冰箱的实物，但它指设计这项工作，不是实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产品设计", "is_correct": true, "explanation": "正确：“产品设计”是椅子的设计，能让坐的人感到舒服，与句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是椅子的一部分，这样读句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”属于人或动物的身体特征，不能说椅子的体重。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格只用于人，不能说椅子的性格让坐的人舒服。"}], "explanations": {"产品设计": "正确：“产品设计”是椅子的设计，能让坐的人感到舒服，与句意相符。", "天气": "语义：天气不是椅子的一部分，这样读句子不通。", "体重": "体貌：“体重”属于人或动物的身体特征，不能说椅子的体重。", "性格": "语义：性格只用于人，不能说椅子的性格让坐的人舒服。"}, "sentence_index": 6, "correct_answer": "产品设计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的产品设计很美，读起来很有节奏感。", "explanation": "这里应该用〈诗〉。产品设计指想出物品的样子并做出来，不能“读”，读起来有节奏感的应是诗。"}, {"text": "今天的产品设计很好，适合出门散步。", "explanation": "这里应该用〈天气〉。天气指空气与温度的状况，产品设计是设计过程，不能说适合出门。"}, {"text": "这次产品设计很丰盛，大家吃得很满足。", "explanation": "这里应该用〈聚餐〉。产品设计不是食物，丰盛、吃得满足的应说聚餐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一个很好产品设计。", "corrected_sentence": "她有一个很好的产品设计。", "error_description": "结构错误：“很好”修饰名词时要加“的”，应说“很好的产品设计”，漏掉“的”就不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们拿出一辆新的产品设计，大家都很喜欢。", "corrected_sentence": "他们拿出一个新的产品设计，大家都很喜欢。", "error_description": "量词错误：“产品设计”应该用“个”，“辆”只用于车辆，这里应改为“一个新的产品设计”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
