INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用来做塑料袋和塑料瓶的软软的、可以弯的材料。", "primary_collocate": null, "pronunciation": "jù yǐ xī", "ipa": "tɕy˥˩ i˨˩˦ ɕi˥", "syllable_count": 3, "sentences": [{"text": "这个塑料瓶是聚乙烯做的，捏一下就会变形。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚乙烯软软的，可以弯，也很轻。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一个聚乙烯做的小水桶。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的塑料袋都是聚乙烯做的。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚乙烯不会碎，小孩用着很放心。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杯子用聚乙烯做，掉在地上也不会破。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，聚乙烯比纸软，也比纸轻。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用聚乙烯做的袋子装水果。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚乙烯可以弯来弯去，所以适合做水管。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗发水的瓶子常常是聚乙烯做的，一捏就扁。", "target_word": "聚乙烯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高密度聚乙烯", "label": "复合"}, {"form": "聚乙烯薄膜", "label": "复合"}], "register": "中性", "sense_fingerprint": "又软又能弯的塑料材料，常做塑料袋和塑料瓶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4207cc0a-4bb8-4fbd-9cd2-7d60f346daa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聚乙烯", "is_correct": true, "explanation": "聚乙烯：名词，指又软又能弯的塑料材料，与“捏一下就会变形”相符。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃硬，不会因为捏一下就变形，与句中的描述矛盾。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁很硬，捏一下不会变形，与句意矛盾。"}, {"text": "陶瓷", "is_correct": false, "explanation": "搭配：“塑料瓶”的材料不说陶瓷，而且陶瓷也不会被捏变形。"}], "explanations": {"聚乙烯": "聚乙烯：名词，指又软又能弯的塑料材料，与“捏一下就会变形”相符。", "玻璃": "语义：玻璃硬，不会因为捏一下就变形，与句中的描述矛盾。", "钢铁": "语义：钢铁很硬，捏一下不会变形，与句意矛盾。", "陶瓷": "搭配：“塑料瓶”的材料不说陶瓷，而且陶瓷也不会被捏变形。"}, "sentence_index": 0, "correct_answer": "聚乙烯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只聚乙烯。", "explanation": "这里应该用〈块〉。聚乙烯是材料，不用“只”计量，“只”一般用于动物或个体物品。"}, {"text": "他们吃了一大碗聚乙烯。", "explanation": "聚乙烯是塑料，不能食用，这里不能当作食物来吃。"}, {"text": "这些聚乙烯是我的好朋友。", "explanation": "聚乙烯是材料，不能指人，这里不能用来称呼朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚乙烯", "is_correct": true, "explanation": "聚乙烯：名词，指又软又轻的塑料，与“比纸软，也比纸轻”的描述相符。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头比纸硬，也不比纸轻，与句中“比纸软”的比较矛盾。"}, {"text": "铁", "is_correct": false, "explanation": "语义：铁很硬，并不比纸软，与句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“软”一般不用来形容石头的质地，这里不能说石头比纸软。"}], "explanations": {"聚乙烯": "聚乙烯：名词，指又软又轻的塑料，与“比纸软，也比纸轻”的描述相符。", "木头": "语义：木头比纸硬，也不比纸轻，与句中“比纸软”的比较矛盾。", "铁": "语义：铁很硬，并不比纸软，与句意矛盾。", "石头": "搭配：“软”一般不用来形容石头的质地，这里不能说石头比纸软。"}, "sentence_index": 6, "correct_answer": "聚乙烯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在聚乙烯里举行了婚礼。", "explanation": "聚乙烯是材料，不是场所，不能作为举行婚礼的地点，这个词不这么用。"}, {"text": "妈妈每天给聚乙烯浇水施肥。", "explanation": "聚乙烯是塑料，不是植物，不需要浇水施肥，这里用法不对。"}, {"text": "他把这块聚乙烯读完了，还写了读后感。", "explanation": "聚乙烯是材料，不是书籍，不能用“读完”来说，这个词不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个袋子是被聚乙烯做的，很轻。", "corrected_sentence": "这个袋子是用聚乙烯做的，很轻。", "error_description": "错误：用“被”引出做材料的“聚乙烯”不自然。正确：材料应用“用”引出，写作“这个袋子是用聚乙烯做的，很轻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人用一个聚乙烯做了一个大箱子。", "corrected_sentence": "工人用聚乙烯做了一个大箱子。", "error_description": "错误：“聚乙烯”是材料，前面不能加“一个”这类量词。正确：直接说“工人用聚乙烯做了一个大箱子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3583dc-0574-4fcf-9610-406ca8cc0070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
