INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26008, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "情绪很高，很激动。", "primary_collocate": null, "pronunciation": "gāo áng", "ipa": "kɑʊ˥ ɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "比赛开始前，球员们士气高昂。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他热情高昂地向大家介绍了新计划。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队赢了以后，球迷们兴致高昂。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们斗志高昂地出发了。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演讲时，他的情绪越来越高昂。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游团的游客们情绪高昂，一路说笑。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的鼓励让我们的学习热情更高昂了。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很累，但是大家的精神依然高昂。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到出发的消息，孩子们的情绪立刻高昂起来。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队员们整天训练，却始终保持着高昂的士气。", "target_word": "高昂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "士气高昂", "label": "复合"}, {"form": "斗志高昂", "label": "复合"}, {"form": "情绪高昂", "label": "复合"}], "register": "中性", "sense_fingerprint": "情绪、士气、斗志很高涨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ab76373-a806-4838-933e-5ef3747780ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高昂", "is_correct": true, "explanation": "正确。“士气高昂”形容精神饱满、情绪高涨，符合比赛前的语境。"}, {"text": "高明", "is_correct": false, "explanation": "语义：“高明”形容技艺或见识出众，不能形容“士气”。"}, {"text": "高速", "is_correct": false, "explanation": "搭配：“高速”说速度，不能说士气高速。"}, {"text": "高深", "is_correct": false, "explanation": "语义：“高深”形容学问或道理深奥，与“士气”不搭。"}], "explanations": {"高昂": "正确。“士气高昂”形容精神饱满、情绪高涨，符合比赛前的语境。", "高明": "语义：“高明”形容技艺或见识出众，不能形容“士气”。", "高速": "搭配：“高速”说速度，不能说士气高速。", "高深": "语义：“高深”形容学问或道理深奥，与“士气”不搭。"}, "sentence_index": 0, "correct_answer": "高昂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的气温很高昂。", "explanation": "这里应该用〈高〉。高昂形容情绪、激动的心情，不能用来说气温。"}, {"text": "她的书法很高昂，很多人都来请教。", "explanation": "这里应该用〈高明〉。高昂形容情绪，不能用来说书法的水平，形容技艺要用“高明”。"}, {"text": "他的个子很高昂。", "explanation": "这里应该用〈高〉。高昂形容情绪、士气，不能描述身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高昂", "is_correct": true, "explanation": "正确。“热情更高昂了”表示情绪比之前更高涨，符合鼓励后的语境。"}, {"text": "高超", "is_correct": false, "explanation": "搭配：“高超”修饰技艺，不能修饰“热情”。"}, {"text": "高傲", "is_correct": false, "explanation": "语义：“高傲”形容态度自大，与“鼓励”带来的积极情绪相反。"}, {"text": "高雅", "is_correct": false, "explanation": "语义：“高雅”形容格调文雅，不能形容学习热情。"}], "explanations": {"高昂": "正确。“热情更高昂了”表示情绪比之前更高涨，符合鼓励后的语境。", "高超": "搭配：“高超”修饰技艺，不能修饰“热情”。", "高傲": "语义：“高傲”形容态度自大，与“鼓励”带来的积极情绪相反。", "高雅": "语义：“高雅”形容格调文雅，不能形容学习热情。"}, "sentence_index": 6, "correct_answer": "高昂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批产品的质量很高昂，客户都很满意。", "explanation": "这里应该用〈好〉。高昂形容情绪，不能用来形容产品的质量，形容质量要用“好”。"}, {"text": "这场晚会的观众人数很高昂，场面很热闹。", "explanation": "这里应该用〈众多〉。高昂形容情绪，不能用来形容人数的多少，这里要用“众多”。"}, {"text": "周末的高昂时段，商场里很挤。", "explanation": "这里应该用〈高峰〉。高昂形容情绪，不能用来形容人流最多的时段，这里要用“高峰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们热情高昂的参加了运动会。", "corrected_sentence": "学生们热情高昂地参加了运动会。", "error_description": "结构助词误用：修饰动词“参加”的状语要用“地”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到胜利的消息，球迷们的兴致立刻高昂下来。", "corrected_sentence": "听到胜利的消息，球迷们的兴致立刻高昂起来。", "error_description": "趋向补语误用：“高昂”表示情绪上升，应该用“起来”，“下来”表示下降，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：“模糊”与“清晰”构成反义，指看不清、听不清或思路不清。"}, {"text": "温暖", "is_correct": false, "explanation": "无关：“温暖”说温度或情感，与“清晰”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：“高兴”说心情，与“清晰”没有反义关系。"}, {"text": "香甜", "is_correct": false, "explanation": "无关：“香甜”说味道，与“清晰”没有反义关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：“模糊”与“清晰”构成反义，指看不清、听不清或思路不清。", "温暖": "无关：“温暖”说温度或情感，与“清晰”没有反义关系。", "高兴": "无关：“高兴”说心情，与“清晰”没有反义关系。", "香甜": "无关：“香甜”说味道，与“清晰”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：“模糊”与“清晰”构成反义，指看不清、听不清或思路不清。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：“柔软”说质地，与“清晰”没有反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "无关：“辽阔”说范围广大，与“清晰”没有反义关系。"}, {"text": "温和", "is_correct": false, "explanation": "无关：“温和”说性情或气候，与“清晰”没有反义关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：“模糊”与“清晰”构成反义，指看不清、听不清或思路不清。", "柔软": "无关：“柔软”说质地，与“清晰”没有反义关系。", "辽阔": "无关：“辽阔”说范围广大，与“清晰”没有反义关系。", "温和": "无关：“温和”说性情或气候，与“清晰”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很清楚，容易看明白。", "primary_collocate": null, "pronunciation": "qīng xī", "ipa": "tɕʰiŋ˥ ɕi˥", "syllable_count": 2, "sentences": [{"text": "这张照片很清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音非常清晰，我听得懂。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里的声音不太清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机拍的照片很清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲得很清晰，大家都明白了。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法很清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的空气好，远处的树看得很清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那张地图画得清晰，我一看就懂。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的电视画面不清晰。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话清晰，每个字都听得见。", "target_word": "清晰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清晰度", "label": "复合"}, {"form": "清晰地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "形容声音、图像、思路等很清楚，容易看明白或听明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4246d07b-ae3c-4f25-9405-93e74c5a5c69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清晰", "is_correct": true, "explanation": "正确：“清晰”形容照片的图像清楚，可以说“这张照片很清晰”。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”说声音或环境没有噪音，不能用来形容照片。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”说声音，照片不能说响亮。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，与照片的清楚与否无关。"}], "explanations": {"清晰": "正确：“清晰”形容照片的图像清楚，可以说“这张照片很清晰”。", "安静": "语义：“安静”说声音或环境没有噪音，不能用来形容照片。", "响亮": "搭配：“响亮”说声音，照片不能说响亮。", "甜": "语义：“甜”说味道，与照片的清楚与否无关。"}, "sentence_index": 0, "correct_answer": "清晰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天的天气很清晰，适合出去玩。", "explanation": "这里应该用〈晴朗〉。清晰指图像、声音或思路清楚，天空和天气要说晴朗。"}, {"text": "听到这个消息，她的心情很清晰。", "explanation": "这里应该用〈平静〉。心情是内心的状态，要说平静；清晰只用于能被看清或听清的事物。"}, {"text": "这个孩子的个子很清晰，比同学高出一头。", "explanation": "这里应该用〈高〉。身高要说高；清晰只用于能被看清或听清的事物或思路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清晰", "is_correct": true, "explanation": "正确：“清晰”说远处的树看得分明，符合句意。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”说味道或辛苦，不能用来形容看树的清楚程度。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容质地，“看得很硬”不能成立。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”说分量或心情，与看树的状态不相干。"}], "explanations": {"清晰": "正确：“清晰”说远处的树看得分明，符合句意。", "苦": "语义：“苦”说味道或辛苦，不能用来形容看树的清楚程度。", "硬": "搭配：“硬”形容质地，“看得很硬”不能成立。", "沉重": "语义：“沉重”说分量或心情，与看树的状态不相干。"}, "sentence_index": 6, "correct_answer": "清晰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "阳光很清晰，照得人睁不开眼。", "explanation": "这里应该用〈明亮〉。清晰说的是能被看清的图像、声音或思路，阳光的强弱要说明亮。"}, {"text": "这朵花的香气很清晰，远远就能闻到。", "explanation": "这里应该用〈浓郁〉。清晰只用于能被看清或听清的事物或思路，花香要说浓郁。"}, {"text": "微风很清晰，吹在脸上很舒服。", "explanation": "这里应该用〈轻柔〉。微风的轻软感觉要说轻柔，清晰只用于能被看清或听清的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这张照片拍很清晰。", "corrected_sentence": "他把这张照片拍得很清晰。", "error_description": "状态补语错误：“拍”和“很清晰”之间要用“得”连接，应说“拍得很清晰”，不能说“拍很清晰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一段清晰地录音。", "corrected_sentence": "这是一段清晰的录音。", "error_description": "的地误用：修饰名词“录音”要用“的”，应说“清晰的录音”；“地”只用于修饰动词，“清晰地录音”不能修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
